[1452]={"Rhapsodys Kalimdor-Cocktail","Rhapsody Shindigger im Hinterland möchte, dass Ihr ihm 3 Muskelmägen eines Roc, 3 Groddoc-Lebern und 3 Eisenfelllebern bringt."},
[1469]={"Rhapsodys Geschichte","Bringt das Schrifttafelfragment der Atal'ai zu Brohann Caskbelly in Stormwind."},
