[1651]={"Der Foliant der Ehre","Verteidigt Daphne Stilwell vor dem Angriff der Defias. Keiner Eurer Geister darf aus seinen irdischen Fesseln befreit werden, wenn Ihr erfolgreich sein wollt. Sprecht erneut mit Daphne Stilwell, wenn Ihr erfolgreich wart."},
[1652]={"Der Foliant der Ehre","Sprecht mit Duthorian Rall in Stormwind."},
[1653]={"Die Prüfung der Rechtschaffenheit","Sprecht mit Jordan Stilwell in Ironforge."},
[1654]={"Die Prüfung der Rechtschaffenheit","Sucht mit Jordans Waffennotizen etwas Weißsteineichenholz, Bailors aufbereitete Erzlieferung, Jordans Schmiedehammer und einen Kor-Edelstein und bringt alles zusammen zu Jordan Stilwell in Ironforge."},
[1740]={"Die Kugel von Soran'ruk","Sucht 3 Soran'ruk-Fragmente und 1 großes Soran'ruk-Fragment und bringt sie zu Doan Karhan im Brachland."},
[1806]={"Die Prüfung der Rechtschaffenheit","Wartet, bis Jordan Stilwell eine Waffe für Euch geschmiedet hat."},
[1956]={"Macht in Uldaman","Beschafft Euch eine Obsidiankraftquelle und bringt sie in die Marschen von Dustwallow zu Tabetha."},
[2040]={"Unterirdischer Angriff","Holt das Gnoam-Sprecklesprocket aus den Todesminen und bringt es Shoni der Schtillen in Stormwind."},
[2198]={"Die zerrissene Halskette","Sucht nach dem Erschaffer der zerrissenen Halskette, um etwas über ihren möglichen Wert zu erfahren."},
[2199]={"Lehren haben ihren Preis","Bringt fünf Silberbarren zu Talvash del Kissel in Ironforge."},
[2200]={"Rückkehr nach Uldaman","Sucht in Uldaman nach Hinweisen auf den momentanen Zustand von Talvashs Halskette. Der getötete Paladin, den Talvash erwähnte, hatte die Kette zuletzt."},
[2201]={"Suche nach den Edelsteinen","Findet den Rubin, den Saphir und den Topas, die in ganz Uldaman verstreut sind. Wenn Ihr sie habt, wendet Euch aus der Ferne an Talvash del Kissel, indem Ihr die Wahrsagephiole nutzt, die er Euch zuvor gegeben hat. Aus dem Tagebuch, wisst Ihr... * Der Rubin wurde in einer Bastion der Zwerge der Schattenschmiede versteckt. * Der Topas steckt in einer Urne in einem der Trogg-Gebiete, in der Nähe einiger Zwerge der Allianz. * Der Saphir wurde von Grimlok, dem Anführer der Troggs, mitgenommen."},
[2202]={"Reagenzsuche in Uldaman","Bringt 12 magenta Funguskappen nach Kargath zu Jarkal Mossmeld."},
[2204]={"Restaurierung der Halskette","Besorgt Euch eine Kraftquelle vom mächtigsten Konstrukt, das Ihr in Uldaman finden könnt, und liefert sie bei Talvash del Kissel in Ironforge ab."},
[2240]={"Die geheime Kammer","Lest Baelogs Tagebuch, erforscht die geheime Kammer und erstattet dann Ausgrabungsleiter Stormpike Bericht."},
[2258]={"Reagenzien-Suche im Ödland","Bringt Jarkal Mossmeld in Kargath im Ödland 5 Bussard-Mägen, 10 Klippenkojoten-Fangzähne und 5 Felselementarsplitter."},
[2278]={"Die Platinscheiben","Sprecht mit dem Steinbehüter und findet heraus, welche uralten Lehren er aufbewahrt. Sobald Ihr alles erfahren habt, was er weiß, aktiviert die Scheiben von Norgannon."},
[2280]={"Die Platinscheiben","Bringt die Miniaturausgabe der Scheiben von Norgannon zu einem der Weisen von Thunder Bluff."},
[2283]={"Wiederbeschaffung der Halskette","Sucht in der Grabungsstätte von Uldaman nach einer wertvollen Halskette und bringt sie nach Orgrimmar zu Dran Droffers. Die Halskette ist vielleicht beschädigt."},
[2284]={"Wiederbeschaffung der Halskette, Teil 2","Sucht in den Tiefen von Uldaman nach einem Hinweis auf den Verbleib der Edelsteine."},
[2318]={"Übersetzung des Tagebuchs","Sucht jemanden, der das Tagebuch des Paladins übersetzen kann. Der nächstgelegene Ort, wo Ihr so jemanden finden könntet, ist Kargath im Ödland."},
[2338]={"Übersetzung des Tagebuchs","Leiht Jarkal die Halskette. Im Gegenzug wird er das Tagebuch für Euch übersetzen."},
[2339]={"Findet die Edelsteine und die Kraftquelle","Beschafft in Uldaman alle drei Edelsteine sowie eine Kraftquelle für die Halskette und bringt sie anschließend zu Jarkal Mossmeld nach Kargath. Jarkal glaubt, dass sich eine Kraftquelle vielleicht im stärksten Konstrukt in Uldaman findet. Aus dem Tagebuch, wisst Ihr... * Der Rubin wurde in einer Bastion der Zwerge der Schattenschmiede versteckt. * Der Topas steckt in einer Urne in einem der Trogg-Gebiete, in der Nähe einiger Zwerge der Allianz. * Der Saphir wurde von Grimlok, dem Anführer der Troggs, mitgenommen."},
[2342]={"Wiederbeschaffte Schätze","Holt Patrick Garretts Familienschatz aus der Truhe der Familie in der südlichen Bankenhalle von Uldaman und bringt diesen zu ihm nach Undercity."},
[2398]={"Die verschollenen Zwerge","Sucht in Uldaman nach Baelog."},
[2418]={"Kraftsteine","Bringt Rigglefuzz im Ödland 8 Kraftsteine aus Dentrium und 8 Kraftsteine aus An'Alleum."},
[2500]={"Reagenzien-Suche im Ödland","Beschafft die Reagenzien, die Ghak Healtouch aus dem Ödland braucht, und bringt sie ihm nach Thelsamar."},
[2768]={"Wünschel-mato-Rute","Bringt die Wünschel-mato-Rute nach Gadgetzan zu Chefingenieur Bilgewhizzle."},
[2770]={"Gahz'rilla","Bringt Wizzle Brassbolts in der schimmernden Ebene Gahz'rillas energiegeladene Schuppe."},
[2841]={"Maschinenkriege","Besorgt die Maschinenblaupausen und Thermapluggs Safekombination aus Gnomeregan und bringt sie zu Nogg nach Orgrimmar."},
[2842]={"Chefingenieur Scooty","Sprecht mit Scooty in Booty Bay."},
[2843]={"Gnomer-weeeeg!","Wartet, bis Scooty den Goblin-Transponder kalibriert hat."},
[2846]={"Tiara der Tiefen","Bringt die Tiara der Tiefen zu Tabetha in den Marschen von Dustwallow."},
[2865]={"Skarabäuspanzerschalen","Bringt Tran’rek in Gadgetzan 5 unbeschädigte Skarabäuspanzerschalen."},
[2904]={"Eine schöne Bescherung","Begleitet Kernobee zur Uhrwerkgasse und meldet Euch dann wieder bei Scooty in Booty Bay."},
[2922]={"Rettet Techbots Hirn!","Bringt Techbots Speicherkern zu Tüftlermeister Overspark nach Ironforge."},
[2924]={"Grundlegende Artifixe","Bringt Klockmort Spannerspan in Ironforge 12 grundlegende Artifixe."},
[2926]={"Gnogaine","Sammelt mit der leeren bleiernen Sammelphiole radioaktive Ablagerungen bestrahlter Eindringlinge oder Plünderer. Sobald sie voll ist, bringt Ihr sie zu Ozzie Togglevolt nach Kharanos zurück."},
[2928]={"Gyrobohrmatische Exkavation","Bringt 24 robomechanische Innereien zu Shoni nach Stormwind."},
[2929]={"Der große Verrat","Reist nach Gnomeregan und tötet Robogenieur Thermaplugg. Kehrt zu Hochtüftler Mekkatorque zurück, wenn der Auftrag ausgeführt ist."},
[2930]={"Datenrettung","Bringt Mechanikermeister Castpipe in Ironforge eine Prismalochkarte."},
[2933]={"Giftflaschen","Bringt eine Giftflasche zu einem Apotheker nach Tarrens Mühle."},
[2934]={"Unbeschädigter Giftbeutel","Bringt Apotheker Lydon in Tarrens Mühle einen unbeschädigten Giftbeutel."},
[2935]={"Konsultiert Meister Gadrin","Sprecht mit Meister Gadrin in Sen'jin."},
[2936]={"Der Spinnengott","Lest von der Schrifttafel des Theka, um den Namen des Spinnengottes der Witherbark zu erfahren, und kehrt dann zu Meister Gadrin zurück."},
[2945]={"Schmutzverkrusteter Ring","Findet einen Weg, den schmutzverkrusteten Ring zu säubern."},
[2947]={"Die Rückkehr des Rings","Ihr könnt den Ring entweder behalten oder die Person finden, die für die Prägung und Gravuren auf der Innenseite des Rings verantwortlich ist."},
[2948]={"Gnomen-Verbesserungen","Bringt Talvash del Kissel in Ironforge den glänzenden Goldring, einen Silberbarren, einen Moosachat und 30 Silbermünzen."},
[2949]={"Die Rückkehr des Rings","Ihr könnt den Ring entweder behalten oder die Person finden, die für die Prägung und Gravuren auf der Innenseite des Rings verantwortlich ist."},
[2950]={"Noggs Ringerneuerung","Bringt Nogg in Orgrimmar den glänzenden Goldring, einen Silberbarren, einen Moosachat und 30 Silbermünzen."},
[2951]={"Der Funkelmat 5200!","Gebt einen schmutzverkrusteten Gegenstand in den Funkelmat 5200 und stellt sicher, dass Ihr drei Silbermünzen habt, um die Maschine zu aktivieren."},
[2962]={"Das einzige Heilmittel ist mehr grünes Leuchten","Reist nach Gnomeregan und bringt etwas von der hoch konzentrierten radioaktiven Ablagerung zurück. Seid gewarnt, die Ablagerung ist instabil und wird ziemlich schnell zerfallen. Ozzie wird außerdem Eure schwere bleierne Phiole benötigen, nachdem die Aufgabe erledigt ist."},
[2988]={"Käfige der Witherbark","Durchsucht die Käfige in den beiden Dörfern der Witherbark und kehrt dann zu Greifenmeister Talonaxe zurück."},
[2989]={"Der Altar von Zul","Überprüft die Oberfläche des Altars von Zul und kehrt dann zu Greifenmeister Talonaxe zurück."},
[2990]={"Thadius Grimshade","Bringt Scharfschnabels Feder zu Thadius Grimshade in die verwüsteten Lande."},
[2991]={"Nekrums Medaillon","Bringt Thadius Grimshade in den verwüsteten Landen Nekrums Medaillon."},
[3042]={"Trollaushärter","Bringt 20 Phiolen Trollaushärter zu Trenton Lighthammer in Gadgetzan."},
[3341]={"Das Ende bringen","Andrew Brownell will, dass Ihr Amnennar den Kältebringer tötet und ihm dessen Schädel bringt."},
[3373]={"Die Essenz des Eranikus","Legt die Essenz von Eranikus in den Essenzborn, der sich in dem Versunkenen Tempel in seinem Unterschlupf befindet."},
[3444]={"Der runde Stein","Holt den runden Stein aus Marvon Rivetseekers Werkstatt in Ratchet."},
[3446]={"In die Tiefen","Sucht den Altar von Hakkar im Versunkenen Tempel in den Sümpfen des Elends."},
[3447]={"Das Geheimnis des Kreises","Reist zum Versunkenen Tempel und enthüllt das Geheimnis, das sich in dem Kreis der Statuen verbirgt."},
[3520]={"Kreischergeister","Fangt die Geister von 3 Kreischern in Feralas ein und kehrt dann zu Yeh'kinya in Steamwheedle zurück."},
[3523]={"Geißel der Niederungen","Wenn Ihr Belnistrasz helfen wollt, sprecht noch einmal mit ihm und übergebt ihm den Schwurstein, den er Euch gab."},
[3525]={"Ausschalten des Götzen","Begleitet Belnistrasz zum Götzen der Stacheleber in den Hügeln von Razorfen. Beschützt Belnistrasz, während er das Ritual durchführt, um den Götzen auszuschalten."},
[3527]={"Die Prophezeiung von Mosh'aru","Bringt die erste und die zweite Mosh'aru-Schrifttafel zu Yeh'kinya nach Tanaris."},
[3528]={"Der Gott Hakkar","Bringt das gefüllte Ei von Hakkar zu Yeh'kinya nach Tanaris."},
[3636]={"Das Licht bringen","Erzbischof Benedictus will, dass Ihr Amnennar den Kältebringer in den Hügeln von Razorfen tötet."},
[3701]={"Die glimmenden Ruinen von Thaurissan","Begebt Euch zu den Ruinen von Thaurissan in der brennenden Steppe und sammelt Informationen über die Thaurissan-Relikte. Kehrt zur königlichen Historikerin Archesonus zurück, wenn Ihr die Informationen besorgt habt."},
[3702]={"Die glimmenden Ruinen von Thaurissan","Hört die Erzählung der königlichen Historikerin Archesonus über die Geschichte von Thaurissan."},
[3765]={"Verderbnis in der Fremde","Reist zu Gershala Nightwhisper in Auberdine."},
[3801]={"Dunkeleisenerbe","Sprecht mit Franclorn Forgewright, wenn Ihr daran interessiert seid, einen Schlüssel für die Hauptstadt zu erhalten."},
[3802]={"Dunkeleisenerbe","Erschlagt Fineous Darkvire und bergt den großen Hammer Ironfel. Bringt Ironfel zum Schrein von Thaurissan und legt ihn auf die Statue von Franclorn Forgewright."},
[3906]={"Disharmonie der Flamme","Reist zum Steinbruch am Blackrock und tötet Übermeister Pyron. Kehrt zu Thunderheart zurück, sobald Ihr den Auftrag erledigt habt."},
[3907]={"Disharmonie des Feuers","Betretet die Blackrocktiefen und spürt Lord Incendius auf. Tötet ihn und bringt jegliche Informationsquelle, die Ihr finden könnt, zu Thunderheart."},
[3981]={"Kommandant Gor'shak","Sucht Kommandant Gor'shak in den Blackrocktiefen. Ihr erinnert Euch, dass auf dem primitiv gezeichneten Bild des Orcs auch Gitter vor dem Gesicht zu sehen waren. Vielleicht solltet Ihr nach einer Art Gefängnis suchen."},
[3982]={"Was ist los?","Verteidigt Gor'shak."},
[4001]={"Was ist los?","Sprecht mit Kharan Mighthammer und sammelt Informationen über die Entführung von Prinzessin Moira Bronzebeard. Bringt diese Informationen dann zu Thrall nach Orgrimmar. Ihr erinnert Euch, dass Gor'shak gesagt hat, Kharan werde in einer Zelle in seiner Nähe festgehalten."},
[4002]={"Das östliche Königreich","Sprecht mit Thrall, wenn Ihr bereit seid, die von ihm geplante Mission zu übernehmen."},
[4003]={"Die königliche Rettung","Tötet Imperator Dagran Thaurissan und befreit Prinzessin Moira Bronzebeard von seinem bösen Zauber."},
[4022]={"Eine Kostprobe der Flamme","Zeigt Cyrus Therepentous die abgestreifte Haut des schwarzen Drachenschwarms, die Ihr von Kalaran Windblade erhalten habt."},
[4024]={"Eine Kostprobe der Flamme","Begebt Euch in die Blackrocktiefen und tötet Bael'Gar. Ihr wisst lediglich, dass der Riese irgendwo in den Blackrocktiefen haust. Vergesst nicht, die veränderte Haut des schwarzen Drachenschwarms mit Bael'Gars Überresten zu benutzen und damit die feurige Essenz einzufangen. Bringt die eingeschlossene feurige Essenz zu Cyrus Therepentous zurück."},
[4061]={"Aufstieg der Maschinen","Begebt Euch in die brennende Steppe und beschafft für Theodora Mulvadania 10 gerissene Elementarsplitter. Euch fällt ein, dass Theodora gesagt hat, die Golems und Elementare in der Gegend seien eine gute Quelle für solche Splitter."},
[4062]={"Aufstieg der Maschinen","Bringt die Elementarsplitterprobe zu Lotwil Veriatus. Ihr erinnert Euch, dass Theodora sagte, Lotwil sei in einem Lager im Osten stationiert."},
[4063]={"Aufstieg der Maschinen","Sucht und tötet Golemlord Argelmach. Bringt Lotwil seinen Kopf. Außerdem müsst Ihr 10 intakte Elementarkerne von den Wuthäschergolems und Kriegshetzerkonstrukten, die Argelmach beschützen, beschaffen. Das wisst Ihr, weil Ihr übernatürliche Fähigkeiten habt."},
[4081]={"SOFORT TÖTEN: Dunkeleisenzwerge","Begebt Euch in die Blackrocktiefen und vernichtet die üblen Aggressoren! Kriegsherr Goretooth möchte, dass Ihr 15 Gardisten der Zorneshämmer, 10 Aufseher der Zorneshämmer und 5 Fußsoldaten der Zorneshämmer tötet. Kehrt zu ihm zurück, sobald Ihr die Aufgabe erfüllt habt."},
[4082]={"SOFORT TÖTEN: Hochrangige Führungskräfte der Dunkeleisenzwerge","Begebt Euch in die Blackrocktiefen und vernichtet die üblen Aggressoren! Kriegsherr Goretooth möchte, dass Ihr 10 Sanitäter der Zorneshämmer, 10 Soldaten der Zorneshämmer und 10 Offiziere der Zorneshämmer tötet. Kehrt zu ihm zurück, sobald Ihr die Aufgabe erfüllt habt."},
[4083]={"Der spektrale Kelch"},
[4121]={"Gefährliche Zwickmühle","Eskortiert Euren Gefangenen, Grark Lorkrub, durch die brennende Steppe und durch den Blackrock in die sengende Schlucht. Euch fällt ein, dass Lexlort gesagt hat, seine Männer würden auf der anderen Seite warten, um Grark in Gewahrsam zu nehmen. Ihr werdet außerdem Eure Thoriumfesseln an Lexlort übergeben müssen."},
[4122]={"Grark Lorkrub","Begebt Euch in die brennende Steppe und sucht Grark Lorkrub. Ihr erinnert Euch, dass Lexlort gesagt hat, er sei zuletzt in einer großen Festung der Blackrock gesehen worden. Wenn Ihr Grark Lorkrub gefunden habt, verwendet die Thoriumfesseln, um ihn zu binden, und bringt ihn dann über den Blackrock in die sengende Schlucht zurück. Lexlorts Männer werden auf der anderen Seite warten, um Grark in Gewahrsam zu nehmen."},
[4123]={"Das Herz des Berges","Bringt das 'Herz des Berges' zu Maxwort Uberglint in der brennenden Steppe."},
[4126]={"Hurley Pestatem","Bringt Ragnar Donnerbräu in Kharanos das gestohlene Donnerbräurezept."},
[4132]={"Operation: Tod dem Zornesschmied","Begebt Euch zu den Blackrocktiefen und eliminiert General Zornesschmied! Kehrt zum Kriegsherrn Goretooth zurück, sobald Ihr diese Aufgabe erledigt habt."},
[4134]={"Verlorenes Donnerbräurezept","Bringt Vivian Lagrave in Kargath das gestohlene Donnerbräurezept."},
[4136]={"Ribbly Screwspigot","Bringt Yuka Screwspigot in der brennenden Steppe Ribblys Kopf."},
[4141]={"Muigin und Larion","Sammelt 15 Blutblüten und kehrt zu Muigin zurück."},
[4142]={"Ein Besuch bei Gregan","Bringt Gregan Brewspewer in Feralas eine Blutblüte."},
[4143]={"Der Dunst des Bösen","Sammelt 5 Proben Dunst der Atal'ai und bringt sie Muigin im Un'Goro Krater."},
[4145]={"Larion und Muigin","Jagt 5 Blutblütenpeitscher, 5 Blutblütendrescher, 5 Blutblütenschinder und 5 Blutblütenfallen für Larion in Marshals Zuflucht."},
[4146]={"Schrumpf-Treibstoff","Bringt Larion in Marshals Zuflucht den ungeladenen Schrumpfer und 5 Proben Dunst der Atal'ai."},
[4147]={"Marvons Werkstatt","Reist zu Marvon Rivetseekers Werkstatt in Ratchet."},
[4182]={"Drachkin-Bedrohung","Erschlagt 15 schwarze Brutlinge, 10 Exemplare der schwarzen Großdrachenbrut, 4 schwarze Wyrmkin und 1 Schwarzdrachen. Kehrt zu Helendis Riverhorn zurück, sobald die Aufgabe erledigt ist."},
[4183]={"Die wahren Meister","Reist nach Seenhain und händigt Magistrat Solomon Helendis Riverhorns Brief aus."},
[4184]={"Die wahren Meister","Reist nach Stormwind und tragt Solomons Hilfegesuch dem Hochlord Bolvar Fordragon vor. Bolvar residiert in der Burg Stormwind."},
[4185]={"Die wahren Meister","Sprecht zuerst mit Lady Katrana Prestor, dann mit Hochlord Bolvar Fordragon."},
[4186]={"Die wahren Meister","Händigt Bolvars Erlass an Magistrat Solomon in Seenhain aus."},
[4201]={"Der Liebestrank","Bringt 4 Gromsblut-Kräuter, 10 Riesensilbervenen und Nagmaras gefüllte Phiole zu Herrin Nagmara in den Blackrocktiefen."},
[4223]={"Die wahren Meister","Sprecht mit Marshal Maxwell in der brennenden Steppe."},
[4224]={"Die wahren Meister","Sprecht mit dem struppigen John, um etwas über Marshal Windsors Schicksal zu erfahren, und kehrt dann zu Marshal Maxwell zurück, wenn Ihr diese Aufgabe erledigt habt. Ihr erinnert Euch daran, dass Marshal Maxwell Euch geraten hat, ihn in einer Höhle im Norden zu suchen."},
[4241]={"Marshal Windsor","Reist zum Blackrock im Nordwesten und dann weiter zu den Blackrocktiefen. Findet heraus, was aus Marshal Windsor geworden ist. Ihr erinnert Euch daran, dass der struppige John sagte, man hätte Windsor in ein Gefängnis verschleppt."},
[4242]={"Verlorene Hoffnung","Überbringt Marshal Maxwell die schlechten Neuigkeiten."},
[4262]={"Übermeister Pyron","Erschlagt Übermeister Pyron und kehrt dann zu Jalinda Sprig zurück. Ihr erinnert Euch an Jalindas Worte, dass Pyron den Steinbruch bewachen würde. Vielleicht solltet Ihr dort nachsehen?"},
[4263]={"Incendius!","Sucht Lord Incendius in den Blackrocktiefen und vernichtet ihn!"},
[4264]={"Eine zusammengeknüllte Notiz","Soeben seid Ihr auf etwas gestoßen, das Marshal Windsor mit Sicherheit sehr interessiert. Vielleicht besteht ja doch noch Hoffnung."},
[4282]={"Ein Funken Hoffnung","Holt Marshal Windsors verloren gegangene Informationen zurück. Marshal Windsor glaubt, dass sich die Informationen in den Händen des Golemlords Argelmach und des Generals Zornesschmied befinden."},
[4286]={"Feine Sachen","Reist in die Blackrocktiefen und holt 20 Dunkeleisengürteltaschen. Kehrt zu Oralius zurück, sobald die Aufgabe erledigt ist. Ihr nehmt an, dass die Dunkeleisenzwerge in den Blackrocktiefen diese 'Gürteltaschen'-Dinger tragen."},
[4322]={"Gefängnisausbruch!","Helft Marshal Windsor, seine Ausrüstung zurückzuholen und seine Freunde zu befreien. Kehrt zu Marshal Windsor zurück, wenn Ihr Erfolg hattet."},
[4341]={"Kharan Mighthammer","Begebt Euch in die Blackrocktiefen und findet Kharan Mighthammer. Der König erwähnte, dass Kharan dort gefangen sei - vielleicht solltet Ihr nach einem Gefängnis Ausschau halten."},
[4342]={"Kharans Geschichte","Lasst Kharan Mighthammer seine Geschichte erzählen."},
[4361]={"Der Überbringer schlechter Botschaften...","Kehrt nach Ironforge zurück und überbringt König Magni Bronzebeard die schlechten Nachrichten."},
[4362]={"Das Schicksal des Königreichs","Kehrt in die Blackrocktiefen zurück und rettet Prinzessin Moira Bronzebeard aus den Fängen des bösen Imperators Dagran Thaurissan."},
[4701]={"Stellt sie ab","Begebt Euch zur Blackrockspitze und vernichtet die Quelle der Bedrohung durch die Worgs. Als Ihr Helendis verlasst, ruft er Euch noch einen Namen hinterher: Halycon. Darauf beziehen sich die Orcs im Zusammenhang mit den Worgs."},
[4724]={"Die Herrin der Meute","Erschlagt Halycon, die Rudelführerin der Worgs der Blutäxte."},
[4726]={"Brutlingessenz","Bringt 8 Brutlingessenzen sowie den Draco-Incarcinatrix 900 zu Tinkee Steamboil am Flammenkamm in der brennenden Steppe."},
[4729]={"Kiblers Exotische Tiere","Begebt Euch zur Blackrockspitze und sucht Worgwelpen der Blutäxte. Benutzt den Käfig, um die wilden kleinen Bestien zu transportieren. Bringt einen eingesperrten Worgwelpen zu Kibler."},
[4734]={"Ei-Frosten","Benutzt den Prototyp des Eiszilloskops an einem Ei im Horst."},
[4735]={"Eiersammlung","Bringt 8 eingesammelte Dracheneier sowie das kollektronische Modul zu Tinkee Steamboil am Flammenkamm in der brennenden Steppe."},
[4742]={"Siegel des Aufstiegs","Sucht die drei Edelsteine der Befehlsgewalt: den Edelstein der Gluthauer, den Edelstein der Felsspitzoger und den Edelstein der Blutäxte. Bringt sie zusammen mit dem unverzierten Siegel des Aufstiegs zu Vaelan zurück. Vaelan nannte Euch auch die Namen der drei Generäle: Kriegsmeister Voone von den Gluthauern, Hochlord Omokk von den Felsspitzogern und Oberanführer Wyrmthalak von den Blutäxten."},
[4764]={"Doomriggers Schnalle","Bringt Mayara Brightwing in der brennenden Steppe Doomriggers Schnalle."},
[4768]={"Die Darkstone-Schrifttafel","Bringt der Schattenmagierin Vivian Lagrave in Kargath die Darkstone-Schrifttafel."},
[4771]={"Dämmerungstrickfalle","Legt die Dämmerungstrickfalle in den Vorführraum von Scholomance. Besiegt Vectus und kehrt dann zu Betina Bigglezink zurück."},
[4787]={"Das uralte Ei","Bringt das uralte Ei zu Yeh'kinya nach Tanaris."},
[4788]={"Die letzten Schrifttafeln","Bringt Ausgrabungsleiter Ironboot in Tanaris die fünfte und sechste Schrifttafel von Mosh'aru."},
[4808]={"Felnok Steelspring","Gebt Felnok Steelspring Tinkees Brief."},
[4809]={"Hörner der Eiswindschimären","Bringt Felnok Steelspring 8 unbeschädigte Hörner einer Eiswindschimäre."},
[4810]={"Rückkehr zu Tinkee","Bringt Tinkee Steamboil in der brennenden Steppe Felnoks Päckchen."},
[4862]={"Be-Öh-Es-Eh","Reist zur Blackrockspitze und sammelt 15 Spitzenspinnen-Eier für Kibler. Logischerweise müsstet Ihr diese Eier in der Nähe von Spinnen finden."},
[4866]={"Muttermilch","Ihr findet Mutter Glimmernetz im Herzen der Blackrockspitze. Kämpft mit ihr und bringt sie dazu, Euch zu vergiften. Es kann gut sein, dass Ihr sie sogar töten müsst. Kehrt zum struppigen John zurück, sobald Ihr vergiftet seid, damit er Euch 'melken' kann."},
[4867]={"Urok Schreckensbote","Lest Waroshs Rolle. Bringt Waroshs Mojo zu Warosh."},
[4903]={"Befehl des Kriegsherrn","Tötet Hochlord Omokk, Kriegsmeister Voone und Oberanführer Wyrmthalak. Findet die wichtigen Blackrockdokumente. Kehrt zum Kriegsherrn Goretooth nach Kargath zurück, sobald Ihr diese Mission erledigt habt."},
[4907]={"Tinkee Steamboil","Sprecht mit Tinkee Steamboil."},
[4941]={"Eitriggs Weisheit","Sprecht mit Etrigg in Orgrimmar. Wenn Ihr die Angelegenheit mit Etrigg besprochen habt, bittet Thrall um Rat. Ihr erinnert Euch, dass Ihr Etrigg in Thralls Gemächern gesehen habt."},
[4974]={"Für die Horde!","Begebt Euch zur Blackrockspitze und tötet den Kriegshäuptling Rend Blackhand. Nehmt seinen Kopf und kehrt nach Orgrimmar zurück."},
[4981]={"Agentin Bijou","Begebt Euch zur Blackrockspitze und findet heraus, was aus Bijou geworden ist."},
[4982]={"Bijous Habseligkeiten","Sucht Bijous Habseligkeiten und bringt sie ihr. Ihr erinnert Euch daran, dass sie erwähnte, ihre Sachen auf der untersten Ebene der Stadt versteckt zu haben."},
[4983]={"Bijous Aufklärungsbericht","Bringt Bijous Aufklärungsbericht zu Großmeister Lexlort nach Kargath."},
[5001]={"Bijous Habseligkeiten","Sucht Bijous Habseligkeiten und bringt sie ihr. Viel Glück!"},
[5002]={"Nachricht an Maxwell","Begebt Euch in die brennende Steppe und leitet Bijous Informationen an Marshal Maxwell weiter."},
[5047]={"Pip Quickwit, zu Euren Diensten!","Sprecht mit Malyfous Darkhammer in Everlook."},
[5065]={"Die verlorenen Schrifttafeln von Mosh'aru","Bringt Ausgrabungsleiter Ironboot in Tanaris die dritte und vierte Schrifttafel von Mosh'aru."},
[5081]={"Maxwells Mission","Reist zur Blackrockspitze und schaltet Kriegsmeister Voone, Hochlord Omokk und Oberanführer Wyrmthalak aus. Kehrt zu Marshal Maxwell zurück, wenn Eure Aufgabe erledigt ist."},
[5089]={"General Drakkisaths Befehl","Bringt den Befehl von General Drakkisath zu Marshal Maxwell in der brennenden Steppe."},
[5102]={"General Drakkisaths Niedergang","Begebt Euch zur Blackrockspitze und schaltet General Drakkisath aus. Kehrt zu Marshal Maxwell zurück, wenn Eure Aufgabe erledigt ist."},
[5122]={"Das Medaillon des Glaubens"},
[5125]={"Aurius' Abrechnung"},
[5127]={"Die Dämonenschmiede","Begebt Euch zur Blackrockspitze und sucht Goraluk Hammerbruch. Erschlagt ihn und wendet dann die blutbefleckte Pike auf seine Leiche an. Nachdem seine Seele abgesaugt wurde, wird die Pike seelenbefleckt sein. Ihr müsst außerdem die ungeschmiedete runenbedeckte Brustplatte finden. Bringt die seelenbefleckte Pike und die ungeschmiedete runenbedeckte Brustplate zu Lorax in Winterspring."},
[5160]={"Die oberste Beschützerin","Begebt Euch nach Winterspring und sucht Haleh. Gebt ihr Awbees Schuppe."},
[5212]={"Das Fleisch lügt nicht","Sammelt 20 verseuchte Fleischproben in Stratholme und bringt sie zu Betina Bigglezink zurück. Ihr vermutet, dass Ihr besagte Fleischproben bei jeder Kreatur in Stratholme finden könnt."},
[5213]={"Der aktive Wirkstoff","Reist nach Stratholme und durchsucht die Ziggurats. Sucht neue Geißeldaten und bringt sie zu Betina Bigglezink zurück."},
[5214]={"Der große Ezra Grimm","Sucht Ezra Grimms Raucherladen in Stratholme und bergt einen Kasten von Grimms Tollem Tabak. Kehrt zu Smokey LaRue zurück, wenn Eure Aufgabe erledigt ist."},
[5243]={"Häuser der Heiligen","Begebt Euch nach Stratholme im Norden. Durchsucht die Vorratskisten, die über die Stadt verstreut sind, und holt 5 Einheiten Heiliges Wasser von Stratholme. Kehrt zu Leonid Barthalomew dem Geachteten zurück, wenn Ihr genug der gesegneten Flüssigkeit gesammelt habt."},
[5244]={"Die Ruinen von Kel'Theril","Sprecht mit Jaron Stoneshaper in Starfall."},
[5245]={"Die gequälten Seelen von Kel'Theril","Benutzt Jarons Hacke, um die vier Fragmente des Hochgeborenenrelikts zu suchen. Bringt sie zu Aurora Skycaller in den Östlichen Pestländern."},
[5246]={"Fragmente der Vergangenheit","Sucht die hochheiligen Schriften der Hochgeborenen im Tempel von Zin-Malor in Azshara und bringt sie zu Aurora Skycaller beim Nordpassturm in den östlichen Pestländern."},
[5247]={"Fragmente der Vergangenheit","Bringt einen verzauberten Thoriumbarren, 5 Kristallflicker und eine Phiole mit Düsterwasser zu Aurora Skycaller beim Nordpassturm in den östlichen Pestländern."},
[5251]={"Der Archivar","Reist nach Stratholme und sucht Archivar Galford vom Scharlachroten Kreuzzug. Vernichtet ihn und verbrennt das Scharlachrote Archiv."},
[5262]={"Die Wahrheit zeigt sich mit Macht","Bringt den Kopf von Balnazzar zu Fürst Nicholas Zverenhoff in den Östlichen Pestländern."},
[5263]={"Übertroffen","Zieht nach Stratholme und vernichtet Baron Rivendare. Nehmt seinen Kopf und kehrt zu Fürst Nicholas Zverenhoff zurück."},
[5281]={"Die ruhelosen Seelen","Sucht Egan. Ihr wisst nur, dass er zuletzt in der Nähe von Stratholme gesehen wurde."},
[5282]={"Die ruhelosen Seelen","Wendet Egans Blaster auf die geisterhaften und spektralen Bürger von Stratholme an. Wenn die ruhelosen Geister ihre geisterhaften Hüllen sprengen, wendet den Blaster erneut an - dann sind sie endlich frei! Befreit 15 ruhelose Seelen und kehrt zu Egan zurück."},
[5341]={"Das Familienvermögen der Barovs","Begebt Euch zur Scholomance und holt das Familienvermögen der Barovs zurück. Dieses Vermögen besteht aus vier Besitzurkunden: Es sind die Besitzurkunde für Caer Darrow, die Besitzurkunde für Brill, die Besitzurkunde für Tarrens Mühle und die Besitzurkunde für Southshore. Kehrt zu Alexi Barov zurück, sobald die Aufgabe erledigt ist."},
[5343]={"Das Familienvermögen der Barovs","Begebt Euch zur Scholomance und holt das Familienvermögen der Barovs zurück. Dieses Vermögen besteht aus vier Besitzurkunden: Es sind die Besitzurkunde für Caer Darrow, die Besitzurkunde für Brill, die Besitzurkunde für Tarrens Mühle und die Besitzurkunde für Southshore. Kehrt zu Weldon Barov zurück, sobald die Aufgabe erledigt ist."},
[5382]={"Doktor Theolen Krastinov, der Schlächter","Sucht Doktor Theolen Krastinov in der Scholomance. Vernichtet ihn, verbrennt dann die Überreste von Eva Sarkhoff und die Überreste von Lucien Sarkhoff. Kehrt zu Eva Sarkhoff zurück, sobald Ihr die Aufgabe erfüllt habt."},
[5384]={"Kirtonos der Herold","Kehrt mit dem Blut Unschuldiger zur Scholomance zurück. Sucht die Veranda und legt das Blut der Unschuldigen in die Kohlenpfanne. Kirtonos wird kommen, um sich von Eurer Seele zu nähren. Kämpft tapfer, gebt keinen Fußbreit nach! Vernichtet Kirtonos und kehrt zu Eva Sarkhoff zurück."},
[5461]={"Der Mensch Ras Frostraunen","Reist in das Arathihochland zu den Ruinen von Stromgarde. Durchsucht Stromgarde nach einem Andenken der Erinnerung. Wenn Ihr einen solchen Gegenstand findet, kehrt mit ihm zu Magistrat Marduke zurück."},
[5462]={"Der Sterbende Ras Frostraunen","Reist zur Hoffnung des Lichts in den Östlichen Pestländern und sucht Leonid Barthalomew den Geachteten auf. Zeigt ihm das Andenken der Erinnerung und berichtet ihm alles, was Ihr entdeckt habt."},
[5463]={"Menethils Geschenk","Begebt Euch nach Stratholme und sucht Menethils Geschenk. Platziert das Andenken der Erinnerung auf dem unheiligen Boden."},
[5464]={"Menethils Geschenk","Bringt das seelengebundene Andenken zu Leonid Barthalomew in den Östlichen Pestländern."},
[5465]={"Seelengebundenes Andenken","Kehrt zu Magistrat Marduke in Caer Darrow zurück. Zeigt ihm das seelengebundene Andenken."},
[5466]={"Der Lich Ras Frostraunen","Sucht Ras Frostraunen in der Scholomance. Wenn Ihr ihn gefunden habt, wendet das seelengebundene Andenken auf sein untotes Antlitz an. Solltet Ihr ihn erfolgreich in einen Sterblichen zurückverwandeln können, dann schlagt ihn nieder und nehmt den menschlichen Kopf von Ras Frostraunen an Euch. Bringt den Kopf zu Magistrat Marduke."},
[5515]={"Krastinovs Tasche der Schrecken","Sucht nach Jandice Barov in der Scholomance und vernichtet sie. Entnehmt ihrer Leiche Krastinovs Tasche der Schrecken. Bringt die Tasche zu Eva Sarkhoff."},
[5522]={"Leonid Barthalomew","Bringt die gefrorenen Eier zu Leonid Barthalomew in den Östlichen Pestländern."},
[5526]={"Die Splitter der Teufelsranke","Sucht die Teufelsranke in Düsterbruch und nehmt einen Teufelsrankensplitter mit Euch. Aller Wahrscheinlichkeit nach, werdet Ihr Alzzin den Wildformer töten müssen, um an die Teufelsranke zu gelangen. Benutzt das Requiliar der Reinheit, um darin den Splitter sicher zu versiegeln und bringt das versiegelte Reliquiar zu Rabine Saturna in Nighthaven, Moonglade."},
[5527]={"Ein Reliquiar der Reinheit","Reist nach Silithus und sucht in den Ruinen des Südwindpostens nach einem Reliquiar der Reinheit. Sollte Eure Suche Erfolg haben, kehrt zu Rabine Saturna in Nighthaven, Moonglade zurück."},
[5529]={"Verseuchte Jungtiere","Tötet 20 verseuchte Jungtiere und kehrt dann zu Betina Bigglezink bei der Kapelle des hoffnungsvollen Lichts zurück."},
[5531]={"Betina Bigglezink","Bringt die gefrorenen Eier zu Betina Bigglezink."},
[5533]={"Scholomance","Sprecht mit Alchimist Arbington an der Chillwindspitze, Westliche Pestländer."},
[5722]={"Die Suche nach dem verloren gegangenen Ranzen","Sucht im Ragefireabgrund nach Maur Grimmtotems Leiche und durchsucht sie nach interessanten Gegenständen."},
[5723]={"Die Kraft des Feindes wird auf die Probe gestellt","Sucht in Orgrimmar nach dem Ragefireabgrund, tötet dann 8 Ragefire-Troggs und 8 Ragefire-Schamanen und kehrt anschließend zu Rahauro in Thunder Bluff zurück."},
[5724]={"Wiederbeschaffung des verloren gegangenen Ranzens","Bringt den Grimmtotemranzen zu Rahauro nach Thunder Bluff."},
[5725]={"Die Macht der Zerstörung...","Bringt die Bücher 'Schattenzauber' und 'Zauberformeln aus dem Nether' zu Varimathras nach Undercity."},
[5726]={"Verborgene Feinde","Bringt die Insignie eines Offiziers zu Thrall nach Orgrimmar."},
[5727]={"Verborgene Feinde","Bringt Neeru Fireblade die Insignie des Offiziers und sprecht mit ihm. Seht, ob er Euch glaubt, dass Ihr ein Mitglied der Burning Blade seid, und kehrt dann zu Thrall nach Orgrimmar zurück."},
[5728]={"Verborgene Feinde","Tötet Bazzalan und Jergosh den Herbeirufer, bevor Ihr zu Thrall nach Orgrimmar zurückkehrt."},
[5761]={"Vernichtung der Bestie","Begebt Euch in den Ragefireabgrund und erschlagt Taragaman den Hungerleider. Bringt anschließend dessen Herz zu Neeru Fireblade nach Orgrimmar."},
[5848]={"Von Liebe und Familie","Begebt Euch nach Stratholme im nördlichen Teil der Pestländer. In der scharlachroten Bastion findet Ihr das Gemälde 'Von Liebe und Familie', das zwischen anderen Gemälden versteckt ist und auf dem die Zwillingsmonde unserer Welt abgebildet sind. Bringt das Gemälde zu Tirion Fordring."},
[6022]={"Töten zu einem bestimmten Zweck","Begebt Euch zu Corins Kreuzung im Osten und besiegt die Mitglieder der Geißel, die in der Stadt leben. Sammelt 7 Stücke lebendige Fäulnis in unter 10 Minuten. Zerstoßt die lebendige Fäulnis mit Mörser und Stößel zu geronnener Fäulnis."},
[6042]={"Die kleinen Ärgernisse des Un-Lebens","Erschlagt 20 giftige Seuchenfledermäuse und 10 monströse Seuchenfledermäuse. Kehrt zu Nathanos Blightcaller zurück, wenn Ihr fertig seid."},
[6133]={"Das Ersuchen des Waldläuferlords","Begebt Euch zur nördlichsten Grenze der Östlichen Pestländer und bringt die Quel'Thalas-Registratur zurück. Der Gegenstand befindet sich irgendwo in der Quel'Lithien-Lodge. Außerdem müsst Ihr 8 Waldläufer, 8 Pfadschreiter und 8 Waldarbeiter töten."},
[6135]={"Dämmerschwinge, oh, wie ich Euch hasse...","Sucht Dämmerschwinge und tötet ihn. Nehmt ein Büschel vom Fell Dämmerschwinges und bringt es zu Nathanos Blightcaller. Man sagt, dass Dämmerschwinge nördlich von hier durch das Land streift."},
[6136]={"Der Korpulente","Sucht in den nördlichen Wüsten der Östlichen Pestländer nach Blutschlinger und vernichtet ihn. Kehrt zu Nathanos Blightcaller zurück, sobald Ihr diese Mission erledigt habt."},
[6163]={"Ramstein","Reist nach Stratholme und tötet Ramstein den Würger. Bringt seinen Kopf als Souvenir zu Nathanos."},
[6402]={"Treffen in Stormwind","Reist nach Stormwind und begebt Euch zu den Stadttoren. Sprecht mit Knappe Rowe, damit er Marshal Windsor über Eure Ankunft informiert."},
[6403]={"Die große Maskerade","Folgt Reginald Windsor durch Stormwind. Schützt ihn vor Gefahren!"},
[6501]={"Das Großdrachenauge","Ihr müsst die Welt nach jemandem absuchen, der fähig ist, die Macht des Fragments des Großdrachenauges wieder herzustellen. Die einzige Information, die Ihr über ein solches Wesen besitzt ist, dass es existiert."},
[6502]={"Drachenfeueramulett","Ihr müsst das Blut des schwarzen Großdrachen-Helden von General Drakkisath bekommen. Ihr findet Drakkisath in seinem Thronsaal hinter den Hallen des Aufstiegs auf der Blackrockspitze."},
[6521]={"Eine unheilige Allianz","Bringt den Kopf von Botschafter Malcin zu Varimathras nach Undercity."},
[6522]={"Eine unheilige Allianz","Bringt die kleine Rolle zu Varimathras nach Undercity."},
[6561]={"Blackfathom-Schurkerei","Bringt den Kopf des Twilight-Lords Kelris zu Bashana Runetotem in Thunder Bluff."},
[6562]={"Ärger in der Tiefe","Sprecht in Ashenvale mit Je'neu Sancrea."},
[6563]={"Die Essenz von Aku'mai","Bringt 20 Saphire von Aku'mai zu Je'neu Sancrea nach Ashenvale."},
[6564]={"Treue zu den Alten Göttern","Bringt die durchfeuchtete Notiz zu Je'neu Sancrea nach Ashenvale."},
[6565]={"Treue zu den Alten Göttern","Tötet Lorgus Jett in der Blackfathom-Tiefe und kehrt dann zu Je'neu Sancrea nach Ashenvale zurück."},
[6566]={"Was der Wind erzählt","Hört Thrall zu."},
[6567]={"Der Champion der Horde","Sucht Rexxar auf. Der Kriegshäuptling hat Euch erklärt, wo Ihr ihn finden könnt. Sucht die Wege von Desolace zwischen dem Steinkrallengebirge und Feralas ab."},
[6568]={"Nachricht von Rexxar","Überbringt Myranda der Vettel in den westlichen Pestländern Rexxars Nachricht."},
[6569]={"Oculus-Illusionen","Reist zur Blackrockspitze und sammelt 20 schwarze Drachenbrutaugen. Kehrt zu Myranda der Vettel zurück, sobald Ihr die Aufgabe erfüllt habt."},
[6570]={"Aschenschwinge","Reist zum Drachensumpf in den Marschen von Dustwallow und begebt Euch in Aschenschwinges Bau. Sobald Ihr darin seid, tragt das Amulett der drachischen Subversion und sprecht mit Aschenschwinge."},
[6582]={"Die Prüfung der Schädel, Scryer","Ihr müsst Scryer, den Champion der blauen Großdrachen, finden und ihn töten. Schlagt seinem Kadaver den Schädel ab und bringt ihn zu Aschenschwinge. Ihr wisst, dass Scryer in Winterspring zu finden ist."},
[6583]={"Die Prüfung der Schädel, Somnus","Vernichtet den Drachenchampion des grünen Drachenschwarms, Somnus. Nehmt seinen Schädel und bringt ihn zu Aschenschwinge zurück."},
[6584]={"Die Prüfung der Schädel, Chronalis","Chronalis, ein Kind Nozdormus, bewacht die Höhlen der Zeit in der Tanariswüste. Vernichtet ihn und bringt seinen Schädel zu Aschenschwinge."},
[6585]={"Die Prüfung der Schädel, Axtroz","Begebt Euch nach Grim Batol und spürt Axtroz auf, den Drachenchampion des Roten Drachenschwarms. Vernichtet ihn und nehmt seinen Schädel. Bringt den Schädel zu Aschenschwinge zurück."},
[6601]={"Aufstieg...","Mir scheint, als sei die Charade jetzt vorüber. Ihr wisst, dass das Amulett der drachischen Unterwanderung, das Myranda die Vettel für Euch erschuf, auf der Blackrockspitze nicht funktioniert. Vielleicht solltet Ihr Rexxar aufsuchen und ihm Eure Notlage erklären. Zeigt ihm das glanzlose Drachenfeueramulett. Er wird hoffentlich wissen, was als Nächstes zu tun ist."},
[6602]={"Blut des schwarzen Großdrachen-Helden","Begebt Euch zur Blackrockspitze und tötet General Drakkisath. Sammelt sein Blut und bringt es zu Rexxar."},
[6626]={"Ein Hort des Bösen","Tötet 8 Schlachtwachen von Razorfen, 8 Dornenwirker von Razorfen und 8 Kultistinnen der Totenköpfe und kehrt dann zu Myriam Moonsinger nahe dem Eingang zu den Hügeln von Razorfen zurück."},
[6627]={"Test der Lehre","Beantwortet Braug Dimspirits Frage richtig und sprecht dann erneut mit ihm. Er wird immer noch im Steinkrallengebirge sein, wenn Ihr bereit seid."},
[6628]={"Test der Lehre","Beantwortet Parqual Fintallas' Frage richtig und sprecht dann erneut mit ihm. Er wird immer noch in Undercity sein, wenn Ihr bereit seid."},
[6642]={"Gunst der Bruderschaft, Dunkeleisenerz"},
[6643]={"Gunst der Bruderschaft, Feuerkern"},
[6644]={"Gunst der Bruderschaft, Lavakern"},
[6645]={"Gunst der Bruderschaft, Kernhäute"},
[6646]={"Gunst der Bruderschaft, Blut des Berges"},
[6804]={"Vergiftetes Wasser","Wendet den Aspekt von Neptulon auf die vergifteten Elementare der östlichen Pestländer an. Bringt 12 disharmonische Armschienen, sowie den Aspekt von Neptulon zu Fürst Hydraxis in Azshara."},
[6805]={"Stürmer und Rumpler","Tötet 15 Staubstürmer und 15 Wüstenrumpler und kehrt dann zu Fürst Hydraxis in Azshara zurück."},
[6821]={"Auge des Glutsehers","Bringt das Auge des Glutsehers zu Fürst Hydraxis in Azshara."},
[6822]={"Der geschmolzene Kern","Tötet 1 Feuerlord, 1 geschmolzenen Riesen, 1 uralten Kernhund sowie 1 Lavawoger und kehrt dann zu Fürst Hydraxis in Azshara zurück."},
[6823]={"Agent von Hydraxis","Verdient Euch eine geehrte Fraktion bei den hydraxianischen Wasserlords und sprecht dann mit Fürst Hydraxis in Azshara."},
[6824]={"Hände des Feindes","Bringt die Hände von Lucifron, Sulfuron, Gehennas und Shazzrah zu Fürst Hydraxis in Azshara."},
[6921]={"Inmitten der Ruinen","Bringt den Fathom-Kern zu Je'neu Sancrea im Zoram'gar-Außenposten in Ashenvale."},
[6922]={"Baron Aquanis","Bringt die seltsame Wasserkugel zu Je'neu Sancrea im Zoram'gar-Außenposten in Ashenvale."},
[6981]={"Der leuchtende Splitter","Begebt Euch nach Ratchet, um jemanden zu finden, der Euch mehr über den leuchtenden Splitter sagen kann. Liefert dann den Splitter ab, wie Ihr angewiesen wurdet."},
[7028]={"Dunkles Böses","Sammelt 25 theradrische Kristallschnitzereien für Willow in Desolace."},
[7029]={"Schlangenzunges Verderbnis","Füllt die beschichtete himmelblaue Phiole am orangefarbenen Kristallteich in Maraudon. Benutzt die gefüllte himmelblaue Phiole mit den Schlangenstrunkranken, damit der verderbte Noxxious-Spross herausgezwungen wird. Heilt 8 Pflanzen, indem Ihr diesen Noxxious-Spross tötet und kehrt dann zu Vark Battlescar in Shadowprey zurück."},
[7041]={"Schlangenzunges Verderbnis","Füllt die beschichtete himmelblaue Phiole am orangefarbenen Kristallteich in Maraudon. Benutzt die gefüllte himmelblaue Phiole mit den Schlangenstrunkranken, damit der verderbte Noxxious-Spross herausgezwungen wird. Heilt 8 Pflanzen, indem Ihr diesen Noxxious-Spross tötet und kehrt dann zu Talendria an der Nijelspitze zurück."},
[7044]={"Legenden von Maraudon","Beschafft die beiden Teile des Szepters von Celebras: den Celebriangriff und den Celebriandiamanten. Findet einen Weg, um mit Celebras zu sprechen."},
[7046]={"Das Szepter von Celebras","Helft Celebras dem Erlösten, während er das Szepter von Celebras herstellt. Sprecht mit ihm, nachdem das Ritual vollendet ist."},
[7064]={"Verderbnis von Erde und Samenkorn","Tötet Prinzessin Theradras und kehrt zu Selendra in der Nähe von Shadowprey in Desolace zurück."},
[7065]={"Verderbnis von Erde und Samenkorn","Erschlagt Prinzessin Theradras und kehrt zum Bewahrer Marandis an der Nijelspitze in Desolace zurück."},
[7066]={"Samenkorn des Lebens","Sucht Remulos in Moonglade auf und gebt ihm das Samenkorn des Lebens."},
[7067]={"Die Anweisungen des Pariahs","Lest die Anweisungen des Pariahs. Beschafft Euch danach das Amulett der Vereinigung von Maraudon und bringt es dem Zentaurenpariah im südlichen Desolace."},
[7068]={"Schattensplitter","Sammelt 10 Schattensplitter aus Maraudon und bringt sie zu Uthel'nay nach Orgrimmar."},
[7070]={"Schattensplitter","Sammelt 10 Schattensplitter in Maraudon und bringt sie zu Erzmagier Tervosh in den Marschen von Dustwallow."},
[7201]={"Das letzte Element","Begebt Euch in die Blackrocktiefen und beschafft 10 Essenzen der Elemente. Euer erster Gedanke ist, die Golems und die Schöpfer der Golems zu suchen. Doch Ihr erinnert Euch, dass Vivian Lagrave auch etwas von Elementaren vor sich hingemurmelt hat."},
[7441]={"Pusillin und der Älteste Azj'Tordin","Reist nach Düsterbruch und macht den Dämonen Pusillin ausfindig. Überzeugt ihn mit allen Mitteln davon, Euch Azj'Tordin's Buch der Zauberformeln zu geben. Kehrt mit dem Buch zu Az'Tordin, an Lariss' Pavillon in Feralas, zurück."},
[7461]={"Der innere Wahnsinn","Zerstört alle Wächter, die um die 5 Pylonen herumstehen, welche Immol'thars Gefängnis mit Energie versorgen. Sobald die Pylone deaktiviert wurden, wird sich das Kraftfeld, das Immol'thar umgibt, auflösen. Betretet Immol'thars Gefängnis und vernichtet den verdorbenen Dämonen. Anschließend müsst Ihr Prinz Tortheldrin im Athenaeum entgegentreten. Kehrt nach Abschluss der Aufgabe zur uralten Shen'dralar im Hof zurück."},
[7462]={"Der Schatz der Shen'dralar","Kehrt in das Athenaeum zurück und sucht den Schatz der Shen'dralar. Nehmt Euch Eure Belohnung!"},
[7463]={"Arcane Erfrischung","Reist nach Düsterbruch in das Wucherborkenviertel und besiegt den Wasserelementar Hydrobrut. Kehrt anschließend mit der Hydrobrutessenz, zum Hüter des Wissens Lydros im Athenaeum zurück."},
[7481]={"Elfische Legenden","Sucht in Düsterbruch nach Telmius Dreamseeker. Meldet Euch anschließend bei Sage Korolusk in Camp Mojache."},
[7482]={"Elfische Legenden","Sucht in Düsterbruch nach Telmius Dreamseeker. Meldet Euch anschließend bei der Gelehrten Runethorn in Feathermoon."},
[7486]={"Die Belohnung eines Helden","Nehmt Eure Belohnung aus Hydraxis' Kasten."},
[7488]={"Lethtendris' Netz","Bringt Lethtendris' Netz zu Latronicus Moonspear in der Festung Feathermoon, in Feralas."},
[7489]={"Lethtendris' Netz","Bringt Lethtendris' Netz zu Talo Thornhoof im Camp Mojache in Feralas."},
[7490]={"Sieg für die Horde","Bringt Onyxias Kopf zu Thrall in Orgrimmar."},
[7491]={"Für alle sichtbar","Sucht Oberanführer Runthak im Tal der Stärke auf."},
[7493]={"Die Reise beginnt erst"},
[7495]={"Sieg für die Allianz","Bringt Onyxias Kopf zu Hochlord Bolvar Fordragon in Stormwind."},
[7496]={"Gute Zeiten feiern","Sucht Major Mattingly im Tal der Helden auf."},
[7497]={"Die Reise beginnt erst"},
[7498]={"Garona: Eine Studie über Heimlichkeit und Verrat","Bringt das Buch seinen rechtmäßigen Besitzern zurück."},
[7499]={"Kodex der Verteidigung","Bringt das Buch seinen rechtmäßigen Besitzern zurück."},
[7500]={"Das Arkanistenkochbuch","Bringt das Buch seinen rechtmäßigen Besitzern zurück."},
[7501]={"Vom Licht und wie man es schwingt","Bringt das Buch seinen rechtmäßigen Besitzern zurück."},
[7502]={"Schatten einspannen","Bringt das Buch seinen rechtmäßigen Besitzern zurück."},
[7503]={"Das größte Volk von Jägern","Bringt das Buch seinen rechtmäßigen Besitzern zurück."},
[7504]={"Heiliger Fleischklops: Was das Licht Dir nicht erzählt","Bringt das Buch seinen rechtmäßigen Besitzern zurück."},
[7505]={"Frostschock und Du","Bringt das Buch seinen rechtmäßigen Besitzern zurück."},
[7506]={"Der Smaragdgrüne Traum","Bringt das Buch seinen rechtmäßigen Besitzern zurück."},
[7507]={"Nostros Kompendium","Bringt Nostros Kompendium des Drachentötens zurück in das Athenaeum."},
[7508]={"Das Schmieden von Quel'Serrar","Bringt dem Hüter des Wissens Lydros, die stumpfe und glanzlose Elfenklinge."},
[7509]={"Das Schmieden von Quel'Serrar","Bringt Onyxia dazu, ihren Feueratem auf die noch unerhitzte Klinge zu benutzen. Sobald dies geschehen ist, hebt die erhitzte Klinge wieder auf. Doch seid gewarnt, die erhitzte Klinge wird nicht auf ewig erhitzt bleiben - behaltet also die Zeit im Auge. Zuletzt müsst Ihr das Biest töten und die uralte erhitzte Klinge in ihren Leib rammen. Kehrt anschließend zu mir zurück und Quel'Serrar wird Euer sein."},
[7563]={"Kochendes Blut","Mor'zul Bloodbringer in der brennenden Steppe möchte, dass Ihr ihm 30 Flaschen mit dem Blut der tobenden Bestien bringt."},
[7564]={"Garzeeki Wildeyes","Bringt den Behälter mit Blut zu Gorzeeki Wildeyes in der brennenden Steppe."},
[7604]={"Ein verbindlicher Vertrag","Bringt den Vertrag der Thoriumbruderschaft zu Lokhtos Darkbargainer, wenn Ihr die Pläne für das Sulfuron erhalten möchtet."},
[7621]={"Eine Warnung (optional explanation)"},
[7622]={"Die Waage von Licht und Schatten","Rettet 50 Arbeiter bevor 15 getötet wurden. Sprecht mit Eris Havenfire, falls Ihr diesen Auftrag erfolgreich zu Ende bringen solltet. Konsultiert den Todesposten, um zu sehen wie viele Arbeiter bereits getötet wurden."},
[7623]={"Lord Banehollow","Erwerbt schattenhaftige Tränke von Gorzeeki in der brennenden Steppe. Benutzt die Tränke um durch Jaedenar zu reisen und sprecht mit Lord Banehollow."},
[7624]={"Ulathek der Verräter","Stellt Euch Ulathek und bringt das Herz des Verräters zu Lord Banehollow in Jaedenar."},
[7625]={"Xorothianischer Sternenstaub","Erwerbt xorothianischen Sternenstaub von Ur'dan. Bringt es anschließend Gorzeeki in der brennenden Steppe."},
[7629]={"Wichtellieferung","Bringt den Wichtel im Gefäß in das Alchimielabor in der Scholomance. Bringt nach der Herstellung des Pergaments, dass Gefäß zurück zu Gorzeeki Wildeyes."},
[7631]={"Schreckensross von Xoroth","Lest Morzuls Anweisungen. Beschwört ein xorothianisches Schreckensross, besiegt es und bindet seinen Geist an Euch."},
[7632]={"Das uralte Blatt","Findet den Besitzer des uralten, versteinerten Blatts. Viel Glück, <Name>; die Welt ist groß."},
[7634]={"Uraltes in Sehnen eingewickeltes Laminablatt","Hastat der Uralte hat Euch um die Beschaffung einer Sehne eines ausgewachsenen, blauen Drachens gebeten. Solltet Ihr diese Sehne finden, kehrt zu Hastat im Teufelswald zurück."},
[7635]={"Die passende Sehne","Stoma der Uralte hat Euch um die Beschaffung einer Sehne eines ausgewachsenen, schwarzen Drachens gebeten. Solltet Ihr diese Sehne finden, kehrt zu Stoma im Teufelswald zurück."},
[7636]={"Holzstab der Uralten","Ihr müsst die vier dämonischen Verderber ausfindig machen und zerstören: Simone die Verführerin. Klinfran der Wahnsinnige. Solenor der Schlächter. Artorius der Verhängnisvolle. Vernichtet diese Kreaturen und kehrt zu Vartrus dem Uralten im Teufelswald zurück. Haltet Euch an die versteinerte Rinde in Eurem Inventar, um Hinweise zu ihren Aufenthaltsorten zu erhalten. Ihr MÜSST diese Aufgabe eigenständig erledigen."},
[7637]={"Ein Opfer darbieten","Reist nach Ironforge und besorgt Euch Hohepriester Rohans Weihrauchschwenker. Eine Spende von 150 Gold wird erforderlich sein, um es zu bekommen."},
[7639]={"Lass Gerechtigkeit walten","Bringt den Weihrauchschwenker zu Lord Grayson Shadowbreaker in Stormwind zurück."},
[7640]={"Der Exorzismus des Schreckenstals","Vertreibt mit Hilfe des Weihrauchschwenkers die Geister im Schreckenstal. Vernichtet 25 Schreckenstalgeister und kehrt anschließend zu Lord Grayson Shadowbreaker im Kathedralenviertel von Stormwind zurück."},
[7641]={"Grimand Elmores Werk","Sprecht mit Grimand Elmore im Zwergendistrikt von Stormwind."},
[7642]={"Fünf Dinge","Bringt 40 Lagen Runenstoff, 6 Arkanitbarren, 10 Artha's Tränen, 5 Phiolen heiliges Wasser aus Stratholme und 150 Gold zu Grimand Elmore im Zwergendistrikt von Stormwind."},
[7643]={"Der uralte Pferdegeist","Beschafft spezielles Pferdefutter mit dem man ein Geisterpferd füttern kann. Meredith Carlson in Southshore scheint dafür eine recht gute Quelle zu sein. Reist anschließend nach Düsterbruch in Feralas und tötet Tendris Wucherborke. Dies wird den uralten Pferdegeist befreien. Füttert den Geist zur Beruhigung mit dem speziellen Pferdefutter. Gebt dem Pferdegeist das Arkanitpferdegeschirr, um es segnen zu lassen."},
[7644]={"Gesegnetes Arkanitpferdegeschirr","Kehrt mit dem gesegneten Arkanitpferdegeschirr zu Lord Grayson Shadowbreaker in das Kathedralenviertel von Stormwind zurück."},
[7646]={"Das Orakel der Anrufung","Bringt Lord Grayson Shadowbreaker im Kathedralenviertel von Stormwind einen Azerothianischen Diamanten und einen makellosen schwarzen Diamanten."},
[7647]={"Gerechtigkeit und Erlösung","Benutzt das Orakel der Anrufung im Herzen des Kellergewölbes des großen Ossuariums, in Scholomance. Damit ruft Ihr die verfluchten Geister, über deren Schicksal Ihr richten müsst. Durch das besiegen der Geister wird der Todesritter Schattensichel beschworen. Besiegt ihn und holt Euch die verlorene Seele des gefallenen Streitrosses. Gebt die Seele des gefallenen Streitrosses und das gesegnete und verzauberte Pferdegeschirr Schattensichels gefallenem Streitross zurück."},
[7648]={"Grimands feinste Arbeit","Bringt das Arkanitpferdegeschirr zur Begutachtung zu Lord Grayson Shadowbreaker im Kathedralenviertel von Stormwind."},
[7667]={"Materielle Unterstützung","Wenn Ihr Sagorne Crestrider im Tal der Weisheit von Orgrimmar helfen wollt, so bringt ihm einen azerothianischen und einen makellosen schwarzen Diamanten."},
[7703]={"Die offene Rechnung der Gordok","Findet die Stulpen der Gordokmacht und bringt sie zu Captain Kromcrush in Düsterbruch. Kromcrush zufolge sagen die \"Alte Zeit Geschichten\", dass Tortheldrin - ein \"gruseliger\" Elf, der sich selbst als Prinz bezeichnet- sie einem der Gordokkönige gestohlen hat."},
[7761]={"Blackhands Befehl","Das war ja vielleicht mal ein dummer Orc. Es sieht so aus, als müsstet Ihr dieses Brandzeichen finden, um an das Mal von Drakkisath zu gelangen. Damit sollte sich die Befehlskugel aktivieren lassen. Dem Brief zufolge, wird das Brandzeichen von General Drakkisath bewacht. Vielleicht solltet Ihr diesem Hinweis nachgehen."},
[7781]={"Der Herrscher von Blackrock","Bringt Hochlord Bolvar Fordragon in Stormwind den Kopf von Nefarian."},
[7782]={"Der Herrscher von Blackrock","Reist in nach Stormwind in das Tal der Helden und sprecht mit Feldmarschall Afrasiabi."},
[7783]={"Der Herrscher von Blackrock","Bringt Thrall in Orgrimmar den Kopf von Nefarian."},
[7784]={"Der Herrscher von Blackrock","Sprecht mit Hochfürst Saurfang in Orgrimmar. Er wartet im Tal der Stärke auf Euch."},
[7785]={"Untersuchung des Gefäßes","Untersucht das Gefäß der Wiedergeburt und bringt es zu Hochlord Demitrian."},
[7786]={"Donneraan der Windsucher","Um Donneraan den Windsucher aus seiner Gefangenschaft zu befreien, müsst Ihr Hochlord Demitrian die rechten und linken Hälften der Fesseln des Windsuchers, 10 Elementiumbarren und die Essenz des Feuerfürsten bringen."},
[7787]={"Donnerzorn erwache!","Präsentiert Hochlord Demitrian die vom Wind berührte, schlummernde Klinge."},
[7848]={"Abstimmung mit dem Kern","Begebt Euch zum Portal in den Blackrocktiefen, das in den geschmolzenen Kern führt, und findet ein Kernfragment. Kehrt mit dem Fragment zu Lothos Riftwaker am Blackrock zurück."},
