[8227]={"Nats Maßband","Bringt Nats Maßband zu Nat Pagle in den Marschen von Dustwallow zurück."},
[8231]={"Wellenjagd","Bringt 6 Wellenhauerschuppen zu Ogtinc in Azshara. Ogtinc wohnt oberhalb des Kliffs, nordöstlich der Ruinen von Eldarath."},
[8232]={"Der grüne Drache","Bringt Morphaz' Zahn zu Ogtinc in Azshara. Ogtinc wohnt oberhalb des Kliffs, nordöstlich der Ruinen von Eldarath."},
