[8234]={"Die versiegelte azurblaue Tasche","Erlangt die versiegelte azurblaue Tasche von dem Schamanen der Holzschlundfeste in Azshara zurück. Bringt sie anschließend zum Erzmagier Xylem, der ebenfalls in Azshara zu finden ist."},
[8235]={"Verschlüsselte Fragmente","Bringt Erzmagier Xylem in Azshara 10 verschlüsselte Fragmente."},
