[8240]={"Ein Schmuckstück für Zanza","Zerstört jedes Schmuckstück der Hakkari, das Ihr in Zul'Gurub findet, am Altar von Zanza auf der Insel Yojamba. Sobald Ihr dies getan habt, sprecht ganz in der Nähe mit Vinchaxa."},
[8243]={"Zanzas wirksame Tränke"},
[8246]={"Das Siegel der Zandalar"},
[8250]={"Geschick der Magier","Sucht nach Sanath Lim-yo und verschafft Euch Zugang zu Erzmagier Xylem."},
[8251]={"Magischer Staub","Bringt Erzmagier Xylem in Azshara 10 glitzernde Staubproben."},
[8252]={"Die Koralle der Sirenen","Sammelt 6 verzauberte Korallen und bringt sie zum Erzmagier Xylem."},
[8253]={"Vernichtet Morphaz","Beschafft den arkanen Splitter von Morphaz' Leichnam und kehrt mit ihm zu Erzmagier Xylem zurück."},
[8254]={"Cenarische Hilfe","Sucht Ogtinc in Azshara auf."},
[8255]={"Renner für einen höheren Zweck","Beschafft 4 gesunde Rennerdrüsen und bringt sie zu Ogtinc in Azshara. Ihr findet ihn auf den Klippen, nordöstlich der Ruinen von Eldarath."},
[8256]={"Sekret des Untodes","Beschafft ein Sekret des Untodes für Ogtinc in Azshara. Ihr findet ihn auf den Klippen, nordöstlich der Ruinen von Eldarath."},
[8257]={"Morphaz' Blut","Tötet Morphaz im versunkenen Tempel von Atal'Hakkar und bringt Greta Mosshoof im Teufelswald sein Blut. Der Eingang zum versunkenen Tempel liegt in den Sümpfen des Elends."},
[8258]={"Die Bedrohung durch Schattensichel","Wendet das Orakel der Anrufung inmitten des Kellergewölbes des großen Ossuariums in Scholomance an. Ihr werdet damit Geister herbeirufen, die es zu bekämpfen gilt. Nach Vernichtung dieser Geister wird der Todesritter Schattensichel auftauchen; besiegt ihn. Bringt Schattensichels Kopf zu Sagorne Creststrider im Tal der Weisheit in Orgrimmar."},
[8286]={"Was uns morgen erwartet","Reist zu den Höhlen der Zeit in Tanaris und findet Anachronos, Nachkomme Nozdormus."},
[8288]={"Nur einer kann sich erheben","Bringt Brutwächter Dreschbringers Kopf zu Baristolth der Sandstürme in die Burg Cenarius in Silithus."},
[8301]={"Der Pfad des Gerechten","Kehrt zu Baristolth zurück, sobald Ihr 200 Silithidenknochenpanzerfragmente gesammelt habt."},
[8302]={"Die Hand der Gerechtigkeit","Kehrt zu Baristolth zurück, sobald Ihr 200 Silithidenknochenpanzerfragmente gesammelt habt."},
[8303]={"Anachronos","Sucht nach Anachronos bei den Höhlen der Zeit in Tanaris."},
[8305]={"Lang Vergessenes","Sucht die Kristallträne und blickt in ihr Innerstes."},
[8412]={"Geistertotem","Bringt Bath'rah dem Windbehüter die Komponenten für das Geistertotem."},
[8413]={"Die Macht des Voodoos","Bringt Bath'rah dem Windbehüter die Voodoofedern."},
[8414]={"Austreibung des Bösen","Sammelt 20 Geißelsteine des Dieners und bringt sie zu Hohepriester Thel'danis in den westlichen Pestländern."},
[8416]={"Gereinigte Geißelsteine","Bringt den gereinigten Geißelstein zu Kommandant Ashlan Valorfist an der Chillwindspitze."},
[8417]={"Ein geplagter Geist","Sprecht mit dem gefallenen Helden der Horde am Eingang zu den verwüsteten Landen."},
[8418]={"Erschaffung des Steins der Macht","Bringt die Voodoofedern zu Ashlam Valorfist."},
[8419]={"Die Bitte eines Wichtels","Bringt ein Stück Teufelsstoff zu Impsy im Teufelswald."},
[8420]={"Heiß und brennend","Bringt ein Stück Teufelsstoff zu Impsy im Teufelswald."},
[8421]={"Das richtige Zeug","Bringt 10 Stück faules Holz und 4 Blutgiftessenzen zu Impsy im Teufelswald."},
[8422]={"Federn von Trollen","Bringt 6 Voodoofedern von den Trollen aus dem versunkenen Tempel."},
[8423]={"Kriegerverwandtschaft","Tötet 7 Hölleneber in den verwüsteten Landen und kehrt zu dem gefallenen Helden der Horde zurück."},
[8424]={"Krieg den Schattenanbetern","Merzt die Schattenanbeter in den verwüsteten Landen aus und kehrt zum gefallenen Helden der Horde zurück."},
[8425]={"Voodoofedern","Bringt die Voodoofedern der Trolle im versunkenen Tempel zu dem gefallenen Helden der Horde."},
[8519]={"Eine Spielfigur auf dem Schachbrett der Ewigkeit","Lernt so viel Ihr könnt über die Vergangenheit, sprecht dann mit Anachronos in den Höhlen der Zeit in Tanaris."},
[8544]={"Schiftung des Eroberers","Bringt die Befehlsbindungen der Qiraji, 2 Götzen der Nacht, 5 Steinskarabäen und 5 Tonskarabäen zu Andorgos in Ahn'Qiraj. Diese Aufgabe erfordert zum Abschluss auch einen neutralen Ruf bei der Brut Nozdormus."},
[8555]={"Der Bund der Drachenschwärme"},
[8556]={"Siegel der unnachgiebigen Stärke","Bringt 1 Gebieterring der Qiraji, 2 züngelnde Götzen, 5 Bronzeskarabäen und 5 Elfenbeinskarabäen zu Windruferin Yessendra in Silithus. Diese Aufgabe erfordert zum Abschluss auch einen wohlwollenden Ruf beim Zirkel des Cenarius."},
[8557]={"Tuch der unnachgiebigen Stärke","Bringt 1 Kampftuch der Qiraji, 2 Onyxgötzen, 5 Sillberskarabäen und 5 Knochenskarabäen zu Keyl Swiftclaw in Silithus. Diese Aufgabe erfordert zum Abschluss auch einen respektvollen Ruf beim Zirkel des Cenarius."},
[8558]={"Sichel der unnachgiebigen Stärke","Bringt 1 Stachelgriff der Qiraji, 2 Alabastergötzen, 5 Kristallskarabäen und 5 Steinskarabäen zu Aufseher Haro in Silithus. Diese Aufgabe erfordert zum Abschluss auch einen ehrfürchtigen Ruf beim Zirkel des Cenarius."},
[8559]={"Schienbeinschützer des Eroberers","Bringt die Befehlsbindungen der Qiraji, 2 Götzen des Krieges, 5 Elfenbeinskarabäen und 5 Goldskarabäen zu Kandrostrasz in Ahn'Qiraj. Diese Aufgabe erfordert auch einen neutralen Ruf bei der Brut Nozdormus."},
[8560]={"Beinschützer des Eroberers","Bringt Ouros intakte Haut, 2 Götzen des Todes, 5 Bronzeskarabäen und 5 Elfenbeinskarabäen zu Kandrostrasz innerhalb von Ahn'Qiraj. Diese Aufgabe erfordert zum Abschluss auch einen freundlichen Ruf bei der Brut Nozdormus."},
[8561]={"Krone des Eroberers","Bringt Vek'nilashs Reif, 2 Götzen der Sonne, 5 Steinskarabäen und 5 Kristallskarabäen zu Andorgos in Ahn'Qiraj. Diese Aufgabe erfordert zum Abschluss auch einen freundlichen Ruf bei der Brut Nozdormus."},
[8562]={"Brustplatte des Eroberers","Bringt den Knochenpanzer des alten Gottes, 2 Götzen des Krieges, 5 Silberskarabäen und 5 Knochenskarabäen zu Vethsera innerhalb von Ahn'Qiraj. Diese Aufgabe erfordert zum Abschluss auch einen wohlwollenden Ruf bei der Brut Nozdormus."},
