[8728]={"Die gute und die schlechte Nachricht","Narain Soothfancy in Tanaris möchte, dass Ihr ihm 20 Arkanitbarren, 10 Elementiumerz, 10 Azerothianische Diamanten und 10 blaue Saphire bringt."},
[8729]={"Der Zorn von Neptulon","Benutzt die Arkanitboje am wirbelnden Maelstrom in der Bucht der Stürme in Azshara."},
[8730]={"Nefarius' Verderbnis","Tötet Nefarian und bringt den roten Szeptersplitter wieder in Euren Besitz. Bringt den roten Szeptersplitter zu Anachronos in den Höhlen der Zeit in Tanaris. Euch bleiben 5 Stunden, um diese Aufgabe zu erfüllen."},
[8733]={"Eranikus, der Tyrann des Traums","Reist nach Teldrassil und sucht Malfurions Agenten irgendwo außerhalb der Stadtmauern von Darnassus auf."},
[8734]={"Tyrande und Remulos","Reist nach Moonglade und sprecht mit Bewahrer Remulos."},
[8735]={"Die Verderbnis des Alptraums","Reist zu den vier Portalen des smaragdgrünen Traums in Azeroth und sammelt dort jeweils ein Verderbnisfragment des Alptraums ein. Kehrt zu Bewahrer Remulos in Moonglade zurück, sobald Ihr diese Aufgabe erfüllt habt."},
[8736]={"Der Alptraum offenbart sich","Verteidigt Nighthaven gegen Eranikus. Bewahrer Remulos darf dabei nicht ums Leben kommen und Eranikus darf nicht getötet werden. Verteidigt Euch. Erwartet Tyrande."},
[8741]={"Der Held kehrt zurück","Bringt den grünen Szeptersplitter zu Anachronos in den Höhlen der Zeit."},
