[8946]={"Lebensbeweis","Bringt Anthion Harmon in den östlichen Pestländern Ysidas Medaillon."},
[8948]={"Anthions alter Freund","Bringt Falrin Treeshaper in der Bibliothek von Düsterbruch das unvervollständigte Banner der Provokation."},
[8949]={"Falrins Rachefeldzug","Nehmt den Ogern in der Blackrockspitze oder in Düsterbruch 25 Ogerkriegsperlen ab und bringt sie zu Falrin Treeshaper im Athenaeum, der Bibliothek von Düsterbruch."},
[8950]={"Die Verzauberung des Aufhetzers","Bringt Falrin Treeshaper in Düsterbruch 1 Essenz eines spöttischen Geisterwesens, 4 Dunkelrunen und 8 große glänzende Splitter."},
[8961]={"Die drei Könige der Flammen","Bringt Bodley im Blackrock Incendius' Pyrophor, Glutsehers Glut, die Asche des Fürsten und ein geheiligtes Räuchergefäß."},
[8966]={"Das linke Stück von Lord Valthalaks Amulett","Benutzt das Räuchergefäß der Beschwörung, um den Geist von Mor Grayhoof zu beschwören und zu vernichten. Kehrt dann mit dem linken Stück von Lord Valthalaks Amulett und dem Räuchergefäß der Beschwörung zu Bodley im Blackrock zurück."},
[8967]={"Das linke Stück von Lord Valthalaks Amulett","Benutzt das Räuchergefäß der Beschwörung, um den Geist von Isalien zu beschwören und zu vernichten. Kehrt dann mit dem linken Stück von Lord Valthalaks Amulett und dem Räuchergefäß der Beschwörung zu Bodley im Blackrock zurück."},
[8968]={"Das linke Stück von Lord Valthalaks Amulett","Benutzt das Räuchergefäß der Beschwörung, um die Geister von Jarien und Sothos zu beschwören und zu vernichten. Kehrt dann mit dem linken Stück von Lord Valthalaks Amulett und dem Räuchergefäß der Beschwörung zu Bodley im Blackrock zurück."},
[8969]={"Das linke Stück von Lord Valthalaks Amulett","Benutzt das Räuchergefäß der Beschwörung, um den Geist von Kormok zu beschwören und zu vernichten. Kehrt dann mit dem linken Stück von Lord Valthalaks Amulett und dem Räuchergefäß der Beschwörung zu Bodley im Blackrock zurück."},
[8989]={"Das rechte Stück von Lord Valthalaks Amulett","Benutzt das Räuchergefäß der Beschwörung, um den Geist von Mor Grayhoof zu beschwören und zu vernichten. Kehrt dann mit Lord Valthalaks zusammengesetzten Amulett und dem Räuchergefäß der Beschwörung zu Bodley im Blackrock zurück."},
[8990]={"Das rechte Stück von Lord Valthalaks Amulett","Benutzt das Räuchergefäß der Beschwörung, um den Geist von Isalien zu beschwören und zu vernichten. Kehrt dann mit Lord Valthalaks zusammengesetzten Amulett und dem Räuchergefäß der Beschwörung zu Bodley im Blackrock zurück."},
[8991]={"Das rechte Stück von Lord Valthalaks Amulett","Benutzt das Räuchergefäß der Beschwörung, um die Geister von Jarien und Sothos zu beschwören und zu vernichten. Kehrt dann mit Lord Valthalaks zusammengesetzten Amulett und dem Räuchergefäß der Beschwörung zu Bodley im Blackrock zurück."},
[8992]={"Das rechte Stück von Lord Valthalaks Amulett","Benutzt das Räuchergefäß der Beschwörung, um den Geist von Kormok zu beschwören und zu vernichten. Kehrt dann mit Lord Valthalaks zusammengesetzten Amulett und dem Räuchergefäß der Beschwörung zu Bodley im Blackrock zurück."},
[8994]={"Letzte Vorbereitungen","Bringt Bodley im Blackrock 40 Blackrockarmschienen und ein Fläschchen mit oberster Macht."},
[8995]={"Mea Culpa, Lord Valthalak","Benutzt das Räuchergefäß der Beschwörung, um Lord Valthalak zu beschwören. Macht ihn unschädlich und benutzt dann Lord Valthalaks Amulett bei seiner Leiche. Danach werdet Ihr dem Geist von Lord Valthalak sein Amulett zurückgeben müssen."},
[9015]={"Die Herausforderung","Reist zum Ring des Gesetzes der Blackrocktiefen und errichtet das Banner der Provokation in dessen Mitte, während Ihr von Oberrichter Grimmstein verurteilt werdet. Tötet Theldren und seine Gladiatoren und kehrt dann mit dem ersten Stück von Lord Valthalaks Amulett zu Anthion Harmon in den östlichen Pestländern zurück."},
[9023]={"Das perfekte Gift","Dirk Thunderwood in der Burg Cenarius will, dass Ihr ihm Venoxis' Giftbeutel und Kurinnaxx' Giftbeutel bringt."},
[9033]={"Echo des Krieges","Kommandant Eligor Morgenbringer bei der Kapelle des Hoffnungsvollen Lichts in den Östlichen Pestländern möchte, dass Ihr 5 lebende Monstrositäten, 5 Steinhautgargoyles, 8 Hauptmänner der Todesritter und 3 Giftpirscher tötet."},
