[1487]={"L'éradication des Déviants","Ebru, des Cavernes des lamentations, veut que vous tuiez 7 Ravageurs Déviant, 7 Vipères Déviant, 7 Glacials Déviant et 7 Crocs-d'effroi Déviant."},
[1489]={"Hamuul Runetotem","Parler à Hamuul Runetotem."},
[1490]={"Nara Wildmane","Parler à Nara Wildmane."},
[1491]={"Les potions d'intelligence","Apporter 6 doses d'Essence de lamentation à Mebok Mizzyrix, à Ratchet."},
[1651]={"Le Tome de la bravoure","Défendez Daphne Stilwell contre les attaques des Défias. Aucun de vous deux ne doit mourir, si vous voulez réussir la quête. Quand vous aurez réussi, reparlez à Daphne Stilwell."},
[1652]={"Le Tome de la bravoure","Parler à Duthorian Rall à Stormwind."},
[1653]={"Le test de droiture","Parler à Jordan Stilwell à Ironforge"},
[1654]={"Le test de droiture","Utiliser les Notes sur les armes de Jordan, trouver du Bois de chêne de blanchepierre, la Cargaison de Minerai raffiné de Bailor, le Marteau de forge de Jordan et une Gemme de Kor, puis revenir voir Jordan Stilwell à Ironforge."},
[1740]={"L'Orbe de Soran'ruk","Trouver 3 Fragments de Soran'ruk et 1 Grand Fragment de Soran'ruk et les rapporter à Doan Karhan dans les Tarides."},
[1806]={"Le test de droiture","Attendre que Jordan Stilwell finisse de forger votre arme."},
[1956]={"L'Energie d'Uldaman","Récupérer une Source d'énergie en obsidienne et la rapporter à Tabetha dans le marécage d'Âprefange."},
[2040]={"Assaut souterrain","Récupérer l'Indicateur Gnoam dans les mortemines et le ramener à Shoni la Silencieuse à Stormwind."},
[2198]={"Le Collier brisé","Chercher celui qui a fabriqué le Collier brisé pour découvrir sa valeur potentielle."},
[2199]={"Le Prix de la Connaissance","Apporter 5 Barres d'Argent à Talvash del Kissel, à Ironforge."},
[2200]={"Retour à Uldaman","Chercher des indices sur le Collier de Talvash à Uldaman. Le paladin dont il a parlé est la dernière personne à l'avoir porté."},
[2201]={"Trouver les Gemmes","Trouvez le rubis, le saphir et la topaze qui sont éparpillés à travers Uldaman. Une fois que vous les aurez, contactez Talvash del Kissel en utilisant la Fiole de divination qu’il vous a donnée précédemment. C'est dans le journal, vous savez... * Le rubis a été caché dans une zone barricadée des Ombreforge. * La topaze a été dissimulée dans une urne, dans l’une des zones trogg, pas très loin de nains de Alliance. * Le saphir est en possession du chef trogg, Grimlok."},
[2202]={"Rechercher les composants à Uldaman","Apporter 12 Champignons magenta à Jarkal Mossmeld à Kargath."},
[2204]={"Réparer le Collier","Obtenir une Source d'énergie de la construction la plus puissante que vous pouvez trouver à Uldaman, puis la remettre à Talvash del Kissel à Ironforge."},
[2240]={"La Chambre secrète","Lire le journal de Baelog, explorer la Chambre secrète, puis rendre compte au Prospecteur Stormpike."},
[2258]={"Les réactifs des Terres ingrates","Apporter 5 Gésiers de busard, 10 Crocs de coyote des rochers et 5 Fragments d'élémentaire de roche à Jarkal Mossmeld, à Kargath, dans les Terres ingrates."},
[2278]={"Les Disques de platine","Parler au Gardien des pierres pour connaître le Savoir qu'il défend. Une fois découvert ce qu'ils peuvent offrir, activer les Disques de Norgannon."},
[2280]={"Les Disques de platine","Apporter la version miniature des Disques de Norgannon à l'un des Sages de Thunder Bluff."},
[2283]={"Réparer le Collier","Rechercher dans l'excavation d'Uldaman un Collier de prix et le rapporter à Dran Droffers à Orgrimmar. Ce Collier peut être endommagé."},
[2284]={"Réparer le Collier, deuxième prise","Trouver, dans les profondeurs d'Uldaman, des indices sur la localisation des Gemmes."},
[2318]={"La Traduction du Journal","Trouver quelqu'un qui puisse traduire le journal du paladin. L'endroit le plus proche est Kargath, dans les Terres ingrates."},
[2338]={"La Traduction du Journal","Laisser Jarkal emprunter le Collier en échange de la traduction du Journal."},
[2339]={"Trouver les Gemmes et la Source d'énergie","Récupérer, dans Uldaman, les trois gemmes et une source d’énergie pour le collier, puis les rapporter à Jarkal Mossmeld, à Kargath. Jarkal pense que vous pouvez trouver une source d’énergie sur la machine la plus puissante d’Uldaman. C'est dans le journal, vous savez... * Le rubis a été caché dans une zone barricadée des Ombreforge. * La topaze a été dissimulée dans une urne, dans l’une des zones trogg, pas très loin de nains de Alliance. * Le saphir est possession du chef trogg, Grimlok."},
[2342]={"Des Trésors à recouvrer","Rapporter à Patrick Garrett, à Undercity, son Trésor de famille, qui se trouve dans le Coffre de famille dans le Hall commun sud d'Uldaman."},
[2398]={"Les nains perdus","Trouver Baelog dans Uldaman."},
[2418]={"Les pierres de puissance","Apporter 8 Pierres de puissance Dentrium et 8 Pierres de puissance An'Alleum à Rigglefuzz dans les Terres ingrates."},
[2500]={"Les réactifs des Terres ingrates","Aller chercher les réactifs dont Ghak Healtouch a besoin dans les Terres ingrates, puis les lui rapporter à Thelsamar."},
[2768]={"Le bâtonnet divino-matic","Rapporter le Bâtonnet divino-matic à l'Ingénieur en chef Bilgewhizzle, à Gadgetzan."},
[2770]={"Gahz'rilla","Rapporter les Ecailles électrifiées de Gahz'rilla à Wizzle Brassbolts dans les Salines."},
[2841]={"Guerre des plates-formes","Obtenir la Combinaison du coffre de Thermaplugg, prendre les Plans de la plate-forme et les apporter à Nogg à Orgrimmar."},
[2842]={"L'ingénieur en chef Scooty","Parler à Scooty à Baie-du-Butin."},
[2843]={"Gnomer-paaarti !","Attendre que Scooty calibre le transpondeur des gobelins."},
[2846]={"La tiare des abysses","Rapporter la Tiare des abysses à Tabetha au marécage d'Âprefange."},
[2865]={"Les carapaces de Scarabées","Rapporter 5 Carapaces de scarabée intactes à Tran'rek à Gadgetzan."},
[2904]={"Une jolie pagaille","Escorter Kernobee jusqu’à la sortie de la Fuite du temps, puis faire un rapport à Scooty, à Baie-du-Butin."},
[2922]={"Sauver le cerveau de Techbot !","Rapporter la Mémoire principale de Techbot au maître-artisan Overspark à Ironforge."},
[2924]={"Les cerveaux mécaniques","Rapporter 12 Cerveaux mécaniques à Klockmort Spannerspan à Ironforge."},
[2926]={"Gnogaine","Utiliser la Fiole de collecte plombée vide sur les Envahisseurs ou les Pilleurs irradiés pour recueillir des retombées radioactives. Une fois pleine, rapportez-la à Ozzie Togglevolt à Kharanos."},
[2928]={"Excavateurs gyrodrilmatiques","Rapporter 24 Entrailles mécaniques de robot à Shoni à Stormwind."},
[2929]={"La grande trahison","Aller à Gnomeregan et tuer le mekgénieur Thermaplugg. Puis retourner voir le Grand Bricoleur Mekkatorque."},
[2930]={"Sauvetage de données","Apporter une Carte perforée prismatique au Maître mécanicien Castpipe, à Ironforge."},
[2933]={"Bouteilles de venin","Apporter une Bouteille de venin à un apothicaire, au Moulin-de-Tarren."},
[2934]={"Glande à venin intacte","Rapporter une Glande à venin intacte à l'Apothicaire Lydon, au Moulin-de-Tarren."},
[2935]={"Consulter Maître Gadrin","Parler à Maître Gadrin au Village de Sen'jin."},
[2936]={"Le dieu-araignée","Lire la Tablette de Theka pour connaître le véritable nom du dieu-araignée des Witherbark, puis retourner voir Maître Gadrin."},
[2945]={"Anneau sali","Trouver un moyen de nettoyer l'Anneau sali."},
[2947]={"Le retour de l'anneau","Garder l'anneau ou retrouver la personne qui y a gravé les lettres."},
[2948]={"Amélioration gnomique","Apporter l’Anneau d'or brillant, une Barre d'argent, une Agate mousse et 30 pièces d’argent à Talvash del Kissel, à Ironforge."},
[2949]={"Le retour de l'anneau","Garder l'anneau ou retrouver la personne qui y a gravé les lettres."},
[2950]={"Nogg améliore l'anneau","Apporter l’Anneau d'or brillant, une Barre d'argent, une Agate mousse et 30 pièces d’argent à Nogg, à Orgrimmar."},
[2951]={"Le Décapeur 5200 !","Insérer un Objet sali dans le Décapeur 5200, sans oublier de jeter trois pièces d'argent dans la fente, pour démarrer la machine."},
[2962]={"Encore plus de Lueur verte !","Voyager à Gnomeregan et rapporter de la Matière radioactive à haut potentiel. Attention, la matière radioactive est instable et se désactive rapidement. Après le travail, conserver la Flasque plombée lourde, pour Ozzie."},
[2988]={"Les cages Witherbark","Inspecter les cages dans les deux villages Witherbark, puis retourner auprès du Maître des gryphons Talonaxe."},
[2989]={"L'autel de Zul","Regarder sur le dessus de l'autel de Zul, puis retourner auprès du Maître des gryphons Talonaxe."},
[2990]={"Thadius Grimshade","Apporter la Plume de Bec-tranchant à Thadius Grimshade, dans les Terres foudroyées."},
[2991]={"Médaillon de Nekrum","Apporter le Médaillon de Nekrum à Thadius Grimshade, dans les Terres foudroyées."},
[3042]={"Agent durcissant troll","Apporter 20 Fioles d'agent durcissant troll à Trenton Lighthammer, dans Gadgetzan."},
[3341]={"L'anéantissement","Andrew Brownell veut que vous tuiez Amnennar le Porte-froid et que vous lui rameniez son crâne."},
[3373]={"L'Essence d'Eranikus","Placer l'Essence d'Eranikus dans le Réceptacle d'essence situé dans son antre dans le Temple englouti."},
[3444]={"Le Cercle de pierres","Récupérer le Cercle de pierres à l'Atelier de Marvon Rivetseeker à Ratchet."},
[3446]={"Dans les profondeurs","Trouver l'Autel d'Hakkar dans le Temple englouti du marais des Chagrins."},
[3447]={"Le secret du cercle","Voyager jusqu'au Temple englouti et découvrir le secret du cercle de statues."},
[3520]={"Esprits de Hurleurs","Capturer l’Esprit de 3 Hurleurs en Feralas, puis retourner voir Yeh'kinya à Port Gentepression."},
[3523]={"Le Fléau des Souilles","Pour aider Belnistrasz, lui parler de nouveau et lui rendre la Pierre de voeu qu’il vous avait donnée."},
[3525]={"L'extinction de l'idole","Escorter Belnistrasz jusqu'à l'Idole des hurans dans les Souilles de Tranchebauge. Protéger Belnistrasz tandis qu'il exécute le rituel pour arrêter l'idole."},
[3527]={"La prophétie de Mosh'aru","Apporter les Première et Deuxième tablettes Mosh'Aru à Yeh'kinya, à Tanaris."},
[3528]={"Le dieu Hakkar","Apporter l'Oeuf Rempli d'Hakkar à Yeh'kinya dans Tanaris."},
[3636]={"Apportez la Lumière","Tuer Amnennar le Porte-froid, aux Souilles de Tranchebauge, pour l’Archevêque Benedictus."},
[3701]={"Les ruines fumantes de Thaurissan","Aller dans les ruines de Thaurissan, dans les Steppes ardentes. Récupérer des informations sur les Reliques de Thaurissan, puis retourner auprès de l’Historienne royale Archesonus."},
[3702]={"Les ruines fumantes de Thaurissan","Écouter l'historienne royale Archesonus raconter l'histoire de Thaurissan."},
[3765]={"La dépravation au loin","Aller voir Gershala Nightwhisper à Auberdine."},
[3801]={"Héritage Sombrefer","Parler à Franclorn Forgewright si obtenir une clé de la Cité majeure vous intéresse."},
[3802]={"Héritage Sombrefer","Tuer Fineous Darkvire et récupérer le grand marteau, Souillefer. Apporter Souillefer au sanctuaire de Thaurissan et le placer sur la statue de Franclorn Forgewright."},
[3906]={"Discordance des flammes","Partir pour la carrière dans le mont Blackrock et tuer le Grand maître Pyron. Retourner voir Thunderheart une fois votre mission accomplie."},
[3907]={"Discordance des flammes","Pénétrer dans les Profondeurs de Blackrock et traquer le Seigneur Incendius. Le tuer puis donner tous les renseignements que vous pouvez trouver à Thunderheart."},
[3981]={"Le commandant Gor'shak","Trouver le commandant Gor'shak dans les Profondeurs de Blackrock. Le dessin grossier représentait également des barreaux. Peut-être devriez-vous rechercher un genre de prison."},
[3982]={"Que se passe-t-il ?","Défendre Gor'shak."},
[4001]={"Que se passe-t-il ?","Parler à Kharan Mighthammer et obtenir autant de renseignements que possible sur l'enlèvement de la princesse Moira Bronzebeard. Apporter ces renseignements à Thrall à Orgrimmar. Gor'shak a dit que Kharan était détenu dans une cellule proche."},
[4002]={"Les Royaumes de l'est","Parler à Thrall si vous êtes <prêt/prête> à vous charger de la mission qu'il a prévue."},
[4003]={"Un sauvetage royal","Tuer l'Empereur Thaurissan et libérer la princesse Moira Bronzebeard de son sort maléfique."},
[4022]={"Un goût de flammes","Montrer à Cyrus Therepentous l'Ecaille des dragons noirs que vous avez reçue de Kalaran Windblade."},
[4024]={"Un goût de flammes","Partir pour les Profondeurs de Blackrock et tuer Bael'Gar. Vous savez seulement que le géant demeure à l'intérieur des Profondeurs de Blackrock. Se souvenir d'utiliser l'Ecaille des dragons noirs altérée pour capturer l'Essence ardente. Apporter l'Essence ardente recouverte à Cyrus Therepentous."},
[4061]={"La révolte des machines","S'aventurer dans les Steppes ardentes et récupérer 10 Fragments d'élémentaires cassés pour la Hiérophante Theodora Mulvadania. Theodora vous a indiqué que les golems et les élémentaires étaient la source de ces fragments."},
[4062]={"La révolte des machines","Apporter l'Echantillon de fragment d'élémentaire à Lotwil Veriatus. Theodora vous a dit qu'il se trouvait au camp à l'est."},
[4063]={"La révolte des machines","Trouver et tuer le seigneur des golems Argelmach. Rapporter sa tête à Lotwil. Collecter également 10 Noyaux d'élémentaire intacts sur les Golems ravarage et les Assemblages porteguerre qui protègent Argelmach. Vous savez cela car vous êtes médium."},
[4081]={"TUER A VUE : nains Sombrefer","Pénétrer dans les Profondeurs de Blackrock et tuer les vils agresseurs ! Le chef de guerre Goretooth veut que vous tuiez 15 Gardes Ragenclumes, 10 Gardiens Ragenclumes et 5 Fantassins Ragenclumes. Retourner le voir une fois votre mission accomplie."},
[4082]={"TUER A VUE : Officiers de haut rang Sombrefer","Pénétrer dans les Profondeurs de Blackrock et tuer les vils agresseurs ! Le Chef de guerre Goretooth veut que vous tuiez 10 Médecins Ragenclumes, 10 Soldats Ragenclumes et 10 Officiers Ragenclumes. Retourner le voir une fois votre mission accomplie."},
[4083]={"Le Calice spectral"},
[4121]={"Situation précaire","Escortez votre prisonnier, Grark Lorkrub, au-delà des Steppes ardentes et du mont Blackrock, jusqu'à la gorge des Vents brûlants. Rappelez-vous que Lexlort a précisé que ses hommes attendraient de l'autre côté pour arrêter Grark. On vous demandera également de remettre vos chaînes en thorium à Lexlort."},
[4122]={"Grark Lorkrub","Partez pour les Steppes ardentes et trouvez Grark Lorkrub. Lexlort a mentionné le fait que la dernière fois où on l'a vu, il se trouvait dans une imposante forteresse des Blackrock. Une fois Grark Lorkrub découvert, l'enchaîner avec les chaînes en thorium, puis le ramener par le mont Blackrock jusque dans la gorge des Vents brûlants. Des hommes de Lexlort attendront de l'autre côté de la gorge et le mettront sous bonne garde."},
[4123]={"Le Coeur de la montagne","Apporter le Cœur de la montagne à Maxwort Uberglint dans les Steppes ardentes."},
[4126]={"Hurley Blackbreath","Apporter la Recette perdue de la Thunderbrew à Ragnar Thunderbrew à Kharanos."},
[4132]={"Opération : Mort à Forgehargne","Voyagez jusqu'aux Profondeurs de Blackrock et tuez le général Forgehargne ! Une fois votre mission accomplie, retournez voir le seigneur de guerre Goretooth."},
[4134]={"La recette perdue de Thunderbrew","Apporter la Recette perdue de la Thunderbrew à Vivian Lagrave à Kargath."},
[4136]={"Ribbly Screwspigot","Apporter la Tête de Ribbly à Yuka Screwspigot dans les Steppes ardentes."},
[4141]={"Muigin et Larion","Récolter 15 Pétales-de-sang et retourner voir Muigin."},
[4142]={"Visite à Gregan","Apporter une Pétale-de-sang à Gregan Brewspewer en Feralas."},
[4143]={"Brouillard maléfique","Récupérer 5 Echantillons de brume atal'ai puis retourner voir Muigin dans le cratère d'Un'Goro."},
[4145]={"Larion et Muigin","Chasser 5 Flagellants Pétale-de-sang, 5 Batteurs Pétale-de-sang, 5 Ecorcheurs Pétale-de-sang et 5 Trappeurs Pétale-de-sang pour Larion au refuge des Marshal."},
[4146]={"Carburant de baguette","Remettre la Baguette déchargée et 5 Echantillons de brume atal'ai à Larion au refuge des Marshal."},
[4147]={"Atelier de Marvon","Se rendre à l'Atelier de Marvon Rivetseeker à Ratchet."},
[4182]={"La menace des draconiens","Tuer 15 Rejetons noirs, 10 Draconides noirs, 4 Wyrmides noirs et 1 Drake noir. Retrouver Helendis Riverhorn une fois la tâche accomplie."},
[4183]={"Les véritables maîtres","Voyager jusqu'au Lakeshire et remettre la Lettre d'Helendis Riverhorn au Magistrat Solomon."},
[4184]={"Les véritables maîtres","Voyager vers Stormwind et remettre la Demande d'aide de Solomon au généralissime Bolvar Fordragon. Bolvar demeure dans le Donjon de Stormwind."},
[4185]={"Les véritables maîtres","Parler au généralissime Bolvar Fordragon après avoir parlé à dame Katrana Prestor."},
[4186]={"Les véritables maîtres","Apporter le Décret de Bolvar au Magistrat Solomon au Lakeshire."},
[4201]={"Le philtre d'amour","Apporter 4 Gromsang, 10 Veines d'argent de géant et la Fiole de Nagmara remplie à la gouvernante Nagmara dans les Profondeurs de Blackrock."},
[4223]={"Les véritables maîtres","Parler au maréchal Maxwell dans les Steppes ardentes."},
[4224]={"Les véritables maîtres","Parlez à John le Loqueteux pour apprendre ce qu'il est advenu du maréchal Windsor puis retournez voir le maréchal Maxwell lorsque vous aurez accompli cette tâche. Vous vous rappelez que le maréchal Maxwell vous a dit de le chercher dans une grotte au nord."},
[4241]={"Maréchal Windsor","Partir pour le mont Blackrock au nord-ouest et pénétrer dans les Profondeurs de Blackrock. Découvrir ce qu'il est advenu du Maréchal Windsor. Vous vous souvenez que John le Loqueteux a dit que Windsor avait été traîné en prison."},
[4242]={"Espoir abandonné","Donner les mauvaises nouvelles au maréchal Maxwell."},
[4262]={"Grand seigneur Pyron","Tuer le Grand seigneur Pyron et retourner voir Jalinda Sprig. Jalinda vous a dit qu'il gardait la carrière. Peut-être devriez-vous chercher à cet endroit ?"},
[4263]={"Incendius !","Trouver le Seigneur Incendius dans les Profondeurs de Blackrock et le détruire !"},
[4264]={"Une Note chiffonnée","Il se peut que vous ayez simplement buté sur quelque chose qui pourrait intéresser le maréchal Windsor au plus haut point. Il reste peut-être encore un peu d'espoir, après tout…"},
[4282]={"Un espoir en lambeaux","Rapporter les Renseignements perdus du maréchal Windsor. Le maréchal Windsor pense qu'ils sont détenus par le seigneur golem Argelmach et par le général Forgehargne."},
[4286]={"Du beau matériel","Se rendre dans les Profondeurs de Blackrock et trouver 20 Sacoches Sombrefer. Retourner voir Oralius lorsque vous aurez accompli cette tâche. Logiquement, ces sacoches devraient être sur les nains Sombrefer des Profondeurs de Blackrock."},
[4322]={"Evasion !","Aider le maréchal Windsor à récupérer son équipement et à libérer ses amis. Ensuite, retourner voir le maréchal Maxwell."},
[4341]={"Kharan Mighthammer","Aller dans les Profondeurs de Blackrock et trouver Kharan Mighthammer. Le roi a mentionné que Kharan était retenu prisonnier là-bas ; cherchez une prison."},
[4342]={"Légende de Kharan","Écouter Kharan Mighthammer raconter son histoire."},
[4361]={"Le porteur des mauvaises nouvelles","Retourner à Ironforge et apporter la mauvaise nouvelle au Roi Magni Bronzebeard."},
[4362]={"Le destin du Royaume","Retourner dans les Profondeurs de Blackrock et secourir la Princesse Moira Bronzebeard, prisonnière de l'Empereur Dagran Thaurissan."},
[4701]={"Abattez-la","Allez au Pic Blackrock et anéantir la menace worg à sa source. Tandis que vous quittiez Helendis, il a crié un nom : Halycon. C'est ce que disent les orcs en parlant des worgs."},
[4724]={"La maîtresse de meute","Tuer Halycon, la maîtresse de la meute des worgs Bloodaxe."},
[4726]={"L'essence de rejeton","Apporter 8 Essences de Rejeton et le Draco-Incarcinatrix 900 à Tinkee Steamboil à la Corniche des flammes dans les Steppes ardentes."},
[4729]={"Les animaux exotiques de Kibler","Aller au Pic Blackrock et trouver de Jeunes worgs Bloodaxe. Utiliser la cage pour transporter ces petites bêtes féroces. Rapporter un Jeune worg en cage à Kibler."},
[4734]={"Un oeuf congelé","Utiliser le Prototype d'Oeufilloscope sur un oeuf dans la Colonie."},
[4735]={"La collecte d'oeufs","Apporter 8 Oeufs de dragon collectés et le Module collectronique à Tinkee Steamboil à la Corniche des flammes dans les Steppes Ardentes."},
[4742]={"Le sceau de l'ascension","Trouver les trois gemmes de commandement : la Gemme de Smolderthorn, la Gemme de Pierre-du-pic et la Gemme de Bloodaxe. Rapportez-les, ainsi que le Sceau d'ascension non décoré, à Vaelan. Les généraux, comme vous l'a dit Vaelan, sont : le maître de guerre Voone de Smolderthorn ; le généralissime Omokk des Pierres-du-pic ; et le seigneur Wyrmthalak de Bloodaxe."},
[4764]={"Le fermoir de Doomrigger","Apporter le Fermoir de Doomrigger à Mayara Brightwing, dans les Steppes ardentes."},
[4768]={"La tablette de Darkstone","Apporter la Tablette de Darkstone à l'ombremage Vivian Lagrave à Kargath."},
[4771]={"Le gambit de l'aube","Placer le Gambit de l'aube dans la Chambre des visions de Scholomance. Vaincre Vectus, puis retourner auprès de Betina Bigglezink."},
[4787]={"L'oeuf antique","Apporter l'Oeuf antique à Yeh'kinya à Tanaris."},
[4788]={"Les dernières tablettes","Apporter la cinquième et la sixième Tablette Mosh'aru au Prospecteur Ironboot à Tanaris."},
[4808]={"Felnok Steelspring","Donner la Lettre de Tinkee à Felnok Steelspring."},
[4809]={"Cornes de Noroît","Apporter 8 Cornes intactes de Noroît à Felnok Steelspring."},
[4810]={"Retourner voir Tinkee","Apporter le Paquet de Felnok à Tinkee Steamboil dans les Steppes ardentes."},
[4862]={"Mauvais","Aller au Pic Blackrock et ramasser 15 Oeuf d'araignée du pic pour Kibler. Ces oeufs peuvent être trouvés à proximité des araignées."},
[4866]={"Le lait matriarcal","Vous trouverez la Matriarche Couveuse au coeur du pic Blackrock. Attaquez-la et poussez-la à vous empoisonner. Vous devrez sans doute la tuer. Une fois <empoisonné/empoisonnée>, trouvez John le Loqueteux afin qu'il puisse prélever un échantillon."},
[4867]={"Urok Hurleruine","Lire le Parchemin de Warosh. Apporter le Mojo de Warosh à Warosh."},
[4903]={"Ordre du chef de guerre","Tuer le généralissime Omokk, le maître de guerre Voone et le seigneur Wyrmthalak. Récupérer les Importants documents Blackrock. Retourner voir le chef de guerre Goretooth à Kargath une fois la mission accomplie."},
[4907]={"Tinkee Steamboil","Parler à Tinkee Steamboil."},
[4941]={"Sagesse d'Eitrigg","Parler à Eitrigg, à Orgrimmar. Après avoir discuté avec Eitrigg, demander conseil à Thrall. Vous avez déjà vu Eitrigg dans les Appartements de Thrall."},
[4974]={"Pour la Horde !","Aller au Pic Blackrock et tuer le Chef de guerre, Rend Blackhand. Prendre sa tête et retourner à Orgrimmar."},
[4981]={"Agent Bijou","Aller au Pic Blackrock et découvrir ce qui est arrivé à Bijou."},
[4982]={"Les effets de Bijou","Trouver les Affaires de Bijou et les lui rapporter. Elle vous a dit les avoir cachées dans le niveau inférieur de la ville."},
[4983]={"Rapport de reconnaissance de Bijou","Rapporter le Rapport de reconnaissance de Bijou au Grand-maître Lexlort, à Kargath."},
[5001]={"Les effets de Bijou","Retrouver les Affaires de Bijou et les lui rapporter. Bonne chance !"},
[5002]={"Message à Maxwell","Se rendre dans les Steppes ardentes et confier les Renseignements de Bijou au maréchal Maxwell."},
[5047]={"Pépin Preste-Jugeote, à votre service !","Parler à Malyfous Darkhammer à Long-guet."},
[5065]={"Les tablettes perdues de Mosh'aru","Apporter la troisième et la quatrième tablette Mosh'aru au Prospecteur Ironboot à Tanaris."},
[5081]={"Mission de Maxwell","Se rendre au Pic Blackrock et tuer le maître de guerre Voone, le généralissime Omokk, et le seigneur Wyrmthalak. Retourner auprès du maréchal Maxwell quand la tâche a été accomplie."},
[5089]={"Ordres du général Drakkisath","Remettre les Ordres du général Drakkisath au maréchal Maxwell dans les Steppes ardentes."},
[5102]={"La reddition du général Drakkisath","Rendez-vous au Pic Blackrock et tuez le général Drakkisath, puis retournez voir le maréchal Maxwell."},
[5122]={"Le médaillon de foi"},
[5125]={"L'estimation d'Aurius"},
[5127]={"La forge démoniaque","Se rendre au pic Blackrock et trouver Goraluk Anvilcrack. Le tuer puis utiliser la Pique tachée de sang sur son cadavre. Après avoir siphonné son âme, la pique sera devenue Tachée d'âme. Trouver aussi la Cuirasse couverte de runes inachevée. Rapporter la Pique tachée d'âme et la Cuirasse couverte de runes inachevée à Lorax au Berceau-de-l'Hiver."},
[5160]={"Le Protectorat de la matrone","Aller jusqu’au Berceau-de-l'Hiver et trouver Haleh. Lui donner l’Ecaille d'Awbee."},
[5212]={"La chair ne ment pas","Récupérer 20 Echantillons de chair pestiférée à Stratholme puis les rapporter à Betina Bigglezink. Vous pensez que toutes les créatures de Stratholme possèdent de tels échantillons de chair."},
[5213]={"L'agent actif","Se rendre jusqu’à Stratholme et fouiller les ziggourats. Trouver et ramener de nouvelles informations sur le Fléau à Betina Bigglezink."},
[5214]={"Le grand Ezra Grimm","Trouver le magasin de tabac d’Ezra Grimm à Stratholme et récupérer une boîte de Tabac d’Ezra. Retourner auprès de Smokey LaRue quand ce sera fait."},
[5243]={"Les demeures du Sacré","Se rendre à Stratholme, au nord. Fouiller les caisses de fournitures qui encombrent la cité et récupérer 5 Eaux sacrées de Stratholme. Retourner auprès de Leonid Barthalomew le Révéré quand vous avez récolté assez de liquide béni."},
[5244]={"Les ruines de Kel'Theril","Parler à Jaron Stoneshaper au village de Pluie-d'Etoiles"},
[5245]={"Les Esprits troublés de Kel'Theril","Utiliser la Pique de Jaron pour trouver les quatre Fragments de relique des Bien-nés. Les apporter à Aurora Skycaller dans les Maleterres de l’est."},
[5246]={"Fragments du passé","Trouver les Ecrits sacrés des Bien-nés dans le temple de Zin-Malor à Azshara et les apporter à Aurora Skycaller à la tour du Col du nord, dans les Maleterres de l'est."},
[5247]={"Fragments du passé","Apporter une Barre de thorium enchanté, 5 Cristaux de restauration et une Fiole d'eau redoutable à Aurora Skycaller à la tour du Col du nord, dans les Maleterres de l’est."},
[5251]={"L'archiviste","Voyager jusqu’à Stratholme et trouver l’Archiviste Galford de la Croisade écarlate. L’abattre et brûler les Archives écarlates."},
[5262]={"La vérité vient du ciel","Apporter la Tête de Balnazzar au duc Nicholas Zverenhoff dans les Maleterres de l’est."},
[5263]={"Au-dessus et au-delà","S’aventurer dans Stratholme et tuer le baron Rivendare. Prendre sa tête et retourner auprès du duc Nicholas Zverenhoff."},
[5281]={"Âmes tourmentées","Trouver Egan. Vous savez seulement qu’on l’a vu pour la dernière fois aux alentours de Stratholme."},
[5282]={"Âmes tourmentées","Se servir du Libérateur d'Egan sur les citoyens fantomatiques et spectraux de Stratholme. Quand les esprits sans repos se libèrent de leur enveloppes fantomatiques, utiliser de nouveau le Libérateur – ils seront enfin libres ! Libérer 15 Esprits sans repos puis retourner auprès d’Egan."},
[5341]={"Fortune de la famille Barov","S’aventurer jusqu’à Scholomance et récupérer la fortune de la famille Barov. Cette fortune se compose de quatre titres de propriété : le titre de propriété de Caer Darrow ; le titre de propriété de Brill ; le titre de propriété de Moulin-de-Tarren ; et le titre de propriété de Southshore. Revenir auprès d’Alexi Barov quand la tâche est accomplie."},
[5343]={"Fortune de la famille Barov","S’aventurer jusqu’à la Scholomance et récupérer la fortune de la famille Barov. Cette fortune se compose de quatre titres de propriété : le titre de propriété de Caer Darrow ; le titre de propriété de Brill ; le titre de propriété de Moulin-de-Tarren ; et le titre de propriété de Southshore. Revenir auprès de Weldon Barov quand la tâche est accomplie."},
[5382]={"Docteur Theolen Krastinov, le boucher","Trouver le docteur Theolen Krastinov à l’intérieur de la Scholomance. Le tuer, puis brûler le Cadavre d’Eva Sarkhoff et le Cadavre de Lucien Sarkhoff. Retourner auprès d’Eva Sarkhoff quand la tâche est accomplie."},
[5384]={"Kirtonos le héraut","Revenir à Scholomance avec le Sang des innocents. Trouver le porche et placer le Sang des innocents dans le brasero. Kirtonos viendra dévorer votre âme. Combattre vaillamment, sans perdre un pouce de terrain ! Détruire Kirtonos et revenir auprès d’Eva Sarkhoff."},
[5461]={"L'humain, Ras Murmegivre","Voyager jusqu’aux hautes-terres d'Arathi, et aller aux ruines de Stromgarde. Fouiller Stromgarde pour trouver un Souvenir de la mémoire. Si une telle trouvaille est faite, rapporter l’objet au magistrat Marduke."},
[5462]={"Le moribond, Ras Murmegivre","Voyager jusqu’à l’Espoir de lumière dans les Maleterres de l'est et trouver Leonid Barthalomew le Révéré. Lui montrer le Souvenir de la mémoire et lui dire tout ce que vous avez découvert."},
[5463]={"Le cadeau de Menethil","Voyager jusqu’à Stratholme et trouver le cadeau de Menethil. Placer le Souvenir de la mémoire sur le sol impie."},
[5464]={"Le cadeau de Menethil","Apporter le Souvenir lié à Leonid Barthalomew dans les Maleterres de l’est."},
[5465]={"Souvenir lié","Retourner auprès du Magistrat Marduke à Caer Darrow. Lui montrer le Souvenir lié."},
[5466]={"La Liche, Ras Murmegivre","Trouver Ras Murmegivre dans Scholomance. Après l’avoir trouvé, utiliser le Souvenir lié sur son visage mort-vivant. Si sa transformation en mortel réussit, l’abattre et prendre la Tête humaine de Ras Murmegivre. Apporter la tête au Magistrat Marduke."},
[5515]={"Sac des horreurs de Krastinov","Trouver Jandice Barov dans Scholomance et la tuer. Sur son cadavre, récupérer le Sac des horreurs de Krastinov. Rapporter le sac à Eva Sarkhoff."},
[5522]={"Leonid Barthalomew","Apporter les Oeufs congelés à Leonid Barthalomew dans les Maleterres de l’est."},
[5526]={"Fragment de la Gangrevigne","Trouvez la Gangrevigne à Hache-tripes et prenez-en un fragment. Il est probable que vous ne pourrez vous en emparer qu’après la mort d’Alzzin le Modeleur. Servez-vous du Reliquaire de Pureté pour conserver le fragment, et retournez à Reflet-de-Lune voir Rabine Saturna au village de Havrenuit."},
[5527]={"Un reliquaire de pureté","Rendez-vous en Silithus et cherchez un Reliquaire de pureté dans les ruines du village de Sudevent. Si vous parvenez à le trouver, ramenez-le à Rabine Saturna à Havrenuit, Reflet-de-Lune."},
[5529]={"Portée contaminée","Tuer 20 Jeunes pestiférés, puis retourner auprès de Betina Bigglezink à la Chapelle de l’Espoir de Lumière."},
[5531]={"Betina Bigglezink","Apporter les Oeufs congelés à Betina Bigglezink."},
[5533]={"Scholomance","Parler à l’alchimiste Arbington à la pointe du Noroît, dans les Maleterres de l’ouest."},
[5722]={"À la recherche de la sacoche perdue","Fouiller le Gouffre de Ragefeu pour trouver le cadavre de Maur Grimtotem et tout élément intéressant."},
[5723]={"Tester la force de l'ennemi","Chercher le gouffre de Ragefeu dans Orgrimmar, puis tuer 8 Troggs Ragefeu et 8 Chamans Ragefeu avant de revenir auprès de Rahauro à Thunder Bluff."},
[5724]={"Rapporter la sacoche perdue","Apporter la Sacoche du Totem sinistre à Rahauro à Thunder Bluff."},
[5725]={"Le pouvoir de détruire...","Apporter les livres de Sorts des Ombres et d’Incantations du Néant à Varimathras, à Undercity."},
[5726]={"Ennemis cachés","Apporter un Insigne de lieutenant à Thrall à Orgrimmar."},
[5727]={"Ennemis cachés","Apporter l'Insigne du Lieutenant à Neeru Fireblade et lui parler. Essayer de déterminer s'il vous croit membre de la Lame ardente puis retourner voir Thrall à Orgrimmar."},
[5728]={"Ennemis cachés","Tuer Bazzalan et Jergosh l'Invocateur avant de retourner voir Thrall à Orgrimmar."},
[5761]={"Tuer la bête","Pénétrer dans le Gouffre de Ragefeu et tuer Taragaman l'Affameur, puis rapporter son coeur à Neeru Fireblade à Orgrimmar."},
[5848]={"De l'amour et de la famille","Se rendre à Stratholme, dans la partie nord des Maleterres. C’est dans le Bastion écarlate que se trouve le tableau De l'amour et de la famille, caché derrière une autre peinture représentant les lunes jumelles. Rapporter le tableau à Tirion Fordring."},
[6022]={"Tuer utile","Allez à l'est à la Croisée de Corin et détruisez les membres du Fléau qui habitent la ville. Rassemblez sept morceaux de Pourriture vivante en moins de dix minutes. Utilisez le Mortier et le pilon pour réduire la Pourriture vivante en Pourriture coagulée."},
[6042]={"Les petits soucis de la non-vie","Tuer 20 Chauves-souris pestiférées nuisibles et 10 Chauves-souris pestiférées monstrueuses. Retourner voir Nathanos le Flétrisseur quand ce sera fait."},
[6133]={"L'ordre du seigneur forestier","Aller vers la frontière nord des Maleterres de l’est et récupérer le Registre de Quel'Thalas. L’objet se trouve quelque part dans le gîte de Quel'Lithien. Tuer également 8 Forestiers, 8 Eclaireurs et 8 Bûcherons."},
[6135]={"Crépuscaile, oh comme je te hais !","Trouver Crépuscaile et la tuer. Récupérer une Touffe de fourrure de Crépuscaile sur son cadavre, puis l’apporter à Nathanos le Flétrisseur. Il paraît que Crépuscaile hante les terres qui se trouvent au nord de la ferme des Marris."},
[6136]={"Le corpulent","Trouver Creusechair, dans les terres au nord des Maleterres de l’est, et le tuer. Retourner voir Nathanos le Flétrisseur quand la mission sera terminée."},
[6163]={"Ramstein","Aller à Stratholme et tuer Ramstein Grandgosier. Prendre sa tête, et l’apporter à Nathanos."},
[6402]={"Le rendez-vous à Stormwind","Aller à la Cité de Stormwind et se rendre aux portes de la ville. Parlez à l'écuyer Rowe, afin qu'il informe le maréchal Windsor de votre arrivée."},
[6403]={"La grande mascarade","Suivre Reginald Windsor dans Stormwind. Le protéger contre toute menace !"},
[6501]={"L'Œil de dragon","Vous devez écumer le monde pour pouvoir rétablir le pouvoir du Fragment de l'Oeil de dragon. La seule information dont vous disposez à propos de cette chose, c’est qu’elle existe."},
[6502]={"Amulette drakefeu","Récupérer le Sang du Champion des dragons noirs sur le général Drakkisath. Il se trouve dans sa salle du trône, derrière les Halls d'Ascension, sur le Pic Blackrock."},
[6521]={"Une alliance impie","Apporter la Tête de l'Ambassadeur Malcin à Varimathras, à Undercity."},
[6522]={"Une alliance impie","Apporter le Petit parchemin à Varimathras, à Undercity."},
[6561]={"L'infamie de Brassenoire","Apporter la tête du Seigneur du crépuscule Kelris à Bashana Runetotem, à Thunder Bluff."},
[6562]={"Problèmes dans les profondeurs","Parler à Je'neu Sancrea, à Ashenvale."},
[6563]={"L'Essence d'Aku'Mai","Apporter 20 Saphirs d'Aku'Mai à Je'neu Sancrea, à Ashenvale."},
[6564]={"Allégeance aux Dieux très anciens","Apporter la Note humide à Je'neu Sancrea, à Ashenvale."},
[6565]={"Allégeance aux Dieux très anciens","Tuer Lorgus Jett, dans les Profondeurs de Brassenoire et retourner voir Je'neu Sancrea, à Ashenvale."},
[6566]={"Ce que le vent apporte","Écouter Thrall."},
[6567]={"Le Champion de la Horde","Chercher Rexxar. Le Chef de guerre vous a dit où il était. Chercher sur les chemins de Désolace, entre les Serres-Rocheuses et Feralas."},
[6568]={"Le testament de Rexxar","Apporter le Testament de Rexxar à Myranda la Mégère, dans les Maleterres de l’ouest."},
[6569]={"Illusions d'Occulus","Aller au Pic Blackrock et collecter 20 Yeux de draconide noir. Retourner voir Myranda la Mégère, quand la tâche sera terminée."},
[6570]={"Brandeguerre","Aller à la tourbière du Ver, dans le marécage d'Âprefange, et chercher la tanière de Brandeguerre. Une fois à l’intérieur, porter l’Amulette de subversion draconique, et parler à Brandeguerre."},
[6582]={"L'épreuve des crânes, Clairvoyant","Vous devez trouver Clairvoyant, le drake champion du Vol bleu, et le tuer. Arracher son crâne à son cadavre, et le rapporter à Brandeguerre. Clairvoyant se trouve au Berceau-de-l'Hiver."},
[6583]={"L'épreuve des crânes, Somnus","Détruire le Champion drake du Vol vert, Somnus. Arracher son crâne à son cadavre, puis le rapporter à Brandeguerre."},
[6584]={"L'épreuve des crânes, Chronalis","Chronalis, enfant de Nozdormu, garde les Grottes du temps, dans le Désert de Tanaris. Tuez-le et rapportez son crâne à Brandeguerre."},
[6585]={"L'épreuve des crânes, Axtroz","Aller à Grim Batol et traquer Axtroz, le Champion drake du Vol rouge. Le tuer et arracher son crâne, puis l’apporter à Brandeguerre."},
[6601]={"Ascension...","Il semble que la comédie soit finie. Vous savez que l’Amulette de subversion draconique, créée par Myranda la Mégère, ne fonctionnera pas à l’intérieur du pic Blackrock. Peut-être devriez-vous trouver Rexxar et lui exposer votre fâcheuse situation. Montrez-lui l'Amulette drakefeu terne. Avec un peu de chance, il saura quoi faire."},
[6602]={"Le sang du champion des dragons noirs","Aller au Pic Blackrock, et tuer le général Drakkisath. Récupérer son sang et retourner voir Rexxar."},
[6626]={"L'hôte du mal","Tuer 8 Gardes de guerre Tranchebauge, 8 Tisseurs d'épines Tranchebauge et 8 Sectateur de la Tête de mort, puis retourner voir Myriam Moonsinger, à l’entrée des Souilles de Tranchebauge."},
[6627]={"L'épreuve de la Connaissance","Réussir à répondre à la question de Braug Dimspirit, puis lui reparler. Il se trouve dans les Serres-Rocheuses."},
[6628]={"L'épreuve de la Connaissance","Réussir à répondre à la question de Parqual Fintallas, puis lui reparler. Il se trouve à Undercity."},
[6642]={"Faveur auprès de la Confrérie, Minerai de sombre fer"},
[6643]={"Faveur auprès de la Confrérie, Noyau de feu"},
[6644]={"Faveur auprès de la Confrérie, Noyau de lave"},
[6645]={"Faveur auprès de la Confrérie, Cuir du Magma"},
[6646]={"Faveur auprès de la Confrérie, Sang de la montagne"},
[6804]={"Eau empoisonnée","Utiliser l’Aspect de Neptulon sur les élémentaires empoisonnés des Maleterres de l’est. Apporter 12 Bracelets discordants et l’Aspect de Neptulon au duc Hydraxis, en Azshara."},
[6805]={"Tempêtes","Tuer 15 Tempétueux de poussière et 15 Grondeurs du désert, puis retourner voir le duc Hydraxis, en Azshara."},
[6821]={"Oeil du Prophète ardent","Apporter l’Oeil du Prophète ardent au duc Hydraxis, en Azshara."},
[6822]={"Le Cœur du Magma","Tuer 1 Seigneur du feu, 1 Géant de lave, 1 Chien antique du Magma et 1 Surgisseur de lave, puis retourner voir le duc Hydraxis, à Azshara."},
[6823]={"Agent de Hydraxis","Parvenir au niveau de réputation Honoré auprès des Hydraxiens, puis parler au duc Hydraxis, en Azshara."},
[6824]={"Les mains de l'ennemi","Apporter les Mains de Lucifron, de Sulfuron, de Gehennas et de Shazzrah au duc Hydraxis, en Azshara."},
[6921]={"Parmi les ruines","Apporter le Noyau de la brasse à Je'neu Sancrea, à l’Avant-poste de Zoram'gar, dans Ashenvale."},
[6922]={"Baron Aquanis","Apporter le Globe d'eau étrange à Je'neu Sancrea, à l’Avant-poste de Zoram'gar, dans Ashenvale."},
[6981]={"L'Eclat luminescent","Allez à Ratchet pour trouver quelqu'un qui puisse vous en dire plus sur l'Eclat luminescent. Puis livrez l'Eclat, selon les instructions."},
[7028]={"Forces maléfiques retorses","Collecter 25 Ciselures de Cristaux Théradriques pour Saule, en Désolace."},
[7029]={"La corruption de Vylelangue","Remplir la Fiole céruléenne renforcée, au Bassin de cristal orange, dans Maraudon. En faire usage sur les Vignes de Vylevrille pour forcer les Engeances de Noxxious corrompues à en sortir. Soigner 8 plantes en tuant les Engeances de Noxxious, puis retourner voir Vark Battlescar, à Proie-de-l'Ombre."},
[7041]={"La corruption de Vylelangue","Remplir la Fiole céruléenne renforcée, au Bassin de cristal orange dans Maraudon. En faire usage sur les vignes de Vylevrille pour forcer les Engeances de Noxxious corrompues à en sortir. Soigner 8 plantes en tuant les Engeances, puis retourner voir Taliendra, à la Combe de Nijel."},
[7044]={"Légendes de Maraudon","Retrouver les deux parties du Sceptre de Celebras : le Bâtonnet de Celebras et le Diamant de Celebras. Trouvez un moyen de parler à Celebras."},
[7046]={"Le sceptre de Celebras","Aidez Celebras le Racheté pendant qu'il recrée le Sceptre de Celebras. Parlez-lui après la réussite du rituel."},
[7064]={"Corruption de la terre et de la graine","Anéantir la princesse Theradras et retourner voir Selendra près de Proie-de-l'Ombre, en Désolace."},
[7065]={"Corruption de la terre et de la Graine","Tuer la princesse Theradras, et retourner voir le Gardien Marandis, à la Combe de Nijel en Désolace."},
[7066]={"Graine de vie","Chercher Remulos à Reflet-de-Lune, et lui donner la Graine de vie."},
[7067]={"Les instructions du paria","Lire les instructions du paria. Après cela, obtenir l'Amulette d'union de Maraudon et la ramener au centaure renégat, dans le sud de Désolace."},
[7068]={"Fragments d'Ombréclat","Collecter 10 Fragments d'Ombréclats dans Maraudon, et les ramener à Uthel'nay, à Orgrimmar."},
[7070]={"Fragments d'Ombréclat","Collecter 10 Fragments d'Ombréclats, et les porter à l'archimage Tervosh, dans le marécage d'Âprefange."},
[7201]={"Le dernier élément","Partir pour les Profondeurs de Blackrock et trouver 10 Essences des éléments. Commencer vos recherches par les golems et par les créateurs de golems. Vivian Lagrave a aussi marmonné quelque chose à propos d'élémentaires."},
[7441]={"Pusillin et l'Ancien Azj'Tordin","Rendez-vous à Hache-tripes et trouvez le diablotin Pusillin. Persuadez-le par tous les moyens de vous rendre le Livre d’Incantations d’Azj’Tordin. Si vous parvenez à le récupérer, retournez voir Azj’Tordin au Pavillon de Lariss, en Feralas."},
[7461]={"Folie intérieure","Vous devez détruire les gardiens qui protègent les 5 Pylônes qui alimentent la Prison d’Immol’thar. Une fois que les Pylônes seront coupés, le champ de force qui entoure Immol’thar se dissipera. Entrez dans la Prison d’Immol’thar et éradiquez l’infâme démon qui se trouve en son cœur. Enfin, affrontez le prince Tortheldrin à l’Athenaeum. Lorsque vous aurez terminé, retournez voir l’Ancienne des Shen’dralar dans la cour."},
[7462]={"Le trésor des Shen'dralar","Retournez à l’Athenaeum et trouvez le Trésor des Shen’dralar. Prenez votre récompense !"},
[7463]={"Rafraîchissement arcanique","Rendez-vous dans le quartier de Crochebois de Hache-tripes et tuez Hydrogénos, l’élémentaire de l’eau. Retournez voir le Gardien du savoir Lydros à l’Athenaeum avec l’Essence d’Hydrogénos."},
[7481]={"Légendes elfiques","Fouillez Hache-tripes à la recherche de Telmius Cherche-Rêve. Lorsque vous aurez des informations, donnez-les au Sage Korolusk du Camp Mojache."},
[7482]={"Légendes elfiques","Fouillez Hache-tripes à la recherche de Telmius Cherche-Rêve. Lorsque vous aurez des informations, donnez-les à l’Erudite Runethorn, à Feathermoon."},
[7486]={"La récompense du héros","Allez chercher votre récompense dans le Coffre d’Hydraxis."},
[7488]={"Le filet de Lethtendris","Ramenez le Filet de Lethtendris à Latronicus Moonspear au bastion de Feathermoon en Feralas."},
[7489]={"Le filet de Lethtendris","Ramenez le Filet de Lethtendris à Talo Thornhoof au Camp Mojache, en Feralas."},
[7490]={"Victoire pour la Horde !","Apportez la Tête d’Onyxia à Thrall à Orgrimmar."},
[7491]={"Pour que tous voient","Allez voir le seigneur Runthak dans la vallée de la Force."},
[7493]={"Le voyage commence à peine"},
[7495]={"Victoire pour l'Alliance !","Apportez la Tête d’Onyxia au généralissime Bolvar Fordragon à Stormwind."},
[7496]={"Célébrer le triomphe","Allez voir le major Mattingly dans la vallée des Héros."},
[7497]={"Le voyage commence à peine"},
[7498]={"Garona : une étude en discrétion et en trahison","Rendez ce livre à ses légitimes propriétaires."},
[7499]={"Le codex de défense","Rendez ce livre à ses légitimes propriétaires."},
[7500]={"Les recettes de l’arcaniste","Rendez ce livre à ses légitimes propriétaires."},
[7501]={"La lumière et comment l'altérer","Rendez ce livre à ses légitimes propriétaires."},
[7502]={"Contrôler les ombres","Rendez ce livre à ses légitimes propriétaires."},
[7503]={"La plus grande race de chasseurs","Rendez ce livre à ses légitimes propriétaires."},
[7504]={"Sainte Bolognaise : Ce que la lumière ne vous dit pas","Rendez ce livre à ses légitimes propriétaires."},
[7505]={"Le Horion de givre et vous","Rendez ce livre à ses légitimes propriétaires."},
[7506]={"Le Rêve d'Emeraude…","Rendez ce livre à ses légitimes propriétaires."},
[7507]={"Le guide de Dagharn","Rapporter « Le guide de Nostro du tueur de dragons » à l’Athenaeum."},
[7508]={"Forger Quel'Serrar","Donnez la Lame elfique inachevée au Gardien du savoir Lydros."},
[7509]={"Forger Quel'Serrar","Vous devez amener Onyxia à cracher le feu sur la Lame ancienne brute. Lorsque ce sera fait, ramassez la Lame ancienne chauffée. Attention, elle ne restera pas chaude éternellement. Le temps est très important. Avant de revenir me voir, il vous faudra tuer la bête et plonger la Lame ancienne chauffée dans son cadavre. Si vous y parvenez, Quel’Serrar sera à vous."},
[7563]={"Rage de sang","Apporter 30 bouteilles de Sang de bêtes enragées à Mor'zul Bloodbringer dans les Steppes ardentes."},
[7564]={"Gorzeeki Wildeyes","Apporter la Caisse de sang à Gorzeeki Wildeyes dans les Steppes ardentes."},
[7604]={"Un contrat contraignant","Apportez le Contrat de la Confrérie du Thorium à Lokhtos Darkbargainer, si vous voulez recevoir les plans du marteau de sulfuron."},
[7621]={"Un avertissement (optional explanation)"},
[7622]={"L’équilibre de la Lumière et de l’Ombre","Sauvez 50 Paysans avant que 15 d'entre eux aient été tués. Si vous y parvenez, allez parler à Eris Havenfire. Consultez le Panneau des morts pour voir combien de paysans ont été tués."},
[7623]={"Le seigneur Banehollow","Achetez des Potions des ténèbres à Gorzeeki dans les Steppes ardentes. Servez-vous en pour vous rendre à Jaedenar, et parlez au seigneur Banehollow."},
[7624]={"Ulathek le traître","Affrontez Ulathek, puis apportez le Coeur du traître au seigneur Banehollow à Jaedenar."},
[7625]={"Poussière d'étoile xorothienne","Acheter de la Poussière d’étoiles xorothienne à Ur’dan. L’apporter à Gorzeeki dans les Steppes ardentes."},
[7629]={"Livraison de diablotin","Apporter le Diablotin en bouteille au laboratoire d'alchimie de la Scholomance. Une fois le parchemin créé, retournez voir Gorzeeki Wildeyes."},
[7631]={"Le destrier de l'effroi de Xoroth","Lisez les Instructions de Mor’zul. Invoquez un Destrier de l’effroi xorothien, vainquez-le, et liez son esprit."},
[7632]={"La feuille ancienne","Trouvez le propriétaire de la Feuille ancienne pétrifiée. Bonne chance, <nom>, le monde est vaste."},
[7634]={"Feuille d'Ancien cousue de tendons","L'Ancien Hasat vous demande de lui ramener un Tendon de dragon bleu adulte. Si vous en trouvez un, ramenez-le-lui à Gangrebois"},
[7635]={"La bonne corde","L’Ancien Stoma vous demande de lui ramener un Tendon de dragon noir adulte. Si vous en trouvez un, ramenez-le à Stoma à Gangrebois."},
[7636]={"Le bâton des Anciens","Vous devez trouver et tuer quatre corrupteurs démoniaques : Simona la Séductrice. Klinfran l’Enragé. Solenor le Tueur. Artorius le Néfaste. Détruisez ces créatures et retournez voir l’Ancien Vartus à Gangrebois. Vous trouverez des indices sur leurs faits et gestes sur l’Ecorce pétrifiée qui se trouve dans votre inventaire. Vous DEVEZ agir seul."},
[7637]={"L'accent sur le sacrifice","Rendez-vous à Ironforge et procurez-vous l’Encensoir d’exorcisme du grand prêtre Rohan. Pour vous le procurer, il vous faudra verser une donation de 150 pièces d’or."},
[7639]={"Des preuves de jugement","Ramener l’Encensoir d’exorcisme au seigneur Grayson Shadowbreaker, dans le Quartier de cathédrale de Stormwind."},
[7640]={"Exorciser Val-Terreur","Servez-vous de l’Encensoir d’exorcisme pour chasser les esprits qui tourmentent Val-Terreur. Lorsque vous aurez tué 25 Esprits de Val-Terreur, retournez voir le seigneur Grayson Shadowbreaker dans le Quartier de la cathédrale de Stormwind."},
[7641]={"L'œuvre de Grimand Elmore","Parlez à Grimand Elmore dans le Quartier des nains de Stormwind."},
[7642]={"Une ribambelle d'objets","Apporter 40 Etoffes runiques, 6 Barres d’arcanite, 10 Larmes d’Arthas, 5 Fioles d’eau sacrée de Stratholme, et 150 pièces d’or à Grimand Elmore, au Quartier des nains de Stormwind."},
[7643]={"L'ancien esprit équin","Procurez-vous un aliment pour chevaux capable de nourrir un esprit équin. Il semble que Merideth Carlson, à Southshore, sache en fabriquer. Ensuite, rendez-vous au donjon de Hache-tripes en Feralas, et tuez Tendris Crochebois. Sa mort libérera l’Ancien esprit équin. Nourrissez-le avec l’aliment spécial afin de l’apaiser. Enfin, donnez-lui le Caparaçon d’arcanite pour qu’il le bénisse."},
[7644]={"Le caparaçon en arcanite béni","Retourner dans le quartier de la cathédrale de Stormwind avec le Caparaçon d’arcanite béni pour voir le seigneur Grayson Shadowbreaker."},
[7646]={"Le Clairvoyant","Apportez un Diamant d’Azeroth et un Diamant noir en parfait état au seigneur Grayson Shadowbreaker dans le Quartier de la cathédrale de Stormwind."},
[7647]={"Jugement et rédemption","Utilisez le Clairvoyant au coeur du sous-sol du Grand ossuaire, dans la Scholomance. Cela attirera des esprits que vous devrez juger. Lorsqu’ils seront vaincus, le Chevalier de la mort Ravassombre apparaîtra. Vainquez-le et purifiez l’âme du destrier déchu. Ensuite, donnez l’Ame rachetée du destrier et le Caparaçon enchanté et béni au Destrier déchu de Ravassombre."},
[7648]={"Le chef d'œuvre de Grimand","Présentez le Caparaçon d’arcanite au seigneur Grayson Shadowbreaker dans le Quartier de la cathédrale de Stormwind, pour inspection."},
[7667]={"Assistance matérielle","Si vous voulez aider Sagorne Crestrider de la vallée de la Sagesse d'Orgrimmar, apportez-lui un Diamant d’Azeroth et un Diamant noir en parfait état."},
[7703]={"Affaires inachevées chez les Gordok","Trouvez le Gantelet de Puissance Gordok et rendez-le au capitaine Kromcrush à Hache-tripes. Selon Kromcrush, les histoires des « vieux » racontent que Tortheldrin – un « vilain » elfe qui se fait appeler prince – l’a volé à l’un des rois gordok."},
[7761]={"Les ordres de Blackhand","Cet orc est stupide. Il semble que vous deviez trouver un moyen d’obtenir la Marque de Drakkisath pour accéder à l’Orbe de commandement. D’après la lettre, la Marque est gardée par le général Drakkisath. Vous devriez peut-être enquêter."},
[7781]={"Le seigneur de Blackrock","Apporter la Tête de Nefarian au généralissime Bolvar Fordragon à Stormwind."},
[7782]={"Le seigneur de Rochenoire","Allez à la vallée des Héros de Hurlevent et parlez au grand maréchal Afrasiabi."},
[7783]={"Le seigneur de Blackrock","Apportez la Tête de Nefarian à Thrall à Orgrimmar."},
[7784]={"Le seigneur de Blackrock","Parlez au Haut seigneur Saurfang à Orgrimmar. Il vous attend dans la vallée de la Force."},
[7785]={"Examiner le Calice","Examiner le Calice de la renaissance et le rapporter au généralissime Demitrian."},
[7786]={"Thunderaan le Cherchevent","Pour libérer Thunderaan le Cherchevent de sa prison, vous devez présenter au généralissime Demetrian les moitiés droite et gauche des Liens du Cherchevent, 10 barres d'élémentium, et l'Essence du Seigneur du feu."},
[7787]={"Éveille-toi, Lame-tonnerre !","Présenter la Lame du baiser du vent dormante au généralissime Demitrian."},
[7848]={"Harmonisation avec le Cœur du Magma","Aventurez-vous jusqu'au portail d'entrée du Cœur du Magma dans les profondeurs de Blackrock et récupérez un Fragment du Magma. Lorsque ce sera fait, retournez voir Lothos Riftwalker au mont Blackrock."},
