[8153]={"La ramure de coursier","Rapporter deux Ramures de coursier parfaites à Ogtinc en Azshara. Ogtinc vit au sommet des collines au nord-est des ruines d’Eldarath."},
[8181]={"La confrontation avec Yeh'kinya","Parlez à Yeh'kinya."},
[8182]={"La main de Rastakhan","Parlez à Molthor à Strangleronce."},
[8183]={"Le cœur d'Hakkar","Donnez le Cœur d'Hakkar à Molthor sur l'île de Yojamba."},
