[8201]={"Une collection de têtes","Attachez 5 Têtes de canalistes, puis ramenez la Collection de têtes de Gurubashi à Exzhal sur l’île des Zandalar."},
[8227]={"Le mètre ruban de Nat","Rendre le Mètre ruban de Nat à Nat Pagle, au marécage d’Âprefange."},
[8231]={"Vandales des flots","Apporter 6 Ecailles de vandale des flots à Ogtinc en Azshara. Ogtinc demeure au sommet des falaises au nord-est des ruines d'Eldarath."},
[8232]={"Le drake vert","Apporter la Dent de Morphaz à Ogtinc en Azshara. Ogtinc demeure au sommet des falaises au nord-est des ruines d'Eldarath."},
[8233]={"Une requête toute simple","Parlez au seigneur Jorach Ravenholdt, au manoir de Ravenholdt."},
[8234]={"Sac azur scellé","Récupérer le Sac azur scellé auprès du chaman Grumegueule en Azshara. Puis apportez le sac à l'archimage Xylem, également en Azshara."},
[8235]={"Les fragments codés","Apporter 10 Fragments codés à l'archimage Xylem à Azshara."},
[8236]={"La clé d’azur","Rendre la Clé d'azur au seigneur Jorach Ravenholdt."},
[8238]={"Pièces Gurubashi, Vilebranch et Witherbark"},
[8239]={"Pièces Sandfury, Skullsplitter et Bloodscalp"},
[8240]={"Un Bijou pour Zanza","Détruisez n'importe lequel des Bijoux hakkari trouvé à Zul'Gurub à l'Autel de Zanza, sur l'Ile de Yojamba. Quand ce sera fait, parlez à Vinchaxa qui se trouve à côté."},
[8243]={"Puissants breuvages de Zanza"},
[8246]={"Cachets des Zandalar"},
[8250]={"L'art du mage","Trouvez Sanath Lim-Yo et obtenez d'être <mené/menée> à l'archimage Xylem."},
[8251]={"La poussière magique","Procurer 10 doses de Poussière lumineuse à l’archimage Xylem."},
[8252]={"Le corail des sirènes","Récupérer 6 Coraux enchantés et les apporter à l’archimage Xylem."},
[8253]={"Détruire Morphaz","Récupérer le Fragment d’arcane sur Morphaz et le rendre à l’archimage Xylem."},
[8254]={"Aider le Cercle","Chercher Ogtinc en Azshara."},
[8255]={"Courser les coursiers","Récupérer 4 Glandes de coursier en bonne santé et les apporter à Ogtinc en Azshara. Ogtinc réside au sommet des falaises, au nord-est des ruines d’Eldarath."},
[8256]={"L'ichor de non-mort","Récupérer une dose d’Ichor de non-mort pour le compte d’Ogtinc en Azshara. Ogtinc réside au sommet des falaises, au nord-est des ruines d’Eldarath."},
[8257]={"Le sang de Morphaz","Tuez Morphaz dans le temple englouti d’Atal'Hakkar, et ramenez son sang à Greta Sabot-de-mousse à Gangrebois. L’entrée du temple englouti se trouve dans le marais des Chagrins."},
[8258]={"La menace de Ravassombre","Servez-vous du Clairvoyant au centre du sous-sol du Grand ossuaire de la Scholomance. Cela attirera des esprits que vous devrez combattre. Les vaincre fera apparaître le Chevalier de la mort Ravassombre. Tuez-le. Rapportez la Tête de Ravassombre à Sagorne Rôdeur-des-crêtes de la Vallée de la Sagesse, à Orgrimmar."},
[8286]={"Ce que demain apportera","Rendez vous dans les grottes du Temps en Tanaris et trouvez Anachronos, la progéniture de Nozdormu."},
[8288]={"Il ne peut y en avoir qu'un","Rapportez la Tête du seigneur des couvées Lanistaire à Baristolth des Sables changeants, au Fort cénarien en Silithus."},
[8301]={"Le Chemin des Justes","Récupérez 200 Fragments de carapaces de silithides et retournez voir Baristolth."},
[8302]={"La Main des Justes","Récupérez 200 Fragments de carapaces de silithides et retournez voir Baristolth."},
[8303]={"Anachronos","Chercher Anachronos dans les Grottes du temps à Tanaris."},
[8305]={"Des souvenirs oubliés depuis longtemps","Trouvez la Larme cristalline, en Silithus, et contemplez ses profondeurs."},
[8412]={"Le totem des esprits","Apportez les différents morceaux du Totem des esprits à Bath’rah la Vigie des Vents."},
[8413]={"Vaudou !","Apporter les Plumes vaudou à Bath'rah la Vigie des vents."},
[8414]={"La dissipation du mal","Récupérez 20 Pierres du Fléau des serviteurs et apportez-les au grand prêtre Thel'danis dans les Maleterres de l'ouest."},
[8416]={"Pierres du Fléau inertes","Apportez la Pierre du Fléau inerte au commandant Ashlam Vaillepoing à la pointe du Noroît."},
[8417]={"Un esprit troublé","Parlez au Héros de la Horde tombé au combat, à l'entrée des Terres Foudroyées."},
[8418]={"Forger la pierre de pouvoir","Apportez des Plumes vaudou ambres, bleues et vertes."},
[8419]={"La demande d'un diablotin","Apportez un morceau de Gangrétoffe à Démonet à Gangrebois."},
[8420]={"Chaud et piquant","Apportez un morceau de gangrétoffe à Démonet à Gangrebois."},
[8421]={"L'anti-étoffe des héros","Apporter 10 morceaux de Bois pourri et 4 Essences de Vénéneuse à Démonet, en Gangrebois."},
[8422]={"Les trolls d'un même plumage…","Apporter 6 Plumes vaudou des trolls du Temple englouti."},
[8423]={"Fraternité entre guerriers","Tuez 7 Sangliers infernaux dans les Terres Foudroyées, et revenez voir le Héros de la Horde tombé au combat."},
[8424]={"La guerre contre les liges d'ombre","Tuez les Liges d'ombre dans les Terres Foudroyées et revenez voir le Héros de la Horde tombé au combat."},
[8425]={"Plumes vaudou","Apportez les Plumes vaudou des trolls du Temple englouti au Héros de la Horde tombé au combat."},
[8519]={"Un pion sur l'Echiquier éternel","Apprenez tout ce que vous pouvez au sujet du passé, puis parlez à Anachronos dans les Grottes du temps à Tanaris."},
[8544]={"Les spallières de conquérant","Apportez des Manchettes de commandement qiraji, 2 Idoles de la nuit, 5 Scarabées de pierre et 5 Scarabées d’argile à Andorgos, à Ahn’Qiraj. Pour terminer cette quête, la Progéniture de Nozdormu doit au moins être Neutre à votre égard."},
[8555]={"Le fardeau des Vols draconiques"},
[8556]={"Chevalière de force inflexible","Apporter 1 Anneau de magistrat qiraji, 2 Idoles brillantes, 5 Scarabées en bronze et 5 Scarabées d'ivoire à l'imploratrice céleste Yessendra, en Silithus. Vous devrez aussi être <Honoré/Honorée> par le Cercle cénarien pour terminer cette quête."},
