[8784]={"Les secrets des Qiraji","Remettre l’Ancien artefact qiraji aux dragons qui se cachent près de l’entrée du temple."},
[8789]={"Les armes impériales qiraji","Arygos, dans le temple d’Ahn’Qiraj, vous fabriquera des armes imprégnées d’élémentium si vous lui procurez des Armes impériales qiraji et 3 Minerais d’élémentium."},
[8790]={"L'équipement impérial qiraji","Merithra du Rêve, au temple d’Ahn’Qiraj, vous fabriquera des armes imprégnées d’élémentium si vous lui ramenez un Equipement impérial qiraji et 3 Minerais d’élémentium."},
[8791]={"La chute d'Ossirian","Remettez la Tête d’Ossirian l’Intouché au commandant Mar’alith, au Fort cénarien en Silithus."},
[8801]={"L'héritage de C'Thun","Remettre l’Oeil de C’Thun a Caelastrasz, dans le temple d’Ahn’Qiraj."},
[8802]={"Le sauveur de Kalimdor","Apporter l’Oeil de C’Thun à Anachronos dans les grottes du Temps."},
[8945]={"La supplique du mort","Entrez à Stratholme et sauvez Ysida Harmon du baron Vaillefendre."},
[8946]={"Une preuve de vie","Remettre le Médaillon d’Ysida à Anthion Harmon, dans les Maleterres de l’est."},
[8948]={"Le vieil ami d'Anthion","Apportez la Bannière de défi incomplète à Farlin Sculpteflore, dans la bibliothèque de Hache-Tripes."},
[8949]={"La vendetta de Falrin","Collecter 25 Perles de guerre ogres à l’intérieur de Hache-Tripes ou du Pic Rochenoire, puis revenir voir Falrin Sculpteflore, à l'intérieur de l'Athenaeum à Hache-Tripes."},
[8950]={"L'enchantement du provocateur","Apportez les choses suivantes à Falrin Sculpteflore dans Hache-Tripes : 1 Essence de spectre railleur, 4 Runes ténébreuses et 8 Grands éclats brillants."},
[8961]={"Les trois rois des flammes","Récupérez l’Incendicite d’Incendius, la Braise du prophète ardent sur le pyrogarde Prophète ardent et les Cendres de Cendres, ainsi qu'un Brasero béni, puis retournez voir Bodley au mont Rochenoire."},
[8966]={"Le morceau gauche de l'amulette du seigneur Valthalak","Utilisez le Brasero de signal pour invoquer l’esprit de Mor Sabot-gris, puis tuez-le. Ensuite, retournez voir Bodley à l'intérieur du mont Rochenoire avec le Morceau gauche de l'amulette du seigneur Valthalak et le Brasero de signal."},
[8967]={"Le morceau gauche de l'amulette du seigneur Valthalak","Utilisez le Brasero de signal pour invoquer l’esprit d’Isalien, puis tuez-le. Retournez voir Bodley, à l'intérieur du mont Rochenoire, avec le Morceau gauche de l’amulette du seigneur Valthalak et le Brasero de signal."},
[8968]={"Le morceau gauche de l'amulette du seigneur Valthalak","Utilisez le Brasero de signal pour invoquer Jarien et Sothos et les tuer. Retournez voir Bodley, à l'intérieur du mont Rochenoire, avec le Morceau gauche de l’amulette du seigneur Valthalak et le Brasero de signal."},
[8969]={"Le morceau gauche de l'amulette du seigneur Valthalak","Utilisez le Brasero de signal pour invoquer l’esprit de Kormok, puis tuez-le. Retournez voir Bodley, à l'intérieur du mont Rochenoire, avec le Morceau gauche de l'amulette du seigneur Valthalak et le Brasero de signal."},
[8989]={"Le morceau droit de l'amulette du seigneur Valthalak","Utilisez le Brasero de signal pour invoquer l’esprit de Mor Sabot-gris, puis tuez-le. Ensuite, retournez voir Bodley, à l'intérieur du mont Rochenoire, avec l’Amulette du seigneur Valthalak reconstituée et le Brasero de signal."},
[8990]={"Le morceau droit de l'amulette du seigneur Valthalak","Utilisez le Brasero de signal pour invoquer l’esprit d’Isalien, puis tuez-le. Retournez voir Bodley, à l'intérieur du mont Rochenoire, avec l’Amulette du seigneur Valthalak reconstituée et le Brasero de signal."},
[8991]={"Le morceau droit de l'amulette du seigneur Valthalak","Utilisez le Brasero de signal pour invoquer Jarien et Sothos, puis tuez-les. Retournez voir Bodley, à l'intérieur du mont Blackrock, avec l’Amulette du seigneur Valthalak reconstituée et le Brasero de signal."},
[8992]={"Le morceau droit de l'amulette du seigneur Valthalak","Utilisez le Brasero de signal pour invoquer l’esprit de Kormok, puis tuez-le. Retournez voir Bodley, à l'intérieur du mont Rochenoire, avec l’Amulette du seigneur Valthalak reconstituée et le Brasero de signal."},
[8994]={"Derniers préparatifs","Collectez 40 Brassards rochenoire et un Flacon de pouvoir suprême. Ensuite, retournez voir Bodley au mont Rochenoire."},
[8995]={"Mea culpa, seigneur Valthalak","Utilisez le Brasero de signal pour invoquer le seigneur Valthalak. Tuez-le, puis utilisez l’Amulette du seigneur Valthalak sur le corps. Ensuite, rendez l’amulette à l’Esprit du seigneur Valthalak."},
[9015]={"Le défi","Rendez-vous dans le Cercle de la loi, dans les profondeurs de Rochenoire, et placez la Bannière de provocation en son centre lorsque vous serez <condamné/condamnée> par le Juge supérieur Mornepierre. Tuez Theldren et ses gladiateurs, puis retournez voir Anthion Harmon dans les Maleterres de l’Est avec le premier morceau de l’amulette du seigneur Valthalak."},
[9023]={"Le poison parfait","Dirk Thunderwood, du Fort cénarien en Silithus, veut que vous lui rameniez la Glande à venin de Venoxis et la Glande à venin de Kurinaxx."},
[9033]={"Les échos de la guerre","Le commandant Eligor Portelaube, de la chapelle de l’Espoir de Lumière dans les Maleterres de l'Est, veut que vous tuiez 5 Monstruosités vivantes, 5 Gargouilles peau de pierre, 8 Capitaines des chevaliers de la mort et 3 Traque-venin."},
[9034]={"Cuirasse de cuirassier","Korfax, à la chapelle de l’Espoir de Lumière dans les Maleterres de l’Est, vous fabriquera une cuirasse de cuirassier si vous lui apportez les choses suivantes : 1 Cuirasse désacralisée, 25 Débris d’armure en plaques, 4 Barres d’arcanite et 2 Cristaux de nexus."},
