[8201]={"Una colección de cabezas","Ata 5 cabezas de los canalizadores y regresa con ellas a Exzhal en la isla Yojamba."},
[8227]={"Cinta métrica de Nat","Devuelve la Cinta métrica de Nat a Nat Pagle en el Marjal Revolcafango."},
[8231]={"Los vándalos marinos","Llévale 6 escamas de descarnador marino a Ogtinc en Azshara. Ogtinc vive en lo alto del precipicio al noreste de las Ruinas de Eldarath."},
[8232]={"El draco verde","Llévale el colmillo de Morphaz a Ogtinc en Azshara. Ogtinc vive en lo alto del precipicio al noreste de las Ruinas de Eldarath."},
