[8234]={"Bolsa azur sellada","Recupera la bolsa azur sellada del chamán Fauces de Madera en Azshara. Llévale entonces la bolsa al archimago Xylem, que también se encuentra en Azshara."},
[8235]={"Los fragmentos codificados","Llévale 10 fragmentos codificados al archimago Xylem en Azshara."},
[8236]={"La llave azur","Devuélvele la llave azur a Lord Jorach Ravenholdt."},
