[8246]={"Las sortijas de Zandalar"},
[8250]={"Pura magia","Busca a Sanath Lim-yo y obtén permiso para ver al archimago Xylem."},
[8251]={"El polvo mágico","Llévale 10 puñados de polvo relumbrante al archimago Xylem."},
[8252]={"El coral de las sirenas","Reúne 6 corales encantados y llévaselos al archimago Xylem."},
[8253]={"Destruye a Morphaz","Recupera el fragmento arcano de Morphaz y llévaselo al archimago Xylem."},
[8254]={"Ayuda a Cenarion","Busca a Ogtinc en Azshara."},
[8255]={"Los trotadores Pezuñamusgo","Consigue 4 glándulas de trotadores sanos y llévaselas a Ogtinc en Azshara. Ogtinc vive en lo alto del precipicio al noreste de las Ruinas de Eldarath."},
[8256]={"El icor de los no-muertos","Consigue un icor de los no-muertos para Ogtinc en Azshara. Ogtinc vive en lo alto del precipicio al noreste de las Ruinas de Eldarath."},
[8257]={"La sangre de Morphaz","Mata a Morphaz en El Templo Sumergido de Atal'Hakkar y lleva su sangre a Greta Pezuñamusgo en Frondavil. Encontrarás la entrada al Templo Sumergido en el Pantano de las Penas."},
[8258]={"La amenaza de Atracoscuro","Usa el cristal de adivinación en el corazón del sótano de El Gran Osario en Scholomance. Al hacerlo se presentarán los espíritus a los que tienes que enfrentarte. La derrota de estos espíritus invoca al caballero de la Muerte Atracoscuro, derrótalo. Llévale la cabeza de Atracoscuro a Sagorne Zanca Cresta en el Valle de la Sabiduría, en Orgrimmar."},
[8286]={"Lo que nos depara el futuro","Ve a las Cavernas del Tiempo en Tanaris y encuentra a Anacronos, del Linaje de Nozdormu."},
[8288]={"Solo uno puede alzarse","Lleva la cabeza del Señor de linaje Capazote a Baristolth del Mar de Dunas al Fuerte Cenarion en Silithus."},
[8301]={"El buen camino","Lleva 200 fragmentos de caparazón de silítido a Baristolth."},
[8302]={"Una buena mano","Lleva 200 fragmentos de caparazón de silítido a Baristolth."},
[8303]={"Anacronos","Busca a Anacronos en las Cavernas del Tiempo de Tanaris."},
[8305]={"Recuerdos olvidados","Encuentra la lágrima cristalina en Silithus y mira en sus profundidades."},
[8412]={"ótem de espíritu","Lleva lo necesario para el tótem del espíritu a Bath'rah el Vigía del viento."},
[8413]={"Vudú","Lleva las plumas vudú a Bath'rah el Vigía del viento."},
[8414]={"Expulsión de los demonios","Recoge 20 piedras de la Plaga del esbirro y entrégaselas al sumo sacerdote Thel'danis en las Tierras de la Peste del Oeste."},
[8416]={"Piedras inertes de la Plaga","Lleva la Piedra inerte de la Plaga al comandante Ashlam Puñovalor en el Alto del Orvallo."},
[8417]={"Un espíritu afligido","Habla con el Héroe Caído de la Horda en la entrada de Las Tierras Devastadas."},
[8418]={"La forja de la piedra de poderío","Obtén plumas vudú ámbar, azules y verdes de los trols del Templo Sumergido."},
[8419]={"Pedido de un diablillo","Lleva una pieza de tela de inferi a Diblis en Frondavil."},
[8420]={"Caliente y picante","Lleva un retal de tela de inferi a Diblis a Frondavil."},
[8421]={"La mercancía equivocada","Lleva 10 maderas putrefactas y 4 esencias de veneno a Diblis a Frondavil."},
[8422]={"Plumas de trol","Reúne un total de 6 plumas vudú en el Templo Sumergido."},
[8423]={"Parentesco guerrero","Mata a 7 jabinfernos de Las Tierras Devastadas y vuelve junto al héroe caído de la Horda."},
[8424]={"La guerra contra los Sombra Jurada","Acaba con los Sombra Jurada en las Tierras Devastadas y regresa junto al Héroe Caído de la Horda."},
[8425]={"Plumas Vudú","Llévale las plumas vudú de los trols del Templo Sumergido al Héroe Caído de la Horda."},
[8519]={"Un peón en el ajedrez de la vida","Aprende todo lo que puedas del pasado y habla con Anacronos en las Cavernas del Tiempo de Tanaris.|n"},
[8544]={"Las hombreras de conquistador","Llévale las ataduras de mando qiraji, 2 ídolos de la noche, 5 escarabajos de piedra y 5 escarabajos de terracota a Andorgos en Ahn'Qiraj. También debes alcanzar la reputación neutral ante el Linaje de Nozdormu para completar esta misión."},
[8555]={"Encomienda a los Vuelos"},
[8556]={"El anillo con sello de fuerza implacable","Llévale 1 anillo de magistrado qiraji, 2 ídolos luminiscentes, 5 escarabajos de bronce y 5 escarabajos de marfil a Clamavientos Yessendra en Silithus. También debes alcanzar la reputación de honrado ante el Círculo Cenarion para completar esta misión."},
