[8784]={"Los secretos de los qiraji","Llévale el artefacto antiguo qiraji a los dragones ocultos cerca de la entrada del templo.|n"},
[8789]={"Armamentos imperiales qiraji","Arygos en el Templo de Ahn'Qiraj creará armamento imbuido de elementium para ti si le llevas armamento imperial qiraji y 3 menas de elementium."},
[8790]={"Regalos imperiales Qiraji","Merithra del Sueño en el Templo de Ahn'Qiraj creará armamento imbuido de Elementium para ti si le llevas regalos imperiales qiraji y 3 minerales de Elementium."},
[8791]={"La caída de Osirio","Entrégale la cabeza de Osirio el Sinmarcas al comandante Mar'alith de Fuerte Cenarion en Silithus.|n"},
[8801]={"El legado de C'Thun","Llévale el ojo de C'Thun a Caelastrasz en el Templo de Ahn'Qiraj."},
[8802]={"La salvación de Kalimdor","Llévale el ojo de C'Thun a Anacronos en las Cavernas del Tiempo."},
[8945]={"La súplica de un muerto","Ve a Stratholme y rescata a Ysida Harmon del Barón Osahendido."},
[8946]={"Prueba de vida","Lleva el Guardapelo de Ysida a Anthion Harmon a las Tierras de la Peste del Este."},
[8948]={"Un viejo amigo de Anthion","Lleva el estandarte de la Provocación incompleto a Falrin Tallarbol que está en la biblioteca de La Masacre."},
[8949]={"La vendetta de Falrin","Reúne 25 abalorios de guerra de ogro de los ogros de La Masacre o de la Cumbre de Roca Negra y vuelve a El Athenaeum de La Masacre a hablar con Falrin Tallarbol."},
[8950]={"El encantamiento del provocador","Lleva a Falrin Tallarbol a La Masacre, lo siguiente: 1 Jeering Spectre's Essence, 4 Dark Runes y 8 grandes fragmentos brillantes."},
[8961]={"Tres reyes de Fuego","Recolecta la incendicita de Incendius, el ascua del Brasadivino y el rescoldo de las brasas junto con el blandón sagrado y llévaselos a Bodley en el interior de la Montaña Roca Negra."},
[8966]={"La parte izquierda del amuleto de Lord Valthalak","Usa el Blandón de Señalización para invocar al espíritu de Mor Ruciapezuña y mátalo. Vuelve junto a Bodley en el interior de la Montaña Roca Negra con la parte izquierda del amuleto de Lord Valthalak y el Blandón de Señalización."},
[8967]={"La parte izquierda del amuleto de Lord Valthalak","Usa el Blandón de Señalización para invocar al espíritu de Isalien y mátala. Vuelve junto a Bodley en el interior de la Montaña Roca Negra con la parte izquierda del amuleto de Lord Valthalak y el Blandón de Señalización."},
[8968]={"La parte izquierda del amuleto de Lord Valthalak","Usa el Blandón de Señalización para invocar al espíritu de Jarien y Sothos y mátalos. Vuelve junto a Bodley en el interior de la Montaña Roca Negra con la parte izquierda del amuleto de Lord Valthalak y el Blandón de Señalización."},
[8969]={"La parte izquierda del amuleto de Lord Valthalak","Usa el Blandón de Señalización para invocar al espíritu de Kormok y mátalo. Vuelve junto a Bodley en el interior de la Montaña Roca Negra con la parte izquierda del amuleto de Lord Valthalak y el Blandón de Señalización."},
[8989]={"La parte derecha del amuleto de Lord Valthalak","Usa el Blandón de Señalización para invocar al espíritu de Mor Ruciapezuña y mátalo. Vuelve junto a Bodley en el interior de la Montaña Roca Negra con el amuleto de Lord Valthalak recompuesto y el Blandón de Señalización."},
[8990]={"La parte derecha del amuleto de Lord Valthalak","Usa el Blandón de Señalización para invocar al espíritu de Isalien y mátala. Vuelve junto a Bodley en el interior de la Montaña Roca Negra con el amuleto de Lord Valthalak recompuesto y el Blandón de Señalización."},
[8991]={"La parte derecha del amuleto de Lord Valthalak","Usa el Blandón de Señalización para invocar al espíritu de Jarien y Sothos y mátalos. Vuelve junto a Bodley en el interior de la Montaña Roca Negra con el amuleto de Lord Valthalak recompuesto y el Blandón de Señalización."},
[8992]={"La parte derecha del amuleto de Lord Valthalak","Usa el Blandón de Señalización para invocar al espíritu de Kormok y mátalo. Vuelve junto a Bodley en el interior de la Montaña Roca Negra con el amuleto de Lord Valthalak recompuesto y el Blandón de Señalización."},
[8994]={"Últimos preparativos","Reúne 40 brazales Roca Negra y consigue un frasco de poder supremo. Llévaselos a Bodley en el interior de la Montaña Roca Negra."},
[8995]={"Mea Culpa, Lord Valthalak","Usa el Blandón de Invocación para invocar a Lord Valthalak. Despáchalo y usa el amuleto de Lord Valthalak sobre el cadáver. Después devuélvele el amuleto de Lord Valthalak al espíritu de Lord Valthalak."},
[9015]={"El reto","Dirígete al Círculo de la Ley en las Profundidades de Roca Negra y coloca el estandarte de Provocación en el centro cuando el Alto justiciero Pedrasiniestra pronuncie tu veredicto. Mata a Theldren y a sus gladiadores y regresa junto a Anthion Harmon en las Tierras de la Peste del Este con la primera pieza del amuleto de Lord Valthalak."},
[9023]={"El veneno perfecto","Dirk Thunderwood quiere que le lleves glándulas de veneno de Venoxis y Kurinnaxx al Fuerte Cenarion."},
[9033]={"Ecos de Guerra","El comandante Eligor Albar de la Capilla de la Esperanza de la Luz, en las Tierras de la Peste del Este, quiere que mates 5 monstruosidades vivientes, 5 gárgolas piel de piedra, 8 capitanes caballero de la Muerte y 3 acechadores venenosos."},
[9034]={"La coraza acorator","Korfax de la Capilla de la Esperanza de la Luz, en las Tierras de la Peste del Este, te hará una coraza acorator si le llevas lo siguiente: 1 coraza profanada, 25 restos de coraza, 4 barras de arcanita y 2 cristales nexo.|n"},
