[3802]={"Legado dos Ferro Negro","Mate Fineous Forçanegra e recupere o grande martelo Ferrovil. Leve-o para o Santuário de Thaurissan e coloque-o na estátua de Franclorn Forjífice."},
[3906]={"Desarmonia das chamas","Vá até a pedreira da Montanha Rocha Negra e mate o Mestre Supremo Piro. Fale novamente com Coração Trovejante quando tiver cumprido essa tarefa."},
[3907]={"Desarmonia do fogo","Entre no Abismo Rocha Negra e encontre o Lorde Incendius. Mate-o e leve todas as informações que puder para o Coração Trovejante."},
[3981]={"Comandante Gor'shak","Encontre o Comandante Gor'shak no Abismo Rocha Negra. Você se lembra que o tosco desenho incluía barras rabiscadas sobre o orc. Talvez você devesse procurar algum tipo de prisão."},
[3982]={"O que está acontecendo?","Defenda Gor'shak."},
[4001]={"O que está acontecendo?","Fale com Kharan Feromalho para obter informações sobre o sequestro da Princesa Moira Barbabronze. Leve as informações para Thrall em Orgrimmar. Gor'shak mencionou que Kharan estava preso em uma cela próxima."},
[4002]={"Os Reinos do Leste","Fale com Thrall se estiver <preparado/preparada> para assumir a missão que ele planejou."},
[4003]={"O resgate real","Mate o Imperador Dagran Thaurissan e liberte a Princesa Moira Barbabronze do feitiço maligno."},
[4022]={"O gosto das chamas","Mostre a Ciro Terepento a Muda de Pele da Revoada Negra que você recebeu de Kalaran Finalâmina."},
[4024]={"O gosto das chamas","Vá para o Abismo Rocha Negra e mate Bael'gar. A única coisa que você sabe é que o gigante mora no Abismo Rocha Negra. Lembre-se de usar a Muda de Pele Alterada da Revoada Negra nos restos mortais de Bael'gar para capturar a Essência Abrasadora. Leve a Essência Abrasadora Aprisionada para Ciro Terepento."},
[4061]={"O levante das máquinas","Vá para as Estepes Ardentes e recupere 10 Estilhaços Elementais Fraturados para a Hierofante Theodora Malvadania. Você se lembra que Theodora mencionou que os golens e elementais dessa região são uma fonte desses estilhaços."},
[4062]={"O levante das máquinas","Leve a Amostra de Estilhaço Elemental para Lotwil Viriato. Segundo Theodora, Lotwil estava escalado em um acampamento ao leste."},
[4063]={"O levante das máquinas","Encontre e mate Lorde Golem Argelmach. Leve a cabeça dele para Lotwil. Você também precisará coletar 10 Núcleos de Elemental Intactos dos Golens Rasgafúria e Constructos Armipotentes que protegem Argelmach. Você sabe disso porque é paranormal."},
[4081]={"SE VIR, MATE: Anões Ferro Negro","Desbrave o Abismo Rocha Negra e destrua aqueles invasores degenerados! O Senhor da Guerra Trincador quer que você mate 15 Guardas Furiadastra, 10 Carcereiros Furiadastra e 5 Soldados Rasos Furiadastra. Fale novamente com ele quando o trabalho estiver terminado."},
[4082]={"SE VIR, MATE: Oficiais Ferro Negro de Alta Patente","Vá até o Abismo Rocha Negra e destrua aqueles invasores degenerados! O Senhor da Guerra Trincador quer que você mate 10 Socorristas Furiadastra, 10 Soldados Furiadastra e 10 Oficiais Furiadastra. Fale novamente com ele quando o trabalho for concluído."},
[4083]={"Cálice Espectral"},
[4121]={"Situação precária","Escolte seu prisioneiro, Grark Lorkrub, pelas Estepes Ardentes, atravessando a Montanha Rocha Negra até chegar à Garganta Abrasadora. Você se lembra de ter ouvido Lexlort dizer que mandaria seus homens esperar no outro lado para levar Grark sob custódia. Você também vai precisar entregar os Grilhões de Tório para Lexlort."},
[4122]={"Grark Lorkrub","Vá para as Estepes Ardentes e encontre Grark Lorkrub. Segundo Lexlort, ele foi visto pela última vez em uma imensa fortaleza Rocha Negra. Quando encontrar Grark Lorkrub, use os Grilhões de Tório para prendê-lo e levá-lo de volta à Garganta Abrasadora, passando pela Montanha Rocha Negra. Os homens de Lexlort estarão esperando do outro lado para levar Grark sob sua custódia."},
[4123]={"O Coração da Montanha","Leve o Coração da Montanha para Maxwort Uberraio nas Estepes Ardentes."},
[4126]={"Hurley Bafonegro","Leve a Receita Perdida de Cervaforte para Ragnar Cervaforte em Kharanos."},
[4132]={"Operação: Morte ao Forjaversa","Viaje para o Abismo Rocha Negra e mate o General Forjaversa! Fale novamente com o Senhor da Guerra Trincador quando a tarefa estiver concluída."},
[4134]={"Receita Perdida de Cervaforte","Leve a Receita Perdida de Cervaforte para Vivian Latumba em Karrath."},
[4136]={"Ribas Parafuseta","Leve a Cabeça do Ribas para Yuka Parafuseta nas Estepes Ardentes."},
[4141]={"Melco e Lário","Colha 15 Pétalas Sangrentas e fale novamente com Melco."},
[4142]={"Uma visita a Gregan","Leve uma Pétala Sangrenta para Gregan Cospechope em Feralas."},
[4143]={"Brumas do mal","Colha 5 amostras de Bruma de Atal'ai, depois fale novamente com Melco na Cratera Un'Goro."},
[4145]={"Lário e Melco","Cace 5 Açoitadeiras Pétala Sangrenta, 5 Látegas Pétala Sangrenta, 5 Esfoladoras Pétala Sangrenta e 5 Laçadoras Pétala Sangrenta para Lário, do Refúgio do Marshal."},
[4146]={"Combustível de fulminadora","Entregue a Fulminadora Descarregada e 5 amostras de Bruma de Atal'ai a Lário, no Refúgio do Marshal."},
[4147]={"Oficina do Marlon","Vá até a oficina de Marlon Catarrebite na Vila Catraca."},
[4182]={"Ameaça draconiana","Mate 15 Filhotes Negros, 10 Dragomorfos Negros, 4 Draconoides Negros e 1 Draco Negro. Fale novamente com Helendis Flumicórnio quando a tarefa estiver concluída."},
[4183]={"Os verdadeiros mestres","Viaje até Vila Plácida e entregue a Carta de Helendis Flumicórnio ao Magistrado Salomão."},
[4184]={"Os verdadeiros mestres","Viaje para Ventobravo e entregue o Apelo de Salomão ao Grão-lorde Bolvar Fordragon. Bolvar reside na Bastilha Ventobravo."},
[4185]={"Os verdadeiros mestres","Fale com o Grão-lorde Bolvar Fordragon depois de falar com a Lady Katrana Prestor."},
[4186]={"Os verdadeiros mestres","Leve o Decreto de Bolvar para o Magistrado Salomão, em Vila Plácida."},
[4201]={"A poção do amor","Leve 4 Sangues-de-grom, 10 Veios de Prata Gigantes e a Ampola da Nagmara Cheia para a Lady Nagmara no Abismo Rocha Negra."},
[4223]={"Os verdadeiros mestres","Fale com o Oficial Maxwell nas Estepes Ardentes."},
[4224]={"Os verdadeiros mestres","Fale com João Roto para saber o destino do Marechal Vilasboas e fale novamente com o Oficial Maxwell quando tiver completado essa tarefa. Você se lembra do Oficial Maxwell lhe dizendo para procurá-lo em uma caverna ao norte."},
[4241]={"Marechal Vilasboas","Viaje para a Montanha Rocha Negra, a noroeste, e entre no Abismo Rocha Negra. Descubra o que aconteceu com o Marechal Vilasboas. Você se lembra de João Roto falando sobre Vilasboas ter sido arrastado para uma prisão."},
[4242]={"Esperança abandonada","Leve as más notícias ao Oficial Maxwell."},
[4262]={"Mestre Supremo Piro","Mate o Mestre Supremo Piro e fale novamente com Jalinda Ramo. Você se lembra de Jalinda ter dito que Piro guarda a pedreira. Que tal procurar por lá?"},
[4263]={"Incendius!","Encontre Lorde Incendius no Abismo Rocha Negra e destrua-o!"},
[4264]={"Bilhete amassado","Você pode ter acabado de descobrir algo que o Marechal Vilasboas estaria interessado em ver. Pode haver esperança, afinal."},
[4282]={"Um fiapo de esperança","Recupere as Informações Perdidas do Marechal Vilasboas. O Marechal Vilasboas acredita que as informações estão sendo mantidas pelo Lorde Golem Argelmach e pelo General Forjaversa."},
[4286]={"Produto de primeira","Viaje para o Abismo Rocha Negra e recupere 20 Pochetes Ferro Negro. Fale novamente com Oralius quando tiver completado a tarefa. Você supõe que os anões Ferro Negro de dentro do Abismo Rocha Negra carregam essa tal de \"pochete\"."},
[4322]={"Fuga da prisão!","Ajude o Marechal Vilasboas a recuperar seu equipamento e libertar seus amigos. Se conseguir, fale novamente com o Oficial Maxwell."},
[4341]={"Kharan Feromalho","Viaje para Abismo Rocha Negra e encontre Kharan Feromalho. O Rei mencionou que Kharan estava preso lá — talvez seja bom procurar uma prisão."},
[4342]={"O conto de Kharan","Ouça Kharan Feromalho contar a história dele."},
[4361]={"Informante das más notícias","Volte a Altaforja e dê as más notícias ao Rei Magni Barbabronze."},
[4362]={"O destino do reino","Volte ao Abismo Rocha Negra e resgate a Princesa Moira Barbabronze das garras malignas do Imperador Dagran Thaurissan."},
[4701]={"Acabando com ela","Vá ao Pico da Rocha Negra e destrua a fonte da ameaça worg. Quando você deixou Helendis, ele gritou um nome: Halycon. É assim que os orcs se referem aos worgs."},
[4724]={"Senhora do matilha","Mate Halycon, senhora da matilha dos Worgs Machado Sangrento."},
[4726]={"Essência da Reprodução","Leve 8 Essências da Reprodução e o Draco-incarcinatrix 900 a Vera Brequim no Monte Candente, que fica nas Estepes Ardentes."},
[4729]={"Mascotes exóticas do Kibler","Vá para o Pico da Rocha Negra e encontre Filhotes de Worg Machado Sangrento. Use a jaula para carregar essas pequenas feras. Leve um Filhote de Worg Enjaulado para Kibler."},
[4734]={"Congelar os ovos","Use o Protótipo de Ovosciloscópio em um ovo no Viveiro."},
[4735]={"Coleção de ovos","Leve 8 Ovos de Dragão Recolhidos e o Módulo Colectrônico a Vera Brequim no Monte Candente, que fica nas Estepes Ardentes."},
[4742]={"Selo da Ascensão","Encontre as três gemas da autoridade: a Gema de Espinho Fúmeo, a Gema de Agulhapétrea e a Gema de Machado Sangrento. Entregue-as, junto com o Selo da Ascensão sem Adorno, a Vaelan. Os generais, como informado a você por Vaelan, são: Senhor da Guerra Voone dos Fumocardo, Grão-lorde Omokk dos Agulhapétrea e Lorde Supremo Wyrmthalak dos Machado Sangrento."},
[4764]={"Broche do Finitudo","Leve o Broche do Finitudo para Mayara Asaluz nas Estepes Ardentes."},
[4768]={"A tabuleta de Pedranegra","Leve a Tabuleta de Pedranegra à Umbramante Vivian Latumba, em Karrath."},
[4771]={"Aposta da Aurora","Coloque a Aposta da Aurora na Sala de Exibição de Scolomântia. Derrote Vectus, depois fale novamente com Betina Bigozinco."},
[4787]={"O ovo velho","Leve o Ovo Velho para Yeh'kinya, em Tanaris."},
[4788]={"As últimas tabuletas","Leve a Quinta e a Sexta Tabuletas Mosh'Aru ao Prospector Botaférrea, em Tanaris."},
[4808]={"Felnok Molaço","Leve a Carta de Vera para Felnok Molaço."},
[4809]={"Chifres de ventogelante","Leve 8 Chifres Inteiriços de Quimera Ventogelante para Felnok Molaço."},
[4810]={"Fale novamente com Vera","Leve o Pacote do Felnok para Vera Brequim, nas Estepes Ardentes."},
[4862]={"Nojento!","Vá para o Pico da Rocha Negra e colete 15 Ovos de Aranha do Pináculo para Kibler. Pelo nome, é de se pensar que eles fiquem perto das aranhas."},
[4866]={"Leite materno","No coração do Pico da Rocha Negra você vai encontrar a Mãe Queimateia. Chame a atenção dela e deixe-a envenenar você. É bem provável que você precise matá-la também. Fale novamente com João Roto depois que for envenenad<o/a> para que ele possa \"ordenhar\" você."},
[4867]={"Urok Uivo-da-ruína","Leia o Pergaminho do Warosh. Traga o Mojo do Warosh para Warosh."},
[4903]={"O comando do Senhor da Guerra","Mate o Grão-lorde Omokk, o Senhor da Guerra Voone e o Lorde Supremo Wyrmthalak. Recupere Documentos Importantes dos Rocha Negra. Fale novamente com o Senhor da Guerra Trincador, em Karrath, quanto a missão tiver sido cumprida."},
[4907]={"Vera Brequim","Fale com Vera Brequim."},
[4941]={"A sabedoria de Eitrigg","Fale com Eitrigg em Orgrimmar. Quando tiver discutido o assunto com Eitrigg, busque o conselho de Thrall. Você se lembra de ter visto Eitrigg nos aposentos de Thrall."},
[4974]={"Pela Horda!","Viaje para o Pico da Rocha Negra e mate o Chefe Guerreiro Laceral Mão Negra. Pegue sua cabeça e volte para Orgrimmar."},
[4981]={"Agente Biju","Vá ao Pico da Rocha Negra e descubra o que aconteceu com Biju."},
[4982]={"Pertences da Biju","Encontre os Pertences de Biju e devolva-os a ela. Ela mencionou tê-los guardado no nível mais profundo da cidade."},
[4983]={"Relatório de reconhecimento de Biju","Leve o Relatório de Reconhecimento de Biju para o Grão-mestre Lexlort em Karrath."},
[5001]={"Pertences da Biju","Encontre os Pertences de Biju e devolva-os a ela. Boa sorte!"},
[5002]={"Mensagem para Maxwell","Viaje para as Estepes Ardentes e dê as Informações de Biju para o Oficial Maxwell."},
[5047]={"Lépido Fagueiro, ao seu dispor!","Fale com Málifus Trevamalho em Visteterna."},
[5065]={"As tabuletas Mosh'Aru perdidas","Leve a Terceira e a Quarta Tabuletas Mosh'Aru ao Prospector Botaférrea, em Tanaris."},
[5081]={"A missão de Maxwell","Vá para o Pico da Rocha Negra e mate o Senhor da Guerra Voone, o Grão-lorde Omokk e o Lorde Supremo Wyrmthalak. Fale novamente com o Oficial Maxwell quando terminar o trabalho."},
[5089]={"Comando do General Drakkisath","Leve o Comando do General Drakkisath para o Oficial Maxwell nas Estepes Ardentes."},
[5102]={"O fim do General Drakkisath","Viaje de volta ao Pico da Rocha Negra e destrua o General Drakkisath. Depois, fale novamente com o Oficial Maxwell."},
[5122]={"O Medalhão da Fé"},
[5125]={"O ajuste de contas de Aurius"},
[5127]={"A forja demoníaca","Viaje para o Pico da Rocha Negra e encontre Goraluk Rachadastra. Mate-o e use o Pique Manchado de Sangue no cadáver dele. Quando a alma dele tiver sido canalizada, o pique ficará Manchado de Almas. Você também precisa encontrar o Peitoral Rúnico de Metal Bruto. Leve o Pique Manchado de Almas e o Peitoral Rúnico de Metal Bruto para Vegax, em Hibérnia."},
[5160]={"A protetorada-máter","Viaje para Hibérnia e encontre Haleh. Entregue para ela a Escama do Albi."},
[5212]={"A carne não mente","Recupere 20 Amostras de Carne Infectada de Stratholme e leve-as para Betina Bigozinco. Você desconfia que qualquer criatura em Stratholme poderia ter essa amostra de carne."},
[5213]={"O agente ativo","Vá para Stratholme e vasculhe os zigurates. Encontre novos Dados do Flagelo e leve-os para Betina Bigozinco."},
[5214]={"O grande Ezra Carranca","Encontre a tabacaria de Ezra Carranca em Stratholme e recolha uma caixa do Tabaco da Lata do Carranca. Fale novamente com Leandro Leonardo depois que tiver terminado o serviço."},
[5243]={"Casas do sagrado","Viaje para Stratholme, ao norte. Procure os caixotes de suprimentos que cobrem a cidade e recupere 5 Águas Bentas de Stratholme. Fale novamente com Leonid Bartolomeu, o Venerado, quando coletar fluido abençoado suficiente."},
[5244]={"Ruínas de Kel'Theril","Fale com Jaron Moldapedra na Aldeia Chuva Estelar."},
[5245]={"Espíritos atormentados de Kel'Theril","Use a Picareta do Jaron para encontrar os quatro Fragmentos da Relíquia dos Altaneiros. Leve-os para Aurora Clamacéus nas Terras Pestilentas Orientais."},
[5246]={"Fragmentos do passado","Encontre os Escritos Sagrados dos Altaneiros no Templo de Zin-Malor, em Azshara, e leve-os para Aurora Clamacéus, perto da Torre do Passo Norte nas Terras Pestilentas Orientais."},
[5247]={"Fragmentos do passado","Leve uma Barra de Tório Encantado, 5 Restaurações de Cristal e uma Ampola de Água Hedionda para Aurora Clamacéus perto da Torre do Passo Norte nas Terras Pestilentas Orientais."},
[5251]={"O arquivista","Viaje até Stratholme e encontre o Arquivista Galford da Cruzada Escarlate. Destrua-o e queime o Arquivo Escarlate."},
[5262]={"A verdade desaba sobre todos","Leve a Cabeça do Balnazzar para o Duque Nicolau Zverenhoff nas Terras Pestilentas Orientais."},
[5263]={"Acima e além","Desbrave Stratholme e destrua o Barão Rivendare. Corte sua cabeça e leve-a de volta para o Duque Nicolau Zverenhoff."},
[5281]={"As almas inquietas","Encontre Egan. Ele foi visto pela última vez nos arredores de Stratholme."},
[5282]={"As almas inquietas","Use o Canhão de Ectoplasma do Egan nos moradores fantasmagóricos e espectrais de Stratholme. Depois de livrá-los da forma de fantasma, use o canhão de novo e BLAU: liberdade! Liberte 15 Almas Inquietas, depois fale novamente com Egan."},
[5341]={"A fortuna da família Barov","Desbrave Scolomântia e recupere a fortuna da família Barov. A fortuna é composta por quatro escrituras: A Escritura de Castro das Flechas, A Escritura de Montalvo, A Escritura da Serraria Tarren e A Escritura de Costa Sul. Fale novamente com Alexei Barov quando tiver terminado a tarefa."},
[5343]={"A fortuna da família Barov","Desbrave Scolomântia e recupere a fortuna da família Barov. A fortuna é composta por quatro escrituras: A Escritura de Castro das Flechas, a Escritura de Montalvo, a Escritura da Serraria Tarren e a Escritura de Costa Sul. Fale novamente com Weldon Barov quando tiver terminado a tarefa."},
[5382]={"Doutor Theolen Krastinov, o Carniceiro","Encontre o Doutor Theolen Krastinov em Scolomântia. Destrua-o, depois queime os Restos Mortais de Eva Sarkhoff e os Restos Mortais de Lucien Sarkhoff. Fale novamente com Eva Sarkhoff depois que tiver terminado a tarefa."},
[5384]={"Kirtonos, o Arauto","Volte a Scolomântia com o Sangue dos Inocentes em mãos. Encontre a varanda e derrame o Sangue dos Inocentes no braseiro. Kirtonos virá na intenção de devorar sua alma. Lute com bravura, não dê nenhuma brecha! Destrua Kirtonos e fale novamente com Eva Sarkhoff."},
[5461]={"Ras Friomúrmuro, o humano","Viaje para o Planalto Arathi, até as ruínas de Stromgarde. Vasculhe Stromgarde em busca de um Livro de Recordações. Se encontrar o item, retorne com ele até o Magistrado Marduque."},
[5462]={"Ras Friomúrmuro, o moribundo","Viaje para a Capela Esperança da Luz, nas Terras Pestilentas Orientais, e procure por Leonid Bartolomeu, o Venerado. Mostre a ele o Livro de Recordações e conte tudo o que descobriu."},
[5463]={"Dádiva de Menethil","Vá até Stratholme e encontre a Dádiva de Menethil. Ponha o Livro de Recordações no solo profanado."},
[5464]={"Dádiva de Menethil","Leve a Lembrança Vinculada para Leonid Bartolomeu, nas Terras Pestilentas Orientais."},
[5465]={"Lembrança Vinculada","Fale novamente com o Magistrado Marduque, no Castro das Flechas. Mostre-lhe a Lembrança Vinculada."},
[5466]={"Ras Friomúrmuro, o lich","Procure por Ras Friomúrmuro em Scolomântia. Quando o encontrar, use a Lembrança Vinculada em sua versão morto-vivo. Quando conseguir transformá-lo novamente em mortal, mate-o e recupere a Cabeça Humana de Ras Friomúrmuro. Leve a cabeça de volta ao Magistrado Marduque."},
[5515]={"Saco de Horrores de Krastinov","Localize Janice Barov em Scolomântia e a destrua. Recupere o Saco de Horrores de Krastinov do cadáver dela. Entregue o saco a Eva Sarkhoff."},
[5522]={"Leonid Bartolomeu","Leve os Ovos Congelados para Leonid Bartolomeu, nas Terras Pestilentas Orientais."},
[5526]={"Pedaços de Vinhavil","Encontre a Vinhavil no Gládio Cruel e obtenha uma lasca dela. É bem provável que você só consiga encontrar uma depois da derrota de Azzin, o Selvamorfo. Use o Relicário da Pureza para selar a lasca com segurança e leve-a de volta para Ravine Saturna, no Refúgio Noturno, que fica na Clareira da Lua."},
[5527]={"Relicário da Pureza","Viaje até Silithus e procure um Relicário da Pureza dentro das ruínas da Vila do Vento Sul. Se conseguir encontrá-lo, regresse com ele até Ravine Saturna, no Refúgio Noturno, que fica na Clareira da Lua."},
[5529]={"Filhotes Pestilentos","Mate 20 Filhotes Pestilentos, depois fale novamente com Betina Bigozinco, na Capela Esperança da Luz."},
[5531]={"Betina Bigozinco","Leve os Ovos Congelados para Betina Bigozinco."},
[5533]={"Scolomântia","Fale com o Alquimista Arvignon no Morro do Ventogelante, que fica nas Terras Pestilentas Ocidentais."},
[5722]={"Em busca da algibeira perdida","Investigue as Cavernas Ígneas em busca do corpo de Mauren Temível Totem e procure quaisquer itens de interesse."},
[5723]={"Testando a força do inimigo","Procure as Cavernas Ígneas em Orgrimmar e mate 8 Troggs Iraflama e 8 Xamãs Iraflama, depois fale novamente com Rahauro no Penhasco do Trovão."},
[5724]={"Devolvendo a algibeira perdida","Leve a Algibeira do Temível Totem para Rahauro no Penhasco do Trovão."},
[5725]={"O poder de destruir...","Leve os livros \"Feitiços da Sombra\" e \"Encantamentos do Éter\" para Varimatras na Cidade Baixa."},
[5726]={"Inimigos ocultos","Leve uma Insígnia do Tenente para Thrall em Orgrimmar."},
[5727]={"Inimigos ocultos","Leve a Insígnia do Tenente para Neeru Cortafogo e fale com ele. Avalie se ele acredita que você é um membro da Lâmina Ardente e, depois, fale novamente com Thrall em Orgrimmar."},
[5728]={"Inimigos ocultos","Mate Bazzalan e Jergosh, o Invocador e fale novamente com Thrall em Orgrimmar."},
[5761]={"Mate a besta","Entre nas Cavernas Ígneas e mate Taragaman, o Famélico, depois leve o coração dele para Neeru Cortafogo em Orgrimmar."},
[5848]={"Do amor e da família","Viaje para Stratholme, na parte norte das Terras Pestilentas. No Bastião Escarlate, você encontrará a pintura \"Do Amor e da Família\", escondida atrás de outro quadro que retrata as luas gêmeas do nosso mundo. Leve a pintura de volta para Tirion Fordring."},
[6022]={"Matar com propósito","Vá ao Cruzamento de Corin, a leste, e mate membros do Flagelo que habitam a cidade. Colete 7 pedaços de Putrefação Viva em menos de 10 minutos. Use o Almofariz e Pilão para moer a Putrefação Viva, de maneira a transformá-la em Putrefação Coagulada."},
[6042]={"Pequenos transtornos da Morte-em-Vida","Mate 20 Quirópragos Nóxios e 10 Quirópragos Monstruosos. Fale novamente com Nathanos Arauto da Praga quando você tiver terminado."},
[6133]={"A mando do lorde patrulheiro","Vá à fronteira norte das Terras Pestilentas Orientais e recupere os Arquivos de Quel'Thalas em algum lugar do Abrigo Quel'Lithien. Você também precisa matar 8 Patrulheiros, 8 Trilheiros e 8 Mateiros."},
[6135]={"Ah, Quiroscuro, como vos odeio...","Encontre Quiroscuro e mate-o. Do cadáver, extraia um Tufo de Pele de Quiroscuro e leve para Nathanos Arauto da Praga. Dizem que Quiroscuro vaga pelo campo ao norte do Sítio dos Marris."},
[6136]={"O corpulento","Encontre Brocassangre nos ermos do norte das Terras Pestilentas e destrua-o. Fale novamente com Nathanos Arauto da Praga quando tiver cumprido a missão."},
[6163]={"Ramstein","Vá a Stratholme e mate Ramstein, o Devorador. Leve a cabeça dele como souvenir para Nathanos."},
[6402]={"Encontro marcado em Ventobravo","Viaje a Ventobravo e vá até os portões da cidade. Fale com o Escudeiro Rui para que ele avise ao Marechal Vilasboas que você chegou."},
[6403]={"O grande baile de máscaras","Siga Reginaldo Vilasboas através de Ventobravo. Proteja-o de qualquer ataque!"},
[6501]={"O Olho do Dragão","Você deve vasculhar o mundo em busca de uma criatura capaz de restaurar o poder do Fragmento do Olho do dragão. A única informação que você tem sobre essa criatura é que ela existe."},
[6502]={"Amuleto da Chama Dracônica","Confronte o General Drakkisath e consiga o Sangue do Campeão dos Dragões Negros. Drakkisath está na sala do trono atrás dos Salões da Ascensão, no Pico da Rocha Negra."},
[6521]={"Uma aliança profana","Leve a cabeça do Embaixador Malcin para Varimatras, na Cidade Baixa."},
[6522]={"Uma aliança profana","Leve o Pergaminho Pequeno para Varimatras, na Cidade Baixa."},
[6561]={"Vilania das Profundezas","Leve a cabeça do Senhor do Crepúsculo Kelris para Bashana Runa Totem, no Penhasco do Trovão."},
[6562]={"Problemas nas Profundezas","Fale com Je'neu Sancrea no Vale Gris."},
[6563]={"A essência de Aku'mai","Entregue 20 Safiras de Aku'Mai a Je'neu Sancrea no Vale Gris."},
[6564]={"Lealdade aos Deuses Antigos","Leve o Bilhete Úmido para Je'neu Sancrea, no Vale Gris."},
[6565]={"Lealdade aos Deuses Antigos","Mate Lorgus Jett nas Profundezas Negras e depois fale novamente com Je'neu Sancrea no Vale Gris."},
[6566]={"O que o vento carrega","Ouça Thrall."},
[6567]={"O campeão da Horda","Procure Rexxar. O Chefe Guerreiro <o/a> instruiu quanto ao paradeiro dele. Procure nos caminhos de Desolação, entre a Cordilheira das Torres de Pedra e Feralas."},
[6568]={"O testamento de Rexxar","Leve o Testamento de Rexxar para Myranda, a Bruxa Velha, nas Terras Pestilentas Ocidentais."},
[6569]={"Ilusões ópticas","Vá para o Pico da Rocha Negra e colete 20 Olhos de Dragomorfo Preto. Fale novamente com Myranda, a Bruxa Velha, depois que tiver terminado a tarefa."},
[6570]={"Ardeluta","Vá até o Pântano da Serpe, no Pântano Vadeoso, e procure o Covil de Ardeluta. Quando estiver lá, use o Amuleto de Subversão Dracônica e fale com Ardeluta."},
[6582]={"O teste dos crânios: Áugure","Encontre e mate o Áugure, o draco da Revoada Dragônica Azul. Arranque a cabeça do draco morto e leve-a para Ardeluta. Você sabe que o Áugure se encontra em Hibérnia."},
[6583]={"O teste dos crânios: Somnus","Destrua Somnus, o draco campeão da Revoada Verde. Pegue seu crânio e leve-o para Ardeluta."},
[6584]={"O teste dos crânios: Chronalis","Guardando as Cavernas do Tempo no Deserto de Tanaris, encontra-se Chronalis, filho de Nozdormu. Destrua-o e leve seu crânio para Ardeluta."},
[6585]={"O teste dos crânios: Axtroz","Vá para Grim Batol e encontre Axtroz, o draco campeão da Revoada Vermelha. Destrua-o e arranque sua cabeça. Leve o crânio para Ardeluta."},
[6601]={"Ascensão...","Pelo jeito, a farsa chegou ao fim. Você já sabe que o Amuleto de Subversão Dracônica criado por Myranda, a Bruxa Velha, não vai funcionar no Pico da Rocha Negra. Você devia ir atrás de Rexxar e explicar a situação. Mostre a ele o Amuleto da Chama Dracônica Fraco. Pode ser que ele saiba o que fazer."},
[6602]={"Sangue do Campeão dos Dragões Negros","Viaje para o Pico da Rocha Negra e mate o General Drakkisath. Recolha seu sangue e leve-o para Rexxar."},
[6626]={"A hoste do mal","Mate 8 Guerreiros do Urzal, 8 Tecespinhos do Urzal e 8 Sectários da Cabeça da Morte, depois fale novamente com Mírian Lunacanto perto da entrada do Urzal dos Mortos."},
[6627]={"Teste de saber","Responda à pergunta de Braug Espírito Turvo corretamente, depois fale com ele novamente. Quando você estiver pront<o/a>, ele estará na Cordilheira das Torres de Pedra."},
[6628]={"Teste de saber","Responda à pergunta de Pasqual Fintallas corretamente, depois fale com ele novamente. Quando você estiver pront<o/a>, ele estará na Cidade Baixa."},
[6642]={"Um favor para a irmandade: Minérios de Ferro Negro"},
[6643]={"Um favor para a irmandade: Núcleos de Fogo"},
[6644]={"Um favor para a irmandade: Núcleo de Lava"},
[6645]={"Um favor para a irmandade: Couro do Núcleo"},
[6646]={"Um favor para a irmandade: Sangue-da-montanha"},
[6804]={"Água contaminada","Use o Aspecto de Neptulon nos elementais contaminados das Terras Pestilentas Orientais. Leve 12 Braçadeiras Dissonantes e o Aspecto de Neptulon ao Duque Hidráxis em Azshara."},
[6805]={"Tempestades e estrondores","Mate 15 Tempestades de Poeira e 15 Estrondores do Deserto e fale novamente com o Duque Hidráxis em Azshara."},
[6821]={"O Olho do Mirabrasa","Leve o Olho do Mirabrasa ao Duque Hidráxis em Azshara."},
[6822]={"O Núcleo Derretido","Mate 1 Senhor do Fogo, 1 Gigante Derretido, 1 Cão-magma Antigo e 1 Irrompedor de Lava e depois fale novamente com o Duque Hidráxis em Azshara."},
[6823]={"Agente de Hidráxis","Alcance a reputação de <Honrado/Honrada> pelos Senhores das Águas Hidraxianos e depois fale com o Duque Hidráxis em Azshara."},
[6824]={"Mãos do inimigo","Leve as Mãos de Lúcifron, Sulfuron, Geena e Shazzrah ao Duque Hidráxis em Azshara."},
[6921]={"Nas ruínas","Leve o Núcleo das Profundezas para Je'neu Sancrea no Assentamento Zoram'gar, no Vale Gris."},
[6922]={"O Barão Aquanis","Leve o Globo d'Água Estranho para Je'neu Sancrea no Assentamento Zoram'gar, no Vale Gris."},
[6981]={"A lasca faiscante","Viaje para a Vila Catraca e procure alguém que possa contar mais alguma coisa sobre a lasca faiscante. Depois, entregue a lasca conforme as orientações."},
[7028]={"Raízes do mal","Colete 25 Entalhes de Cristal Terádrico para Faia, na Desolação."},
[7029]={"A corrupção de Torpelíngua","Encha a Ampola Cerúlea Tampada na poça de cristal laranja, em Maraudon. Use a Ampola Cerúlea Cheia nos Cipós Caule Torpe para forçar os Rebentos Tóxxicos corrompidos a emergir. Cure 8 plantas ao matar os Rebentos Tóxxicos, depois fale novamente com Vark Chaga de Guerra, na Aldeia Pescassombra."},
[7041]={"A corrupção de Torpelíngua","Encha a Ampola Cerúlea Tampada na poça de cristal laranja, em Maraudon. Use a Ampola Cerúlea Cheia nos Cipós Caule Torpe para forçar os Rebentos Tóxxicos corrompidos a emergir. Cure 8 plantas ao matar os Rebentos Tóxxicos, depois fale novamente com Talendria, no Posto do Nijel."},
[7044]={"Lendas de Maraudon","Recupere as duas partes do Cetro de Celebras: o Bastão de Celebras e o Diamante de Celebras. Encontre um jeito de falar com Celebras."},
[7046]={"O Cetro de Celebras","Ajude Celebras, o Redimido, a criar o Cetro de Celebras. Fale com ele quando o ritual estiver concluído."},
[7064]={"Corrupção da terra e dos grãos","Mate a Princesa Theradras e fale novamente com Selendra perto da Aldeia Pescassombra, na Desolação."},
[7065]={"Corrupção da terra e dos grãos","Mate a Princesa Theradras e fale novamente com o Guardião Marandis no Posto do Nijel, na Desolação."},
[7066]={"A semente da vida","Procure Remulos, na Clareira da Lua, e entregue a ele a Semente da Vida."},
[7067]={"As instruções do pária","Leia as Instruções do Pária. Depois, obtenha em Maraudon o Amuleto da União e devolva-o ao Centauro Pária, na parte sul de Desolação."},
[7068]={"Fragmentos de lascanegra","Colete 10 Fragmentos de Lascanegra em Maraudon e leve-os para Uthel'nay, em Orgrimmar."},
[7070]={"Fragmentos de lascanegra","Colete 10 Fragmentos de Lascanegra em Maraudon e leve-os para o Arquimago Tervosh, em Theramore, na costa do Pântano Vadeoso."},
[7201]={"O último elemento","Vá até o Abismo Rocha Negra e obtenha 10 Essências dos Elementos. Seu primeiro impulso é procurar nos golens e criadores de golens. Você lembra que Vivian Latumba também mencionou elementais."},
[7441]={"Pusillin e o Ancião Azj'Tordin","Vá ao Gládio Cruel e encontre o Diabrete Pusillin. Convença-o usando qualquer meio que for necessário a lhe dar o Livro de Encantamentos de Azj'Tordin. Fale novamente com Azj'Tordin no Pavilhão Lariss, em Feralas, caso você recupere o Livro de Encantamentos."},
[7461]={"A loucura intrínseca","Mate os guardiões que cercam os cinco pilares de força da Prisão de Immol'thar. Quando os pilares se desligarem, o campo de força que cerca Immol'thar se dissipará. Destrua o terrível demônio que fica no coração da Prisão de Immol'thar. Por fim, enfrente o Príncipe Tortheldrin, no Ateneu. Fale novamente com a Anciã Shen'dralar, no pátio, após cumprir a missão."},
[7462]={"O tesouro de Shen'dralar","Volte ao Ateneu e encontre o Tesouro dos Shen'dralar. Reclame sua recompensa!"},
[7463]={"Bebida arcana","Vá ao Distrito Lenhatorta, no Gládio Cruel, e mate o elemental da água, Rebentágua. Leve a Essência de Rebentágua para o Erudito Lydros, no Ateneu."},
[7481]={"Lendas élficas","Procure Telmius Romanesca no Gládio Cruel. Reporte-se, então, ao Sábio Korolusk na Aldeia Mojache com qualquer informação que você encontrar."},
[7482]={"Lendas élficas","Procure Telmius Romanesca no Gládio Cruel. Reporte-se, então, à Erudita Runacardos em Plumaluna com qualquer informação que você encontrar."},
[7486]={"Recompensa para um herói","Obtenha a recompensa na Arca de Hidráxis."},
[7488]={"A teia de Letendris","Leve a Teia de Letendris para Latrônicus Lunalança no Domínio de Plumaluna, em Feralas."},
[7489]={"A teia de Letendris","Leve a Teia de Letendris para Talo Casco de Espinhos na Aldeia Mojache, em Feralas."},
[7490]={"Vitória da Horda","Leve a Cabeça da Onyxia para Thrall em Orgrimmar."},
[7491]={"Para que todos vejam","Procure o Lorde Supremo Runthak no Vale da Força."},
[7493]={"A jornada está apenas começando"},
[7495]={"Vitória pela Aliança","Leve a Cabeça da Onyxia ao Grão-lorde Bolvar Fordragon em Ventobravo."},
[7496]={"Celebrar os bons tempos","Procure o Major Valadão no Vale dos Heróis."},
[7497]={"A jornada está apenas começando"},
[7498]={"Garona: Um Estudo sobre Furtividade e Traição","Devolva o livro aos legítimos donos."},
[7499]={"Códice de Defesa","Devolva o livro aos legítimos donos."},
[7500]={"Livro de Receitas do Arcanista","Devolva o livro aos legítimos donos."},
[7501]={"A Luz e Como Ativá-la","Devolva o livro aos legítimos donos."},
[7502]={"Sombras Agrilhoantes","Devolva o livro aos legítimos donos."},
[7503]={"A Grande Corrida dos Caçadores","Devolva o livro aos legítimos donos."},
[7504]={"Caçarolas: O Que a Luz Não lhe Contará","Devolva o livro aos legítimos donos."},
[7505]={"O Choque Gélido e Você","Devolva o livro aos legítimos donos."},
[7506]={"O Sonho Esmeralda...","Devolva o livro aos legítimos donos."},
[7507]={"O compêndio de Nostro","Leve o Compêndio do Abate de Dragões de Nostro até o Ateneu."},
[7508]={"Forjando a Quel'Serrar","Dê a Lâmina Élfica Lisa e Cega ao Erudito Lydros."},
[7509]={"Forjando a Quel'Serrar","Faça Onyxia soprar fogo na Lâmina Ancestral Virgem. Quando conseguir, pegue a agora Lâmina Ancestral Incandescente. Atenção, uma Lâmina Ancestral Incandescente não permanecerá assim para sempre — o tempo urge. O último passo antes de voltar para mim é matar a fera e enfiar a Lâmina Ancestral Incandescente no cadáver dela. Faça isso e Quel'Serrar será sua."},
[7563]={"Raiva de Sangue","Leve 30 garrafas de Sangue de Fera em Fúria para Mor'zul Trazangre nas Estepes Ardentes."},
[7564]={"Olholouco","Leve o Caixote de Sangue para Gorzeeki Olholouco nas Estepes Ardentes."},
[7604]={"Contrato vinculante","Entregue o Contrato da Irmandade do Tório para Lokhtos Umbrarganha, caso tenha interesse em receber as instruções para Sulfuron."},
[7621]={"Um aviso (optional explanation)"},
[7622]={"Equilíbrio entre luz e sombra","Salve 50 Camponeses antes que 15 sejam mortos. Fale com Eris Abrigoardente se conseguir completar a tarefa. Você pode conferir o Poste da Morte para saber quantos Camponeses foram mortos."},
[7623]={"Lorde Nihilus","Compre Poções Sombrias de Gorzeeki nas Estepes Ardentes. Use as poções para viajar através de Jaedenar e fale com Lorde Nihilus."},
[7624]={"Ulathek, o traidor","Confronte Ulathek, depois leve o Coração do Traidor para o Lorde Nihilus em Jaedenar."},
[7625]={"Poeira Estelar Zorothiana","Compre Poeira Estelar Zorothiana de Ur'dan. Leve-a para Gorzeeki Olholouco nas Estepes Ardentes."},
[7629]={"Entrega de diabrete","Leve o Diabrete numa Jarra para o laboratório de alquimia em Scolomântia. Depois que o pergaminho for criado, devolva a jarra para Gorzeeki Olholouco."},
[7631]={"Corcel Medonho de Zoroth","Leia as Instruções de Mor'zul. Evoque um Corcel Medonho Zorothiano, derrote-o e então vincule o espírito dele a você."},
[7632]={"A folha antiga","Encontre o dono da Folha Antiga Petrificada. Boa sorte, <name>, pois o mundo é grande."},
[7634]={"Lâmina Embrulhada de Tendão Antigo","Hastat, o Anciente, lhe pediu um Tendão de Dragão Azul Maduro. Se você encontrar esse tendão, vá falar com Hastat na Selva Maleva."},
[7635]={"A melhor corda","Stoma, o Anciente, lhe pediu um Tendão de Dragão Negro Maduro. Se você encontrar esse tendão, vá falar com Stoma na Selva Maleva."},
[7636]={"Báculo dos Antigos","Você precisa encontrar e destruir aqueles quatro corruptores demoníacos: Simone, a Sedutora. Klinfran, o Enlouquecido. Solenor, o Matador. Artórius, o Destruidor. Destrua aquelas criaturas e fale novamente com Vartrus, o Anciente, na Selva Maleva, trazendo as cabeças deles. Consulte a Casca Petrificada no seu inventário para ter pistas da localização deles. Você TEM QUE completar a tarefa sozinh<o/a>."},
[7637]={"Ênfase em sacrifício","Viaje para Altaforja e obtenha o Incensório de Exorcismo do Sumo Sacerdote Rohan. Você precisará fazer uma doação de 150 moedas de ouro para obtê-lo."},
[7639]={"O devido julgamento","Leve o Incensório de Exorcismo para Lorde Grayson Quebrassombra no Distrito da Catedral de Ventobravo."},
[7640]={"Exorcizando a Várzea do Medo","Use o Incensório de Exorcismo para expulsar os espíritos que atormentam a Várzea do Medo. Quando você tiver eliminado 25 Espíritos da Várzea do Medo, fale novamente com Lorde Grayson Quebrassombra no Distrito da Catedral de Ventobravo."},
[7641]={"O trabalho de Grimand Elmore","Fale com Grimand Elmore em Ventobravo no Distrito dos Anões de Ventobravo."},
[7642]={"Coleta de produtos","Leve 40 Runatramas, 6 Barras de Arcanita, 10 Lágrimas-de-arthas, 5 ampolas de Água Benta de Stratholme e 150 moedas de ouro para Grimand Elmore, no Distrito dos Anões de Ventobravo."},
[7643]={"O Espírito Equino Antigo","Obtenha uma ração de cavalo especial para alimentar o cavalo espiritual. Aparentemente, Judite Castanheira, que vive na Costa Sul, é a fornecedora da tal ração. Entre na masmorra de Gládio Cruel, em Feralas, e mate Gavíneo Lenhatorta. Isso libertará o Espírito Equino Antigo. Alimente-o com a ração de cavalo especial, o que acalmará o espírito. Finalmente, dê-lhe a Barda de Arcanita para que ele a abençoe."},
[7644]={"Barda de Arcanita Abençoada","Leve a Barda de Arcanita Abençoada para Lorde Grayson Quebrassombra no Distrito da Catedral de Ventobravo."},
[7646]={"O Cristal Divinatório","Leve um Diamante Azerotiano e um Diamante Preto Límpido para Lorde Grayson Quebrassombra no Distrito da Catedral de Ventobravo."},
[7647]={"Julgamento e redenção","Use o Cristal Divinatório no coração do porão do Grande Ossário, em Scolomântia. Isso invocará espíritos que você precisará julgar. A derrota dos espíritos evocará o Cavaleiro da Morte Noctilatrus. Derrote-o e reclame a alma perdida do corcel caído. Entregue a Alma Redimida do Corcel e a Barda Encantada Abençoada ao Corcel Caído de Noctilatrus."},
[7648]={"O melhor trabalho de Grimand","Leve a Barda de Arcanita para Lorde Grayson Quebrassombra no Distrito da Catedral de Ventobravo para que ele a inspecione."},
[7667]={"Ajuda material","Se você tiver interesse em ajudar Sagorne Monta Crista, no Vale da Sabedoria de Orgrimmar, leve para ele um Diamante Azerotiano e um Diamante Preto Límpido."},
[7703]={"Negócios pendentes","Encontre as Manoplas do Poder de Gordok e devolva-as para o Capitão Kebrapaw no Gládio Cruel. De acordo com Kebrapaw, a \"história de ancião\" diz que Tortheldrin — um elfo \"medonho\" que se diz príncipe — roubou as manoplas de um dos reis Gordok."},
[7761]={"Comando do Mão Negra","Sem dúvida, um orc excepcionalmente burro. Parece que para acessar o Orbe de Comando é necessário ter a Marca de Drakkisath. A carta indica que o próprio General Drakkisath a guarda. Talvez você devesse investigar."},
[7781]={"O Senhor dos Rocha Negra","Leve a Cabeça de Nefarian para o Grão-lorde Bolvar Fordragon, em Ventobravo."},
[7782]={"O Senhor dos Rocha Negra","Vá até o Vale dos Heróis, em Ventobravo, e fale com o Marechal de Campo Afrasiabi."},
[7783]={"O senhor dos Rocha Negra","Leve a Cabeça de Nefarian para Thrall, em Orgrimmar."},
[7784]={"O senhor dos Rocha Negra","Fale com o Lorde Supremo Saurfang em Orgrimmar. Ele espera por você no Vale da Força."},
[7785]={"Examine o casulo","Examine o Casulo de Renascimento e entregue-o para o Grão-lorde Dimitriano."},
[7786]={"Trovejardus, o Perseguidor dos Ventos","Para libertar Trovejardus, o Perseguidor dos Ventos, de sua prisão, você deve entregar as metades direita e esquerda dos Grilhões do Perseguidor dos Ventos, 10 Barras de Elemêntio Encantadas e a Essência do Senhor do Fogo para o Grão-lorde Dimitriano em Silithus."},
[7787]={"Erga-se, Tormentária!","Entregue a Lâmina Latente Beijada pelo Vento para o Grão-lorde Dimitriano."},
[7848]={"Harmonização com o Núcleo","Vá ao portal da entrada do Núcleo Derretido no Abismo Rocha Negra e recupere um Fragmento de Núcleo. Fale novamente com Lothos Fendespéril na Montanha Rocha Negra após recuperar o Fragmento de Núcleo."},
