[8053]={"Epítomes de poder: as braçadeiras do livre-pensador","Leve as Braçadeiras Hakkari Primevas a Jin'rokh, o Rebentador, que se encontra na Ilha Yojamba, que fica na Selva do Espinhaço. Você precisa ser no mínimo <Respeitado/Respeitada> pela Tribo Zandalar."},
[8054]={"Epítomes de poder: o cinto do livre-pensador","Leve um Xale Hakkari Primevo a Jin'rokh, o Rebentador, que se encontra na Ilha Yojamba, que fica na Selva do Espinhaço. Você precisa ser no mínimo <Honrado/Honrada> pela Tribo Zandalar."},
[8055]={"Epítomes de poder: o peitoral do livre-pensador","Leve um Tabardo Hakkari Primevo a Jin'rokh, o Rebentador, que se encontra na Ilha Yojamba, que fica na Selva do Espinhaço. Você precisa ser no mínimo <Reverenciado/Reverenciada> pela Tribo Zandalar."},
[8056]={"Epítomes de poder: as braçadeiras do áugure","Leve uma Tala Hakkari Primeva a Maywiki de Zuldazar, que se encontra na Ilha Yojamba, que fica na Selva do Espinhaço. Você precisa ser no mínimo <Respeitado/Respeitada> pela Tribo Zandalar."},
[8057]={"Epítomes de Poder: as braçadeiras do harúspice","Leve um Pilar Hakkari Primevo a Maywiki de Zuldazar, que se encontra na Ilha Yojamba, que fica na Selva do Espinhaço. Você precisa ser no mínimo <Respeitado/Respeitada> pela Tribo Zandalar."},
[8058]={"As epítomes do poder: as braçadeiras do vindicante","Leve uma Tala Hakkari Primeva a Jin'rokh, o Rebentador. Sua reputação com a Tribo Zandalar precisa ser igual ou superior a <Amistoso/Amistosa>. Jin'rokh, o Rebentador, se encontra na Ilha Yojamba, que fica na Selva do Espinhaço."},
[8059]={"Epítomes de poder: as braçadeiras do demoníaco","Leve um Pilar Hakkari Primevo a Al'tabim, que Tudo Vê. Sua reputação com a Tribo Zandalar precisa ser igual ou superior a <Amistoso/Amistosa>. Al'tabim, que Tudo Vê, se encontra na Ilha Yojamba, que fica na Selva do Espinhaço."},
[8060]={"Epítomes de poder: os braceletes do ilusionista","Leve as Braçadeiras Hakkari Primevas a Al'tabim, que Tudo Vê, que se encontra na Ilha Yojamba, que fica na Selva do Espinhaço. Você precisa ser no mínimo <Respeitado/Respeitada> pela Tribo Zandalar."},
[8061]={"Epítomes de poder: as braçadeiras do confessor","Leve um Pilar Hakkari Primevo a Al'tabim, que Tudo Vê, que se encontra na Ilha Yojamba, que fica na Selva do Espinhaço. Você precisa ser no mínimo <Respeitado/Respeitada> pela Tribo Zandalar."},
[8062]={"Epítomes de poder: as braçadeiras do predador","Leve as Braçadeiras Hakkari Primevas a Falthir, o Cego, que se encontra na Ilha Yojamba, que fica na Selva do Espinhaço. Você precisa ser no mínimo <Respeitado/Respeitada> pela Tribo Zandalar."},
