[8728]={"As boas e más notícias","Narain Suavestilo, em Tanaris, quer que você leve para ele 20 Barras de Arcanita, 10 Minérios de Elemêntio, 10 Diamantes Azerotianos e 10 Safiras Azuis."},
[8729]={"A ira de Neptulon","Use a Boia de Arcanita na Voragem Serpenteante da Baía das Tempestades, que fica em Azshara."},
[8730]={"A corrupção de Nefarius","Mate Nefarian e recupere o Estilhaço de Cetro Vermelho. Devolva o Estilhaço de Cetro Vermelho a Anacronos nas Cavernas do Tempo, em Tanaris. Você tem 5 horas para concluir a tarefa."},
[8733]={"Erânicos, Tirano dos Sonhos","Vá para o continente de Teldrassil e encontre o agente de Malfurion perto das muralhas de Darnassus."},
[8734]={"Tyrande e Remulos","Vá à Clareira da Lua e fale com o Guardião Remulos."},
[8735]={"A Corrupção do Pesadelo","Vá até os quatro portais do Sonho Esmeralda em Azeroth e obtenha um Fragmento da Corrupção do Pesadelo de cada um. Quando tiver cumprido essa tarefa, fale novamente com o Guardião Remulos na Clareira da Lua."},
[8736]={"Os pesadelos manifestos","Defenda o Refúgio Noturno de Erânicos. Impeça que o Guardião Remulos pereça. Não mate Erânicos. Defenda-se. Espere Tyrande."},
