[8784]={"Segredos dos Qiraji","Leve o Artefato Qiraji Antigo aos dragões escondidos perto da entrada do templo."},
[8789]={"Armamentos Imperiais Qiraji","Arygos, no Templo de Ahn'Qiraj, criará Armamentos Infundidos em Elemêntio para você. Para tanto, entregue-lhe Armamentos Imperiais Qirajis e 3 Minérios de Elemêntio."},
[8790]={"Paramentos Imperiais Qiraji","Merithra do Sonho, no Templo de Ahn'Qiraj, criará Armamentos Infundidos em Elemêntio para você. Para tanto, entregue-lhe Paramentos Imperiais Qiraji e 3 Minérios de Elemêntio."},
[8791]={"A queda de Ossirian","Entregue a Cabeça de Ossirian, o Imaculado, ao Comandante Mar'alith no Forte Cenariano, que fica em Silithus."},
[8801]={"O legado de C'Thun","Leve o Olho de C'Thun para Celestrasz no Templo de Ahn'Qiraj."},
[8802]={"O salvador de Kalimdor","Leve o Olho de C'Thun para Anacronos nas Cavernas do Tempo."},
[8945]={"Súplica de um morto","Entre em Stratholme e resgate Ysida Harmon do Barão Rivendare."},
[8946]={"Prova de vida","Leve o Medalhão de Ysida para Anthion Harmon nas Terras Pestilentas Orientais."},
[8948]={"Um velho amigo de Anthion","Leve o Estandarte Incompleto da Provocação para Falrin Arboril na biblioteca do Gládio Cruel."},
[8949]={"A vendeta de Falrin","Colete 25 Colares de Guerra dos Ogros dos Ogros no Gládio Cruel ou no Pico da Rocha Negra e fale novamente com Falrin Arboril no Ateneu do Gládio Cruel."},
[8950]={"O encantamento do instigador","Leve os seguintes materiais para Falrin Arboril no Gládio Cruel: 1 Essência de Espírito Zombeteiro, 4 Runas Negras e 8 Estilhaços Brilhantes Grandes."},
[8961]={"Três reis das chamas","Colete a Incendicita de Incendius, a Brasa do Mirabrasa e a Cinza das Cinzas, além de um Braseiro Santificado, e fale novamente com Bodley na Montanha Rocha Negra."},
[8966]={"A parte esquerda do amuleto do Lorde Valthalak","Use o Braseiro de Sinalização para evocar o espírito de Mor Casco Gris e então mate-o. Fale novamente com Bodley na Montanha Rocha Negra, com a Parte Esquerda do Amuleto do Lorde Valthalak e o Braseiro de Sinalização."},
[8967]={"A parte esquerda do amuleto do Lorde Valthalak","Use o Braseiro de Sinalização para evocar o espírito de Isalien e então mate-o. Fale novamente com Bodley na Montanha Rocha Negra, com a Parte Esquerda do Amuleto do Lorde Valthalak restaurado e o Braseiro de Sinalização."},
[8968]={"A parte esquerda do amuleto do Lorde Valthalak","Use o Braseiro de Sinalização para evocar os espíritos de Jil e Soeiro e então mate os dois. Fale novamente com Bodley na Montanha Rocha Negra, com a Parte Esquerda do Amuleto do Lorde Valthalak e o Braseiro de Sinalização."},
[8969]={"A parte esquerda do amuleto do Lorde Valthalak","Use o Braseiro de Sinalização para evocar o espírito de Kormok e então mate-o. Fale novamente com Bodley, na Montanha Rocha Negra, com a Parte Esquerda do Amuleto do Lorde Valthalak e o Braseiro de Sinalização."},
[8989]={"A parte direita do amuleto do lorde Valthalak","Use o Braseiro de Sinalização para evocar o espírito de Mor Casco Gris e então mate-o. Fale novamente com Bodley na Montanha Rocha Negra, com o Amuleto do Lorde Valthalak restaurado e o Braseiro de Sinalização."},
[8990]={"A parte direita do amuleto do Lorde Valthalak","Use o Braseiro de Sinalização para evocar o espírito de Isalien e então mate-a Fale novamente com Bodley dentro da Montanha Rocha Negra. Leve o Amuleto do Lorde Valthalak recombinado e o Braseiro de Sinalização."},
[8991]={"A parte direita do amuleto do Lorde Valthalak","Use o Braseiro de Sinalização para evocar os espíritos de Jil e Soeiro e então mate os dois. Fale novamente com Bodley na Montanha Rocha Negra, com o Amuleto do Lorde Valthalak restaurado e o Braseiro de Sinalização."},
[8992]={"A parte direita do amuleto do Lorde Valthalak","Use o Braseiro de Sinalização para evocar o espírito de Kormok e então mate-o. Fale novamente com Bodley na Montanha Rocha Negra, com o Amuleto do Lorde Valthalak restaurado e o Braseiro de Sinalização."},
[8994]={"Preparativos finais","Colete 40 Braceletes de Rocha Negra e consiga um Frasco de Poder Supremo. Leve tudo para Bodley, dentro da Montanha Rocha Negra."},
[8995]={"Mea culpa, Lorde Valthalak","Use o Braseiro de Sinalização para evocar o Lorde Valthalak. Acabe com ele e use o Amuleto do Lorde Valthalak no cadáver. Em seguida, devolva o Amuleto do Lorde Valthalak ao Espírito de Lorde Valthalak."},
[9015]={"O desafio","Viaje até o Círculo da Lei no Abismo Rocha Negra e coloque o Estandarte da Provocação no centro enquanto ouve a sentença do Supremo Juiz Durólito. Mate Theldren e seus gladiadores e fale novamente com Anthion Harmon nas Terras Pestilentas Orientais em posse da primeira parte do amuleto de Lorde Valthalak."},
[9023]={"O veneno perfeito","Dirk Fortelenho no Forte Cenariano quer que você leve para ele uma Vesícula de Peçonha de Venoxis e uma Vesícula de Peçonha de Kurinnaxx."},
[9033]={"Ecos da Guerra","O Comandante Eligor Alvorada, na Capela Esperança da Luz, que fica nas Terras Pestilentas Orientais, quer que você mate 5 Monstruosidades Vivas, 5 Gárgulas Litopele, 8 Capitães Cavaleiros da Morte e 3 Espreitadoras Peçonhentas."},
[9034]={"Peitoral Couraçado","Korfax, que está na Capela Esperança da Luz, nas Terras Pestilentas Orientais, fará para você um Peitoral Couraçado caso você leve para ele os seguintes itens: 1 Peitoral Profanado, 25 Restos de Placas, 4 Barras de Arcanita e 2 Cristais do Nexus."},
[9036]={"Coxotes Couraçados","Korfax, que está na Capela Esperança da Luz, nas Terras Pestilentas Orientais, fará para você Coxotes Couraçados caso você leve para ele os seguintes itens: 1 par de Coxotes Profanados, 20 Restos de Placas, 4 Barras de Arcanita e 3 Pelegos Rústicos Curados."},
[9037]={"Capacete Couraçado","Korfax, que está na Capela Esperança da Luz, nas Terras Pestilentas Orientais, fará para você um Capacete Couraçado caso você leve para ele os seguintes itens: 1 Capacete Profanado, 15 Restos de Placas, 5 Barras de Arcanita e 1 Cristal do Nexus."},
