[2199]={"Мудрость за деньги","Принесите пять серебряных слитков Талвашу де Кисселю в Стальгорн."},
[2200]={"Назад в Ульдаман","Выясните, где именно в Ульдамане находится ожерелье Талваша. Убитый паладин, о котором он упоминал, был последним владельцем этого ожерелья."},
[2201]={"Время собирать камни","Найдите рубин, сапфир, и топаз, которые спрятаны в разных местах Ульдамана. Когда найдете, свяжитесь с Талвашем де Кисселем, используя фиал Видения, который он предоставил. Из дневника вы узнали следующее: *Рубин укрыт в забаррикадированной Кузне Теней. *Топаз спрятан в урне в одной из областей, занятых троггами, недалеко от расположения дворфов Альянса. *Сапфир присвоил себе Гримлок, лидер троггов."},
[2202]={"В Ульдаман за реактивом","Принести 12 грибов-малиновиков Джаркалу Замшелому Клыку в Каргат."},
[2204]={"Восстановление ожерелье","Добудьте источник энергии из самого мощного волшебного создания, которое найдете в Ульдамане и доставьте его Талвашу де Кисселю в Стальгорн."},
[2240]={"Потайной чертог","Прочитайте журнал Бейлога, исследуйте, потайной чертог и потом доложите об увиденном геологу Грозовой Вершине."},
[2258]={"Пробежка по Бесплодным землям","Принесите 5 вторых желудков канюка, 10 клыков скального койота и 5 осколков каменных элементалей Джаркалу Смешанному Лишайнику в Каргат."},
[2278]={"Платиновые Диски","Поговорите с каменным Стражем и запомните все, что он передаст вам. Когда он закончит свой пересказ событий древности, активируйте диски Норганнона."},
[2280]={"Платиновые Диски","Отнесите миниатюрную копию дисков Норганнона кому-то из мудрецов с Громового Утеса."},
[2283]={"Пропавшее ожерелье","Найдите на раскопках Ульдамана драгоценное ожерелье (возможно, поврежденное) и принесите его в Оргриммар Драну Дрофферсу."},
[2284]={"Пропавшее ожерелье, этап 2","Разыщите ключ к местонахождению самоцветов в глубинах Ульдамана."},
[2318]={"Трудности перевода","Найдите кого-нибудь, кто сможет перевести для вас дневник паладина. Ближайший к вам такой умелец, скорее всего, найдется в Каргате, форпосте в Бесплодных Землях."},
[2338]={"Трудности перевода","Одолжите ожерелье Джаркалу. Взамен он переведет дневник."},
[2339]={"Найти самоцветы и источник энергии","Добудьте все три самоцвета и источник энергии для ожерелья из Ульдамана и принесите их Джаркалу Замшелому Клыку в Каргат. Джаркал считает, что источник энергии можно найти у самой сильной твари в Ульдамане. Из дневника следует... * Рубин спрятан на огражденной завалами территории Кузни Теней. *Топаз спрятан в урне на территорях троггов под боком у дворфов Альянса. *Сапфир забрал Гримлок, старейшина троггов."},
[2342]={"Возвращенные сокровища","Принесите Патрику Гарретту в Подгород фамильное сокровище из сундука в Южном зале Ульдамана."},
[2398]={"Потерянные дворфы","Найдите Бейлога в Ульдамане."},
[2418]={"Камни Силы","Принесите 8 дентриевых камней Силы и 8 энелиевых камней Силы Ригглфаззу в Бесплодные земли."},
[2500]={"За реактивами в Бесплодные земли","Добудьте в Бесплодных землях реактивы для Гхака Целителя и отнесите их ему в Телcамар."},
[2768]={"Изыскательский стержень","Принесите изыскательский cтержень главному инженеру Чепухастеру в Прибамбасск."},
[2770]={"Газ'рилла","Принесите искрящую чешую Газ'риллы Виззлу Медноштифу на Мерцающую равнину."},
[2841]={"Техновойны","Добудьте в Гномрегане чертежи боевой машины и код от сейфа Термоштепселя в Гномрегане и принесите их Ноггу в Оргриммар."},
[2842]={"Главный инженер Скути","Поговорите со Скути в Пиратской бухте."},
[2843]={"Поехалиии!","Дождитесь, пока Скути настроит гоблинский импульсный повторитель."},
[2846]={"Тиара глубин","Принесите Тиару Глубин Табете в Пыльную Трясину."},
[2865]={"Панцири скарабеев","Принести 5 целых панцирей скарабея Тран'реку в Прибамбасск."},
[2904]={"Катавасия","Отведите Керноби к Часовому ходу. Затем отправляйтесь с донесением к Скути в Пиратскую бухту."},
[2922]={"Промыть мозг Техботу","Принесите ядро памяти Техбота мехмастеру Замыкальцу в Стальгорн."},
[2924]={"Базовый элемент","Принесите 12 базовых элементов Клацморту Гайкокруту в Стальгорн."},
[2926]={"Новая формула","Соберите радиоактивный осадок, оставляемый облученными захватчиками и облученными погромщиками в пустой свинцовый фиал для образцов. Принесите полный фиал Оззи Триггервольту в Каранос."},
[2928]={"Сооружение автогиробуророек","Принесите Шони в Штормград 24 горсти механических внутренностей роботов."},
[2929]={"Великое предательство","Отправляйтесь в Гномреган и убейте Мекжинера Термоштепселя. Вернитесь к Главному Механику Меггакруту."},
[2930]={"Спасение данных","Принесите призматическую перфокарту главному механику Чугунотрубзу в Стальгорн."},
[2933]={"Бутыли с ядом","Принесите бутылку яда аптекарю на Мельницу Таррен."},
[2934]={"Неповрежденная ядовитая железа","Принесите неповрежденную ядовитую железу аптекарю Лидону на Мельницу Таррен."},
[2935]={"Разговор с мастером Гадрином","Поговорите с мастером Гадрином в деревне Сен'джин."},
[2936]={"Паучья богиня","Прочитайте надписи на табличке Теки, узнайте имя паучьей богини, которой поклоняются тролли Сухокожих, а потом возвращайтесь к мастеру Гадрину."},
[2945]={"Кольцо, покрытое грязью","Придумайте, как отчистить кольцо, покрытое грязью."},
[2947]={"Возвращение кольца","Вы можеть оставить кольцо себе, а можете попытаться найти того, чьи инициалы выгравированы на внутренней стороне кольца."},
[2948]={"Гномское усовершенствование","Принесите блестящее золотое кольцо, слиток серебра, моховой агат и 30 серебряных монет Талвашу де Кисселю в Стальгорн."},
[2949]={"Возвращение кольца","Вы можеть оставить кольцо себе, а можете попытаться найти того, чьи инициалы выгравированы на внутренней стороне кольца."},
[2950]={"Переделка кольца","Принесите блестящее золотое кольцо, слиток серебра, моховой агат и 30 серебряных монет Ноггу в Огргиммар."},
[2951]={"Чистер 5200!","Опустите покрытый грязью предмет и три серебряные монеты в Чистер 5200."},
[2962]={"Сильное зеленое свечение","Отправляйтесь в Гномреган и принесите высокорадиоактивные образцы. Внимание: отходы нестабильны и довольно быстро разрушаются. Верните Оззи тяжелую освинцованную склянку для проб, когда задача будет выполнена."},
[2988]={"Тролльи клетки","Проверьте клетки в двух деревнях Сухокожих и возвращайтесь к дрессировщику грифонов Разящему Когтю."},
[2989]={"Алтарь Зула","Осмотрите вершину Алтаря Зула и возвращайтесь к укротителю грифонов Разящему Когтю."},
[2990]={"Тадиус Мрачная Тень","Принесите перо Остроклюва Тадиусу Мрачной Тени в Выжженные земли."},
[2991]={"Медальон Некрума","Отнесите медальон Некрума Тадиусу Мрачной Тени в Выжженные земли."},
[3042]={"Троллье месиво","Принесите 20 фиалов с Тролльим месивом."},
[3341]={"Да сгинет Хладовей","Эндрю Браунелл поручил вам убить Амненнара Хладовея и принести его череп."},
[3373]={"Сущность Эраникуса","Поместите сущность Эраникуса в купель сущности в его логове в затонувшем храме."},
[3444]={"Круглый камень","Заберите круглый камень из мастерской Марвона Клепальщика в Кабестане."},
[3446]={"Во глубине болот","Найдите алтарь Хаккара в затонувшем храме на Болоте Печали."},
[3447]={"Тайна камня","Отправляйтесь в затонувший храм и узнайте, что скрывается в круге статуй."},
[3520]={"Духи крикунов","Поймайте души трех крикунов из Фераласа и возвращайтесь к Йе'кинье в Порт Картеля."},
[3523]={"Плеть в холмах","Если вы хотите помочь Белнистразу, поговорите с ним еще раз и верните ему Камень клятвы, который он дал вам."},
[3525]={"Уничтожить идола","Сопроводите Белнистраза к идолу свинобразов на Курганах Иглошкурых. Защищайте Белнистраза, пока он будет проводить ритуал, чтобы разрушить идола."},
[3527]={"Пророчество Мошару","Принесите первую и вторую таблички Мошару Йе'кинье в Танарис."},
[3528]={"Бог Хаккар","Отнесите заполненное яйцо Хаккара Йе'кинье в Танарис."},
[3636]={"Нести свет","Убейте Амненнара Хладовея на Курганах Иглошкурых."},
[3701]={"Дымящиеся руины Тауриссана","Пойдите в руины Тауриссана в Пылающих степях и добудьте информацию из таурисанских реликвий. Вернитесь к королевскому историку Аркессону."},
[3702]={"Дымящиеся руины Тауриссана","Узнайте от королевского историка Аркессона историю Тауриссана."},
[3765]={"Проблема за морем","Отправляйтесь в Аубердин к Гершалу Шепоту Ночи."},
[3801]={"Наследие Черного Железа","Чтобы получить ключ от города, поговорите с Франклорном Искусником."},
[3802]={"Наследие Черного Железа","Убейте Точеня Темностроя и добудьте великий молот, Железный Друг. Отнесите Железного Друга в святилище Тауриссана и вложите его в руки статуи Франклорна Искусника."},
[3906]={"Дисгармония пламени","Отправьтесь в карьер у Черной горы и уничтожьте Подчинителя Пирона. По выполнению вернитесь к Громосерду."},
[3907]={"Дисгармония пламени","Ступайте в глубины Черной горы и выследите лорда Опалителя. Убейте его и принесите Громосерду все, что может дать какую-то информацию."},
[3981]={"Командир Гор'шак","Найдите командира Гор'шака в Глубинах Черной горы. Судя по рисунку в записке, искать следует в темнице где-то вроде того."},
[3982]={"Что происходит?","Защитите Горшака."},
[4001]={"Что происходит?","Поговорите с дворфом по имени Каран Могучий Молот и соберите информацию о похищении принцессы Мойры Бронзобород. Передайте информацию Траллу в Оргриммар. Карана держат в темнице напротив."},
[4002]={"Восточные королевства","Поговорите с Траллом."},
[4003]={"Спасение принцессы","Убейте императора Даграна Тауриссана и освободите принцессу Мойру Бронзобород от его черного заклятия."},
[4022]={"Вкус пламени","Покажите Цирусу Раскаивателю сброшенную кожу черного дракона, полученную от Каларана Ветрореза."},
[4024]={"Вкус пламени","Отправьтесь в глубины Черной горы и убейте Бейл'Гора. Известно лишь то, что великан живет в глубинах. Воспользуйтесь измененной сброшенной шкурой черного дракона и возьмите из останков Бейл'Гора сущность Огня. Отнесите пойманную сущность Огня Цирусу Раскаивателю."},
[4061]={"Восстание машин","Отправляйтесь в Пылающие степи и соберите 10 осколков элементалей для верховной жрицы Теодоры Мальвадании. Теодора упоминала, что осколки можно найти у элементалей и големов."},
[4062]={"Восстание машин","Отнесите образец осколка элементаля Лотвилю Вериатусу. Теодора упоминала, что его лагерь находится на востоке."},
[4063]={"Восстание машин","Найдите и убейте повелителя големов Аргелмаха. Принесите его голову Лотвилу. Также соберите 10 невредимых ядер стихий с беспощадных големов и созданий-завоевателей, охраняющих Аргелмаха. Информация передана посредством телепатии."},
[4081]={"УНИЧТОЖИТЬ НА МЕСТЕ: Дворфы Черного Железа","Отправляйтесь в Глубины Черной горы и уничтожьте подлых агрессоров! По приказу полководца Клинозуба уничтожьте 15 охранников, 10 надсмотрщиков и 5 пехотинцев из клана Ярости Горна. Вернитесь сразу по выполнении задания."},
[4082]={"УНИЧТОЖИТЬ НА МЕСТЕ: Высокопоставленные чины Черного Железа","Отправляйтесь в Глубины Черной горы и уничтожьте подлых агрессоров! По приказу полководца Клинозуба уничтожьте 10 медиков, 10 солдат и 10 офицеров из клана Ярости Горна. Вернитесь сразу по выполнении задания."},
[4083]={"Призрачный кубок"},
[4121]={"Опасное положение","Отконвоируйте пленника, Грарка Лорктуба, через Пылающие степи и Черную гору к Тлеющему ущелью. Лекслорт что-то говорил насчет того, что по другую сторону будут ждать его ребята, которые уведут Грарка в тюрьму. Также отдайте Лекслорту ториевые оковы."},
[4122]={"Грарк Лоркруб","Отправьтесь в Пылающие степи и найдите Грарка Лоркруба. Лекслорт упоминал, что в последний раз предателя видели в крепости Черной горы. По обнаружении Грарка Лоркруба закуйте его в ториевые оковы и затем доставьте его от Черной горы к Тлеющему ущелью, Лекслорт и его подчиненные займутся допросом преступника."},
[4123]={"Сердце горы","Принесите сердце горы Максворту Суперблеску в Пылающие степи."},
[4126]={"Харли Пьянодых","Найдите украденный рецепт громоварского и верните его Рагнару Громовару в Каранос."},
[4132]={"Операция:смерть Кузне Гнева","Отправляйтесь в Глубины Черной горы и убейте генерала Кузню Гнева. Вернитесь к полководцу Клинозубу по выполнении задания."},
[4134]={"Украденный рецепт громоварского","Принесите рецепт громоварского светлого Вивиан Лягроб в Каргат."},
[4136]={"Риббли Крутипроб","Принесите голову Риббли Юке Крутипроб в Пылающие степи."},
[4141]={"Майджин и Ларион","Соберите 15 кровоцветов и принесите их Майджину."},
[4142]={"Визит к Грегану","Отнесите кровоцвет Грегану Пивоплюю в Фералас."},
[4143]={"Туман зла","Соберите 5 образцов тумана Аталаи и принесите их Майджину в Кратер Ун'Горо."},
[4145]={"Ларион и Майджин","Уничтожьте 5 кровоцветов-хлестунов, 5 кровоцветов-крепкозубов, 5 кровоцветов-живодеров и 5 кровоцветов-звероловов по просьбе Лариона из Укрытия Маршалла."},
[4146]={"Питание для шокера","Доставьте незаряженный шокер и 5 образцов тумана Аталаи Лариону в Укрытие Маршалла."},
[4147]={"Мастерская Марвона","Отправьтесь к Марвону Клепальщику в его мастерскую в Кабестане."},
[4182]={"Драконья угроза","Убейте 15 детенышей черного дракона, 10 черных драконидов, 4 черных драконид и 1 черного дракона. По выполнении задания вернитесь к Хелендису Речному Мысу."},
[4183]={"Подлинные хозяева","Отправьтесь в Приозерье и доставьте письмо Хелендиса Речного Мыса мировому судье Соломону."},
[4184]={"Подлинные хозяева","Передайте обращение Соломона верховному лорду Болвару Фордрагону. Болвар Фордрагон пребывает в Крепости Штормграда."},
[4185]={"Подлинные хозяева","Поговорите с Верховным лордом Болваром Фордрагоном после беседы с леди Катраной Престор."},
[4186]={"Подлинные хозяева","Отнесите указ Болвара мировому судье Соломону в Приозерье."},
[4201]={"Приворотное зелье","Принесите 4 листа крови Грома, 10 огромных серебряных слитков и наполненный сосуд Нагмары госпоже Нагмаре в Глубины Черной горы."},
[4223]={"Подлинные хозяева","Поговорите с маршалом Максвеллом в Пылающих степях."},
[4224]={"Подлинные хозяева","Поговорите с Джоном-Оборванцем и узнайте о судьбе маршала Виндзора. По выполнении задания вернитесь к маршалу Максвеллу. Кажется, маршал Максвелл говорил, что Джона следует искать в пещере на севере."},
[4241]={"Маршал Винздор","Отправляйтесь на Черную гору на северо-западе и войдите в ее глубины. Узнайте, что сталось с маршалом Виндзором. Кажется, Джон-Оборванец говорил о том, что Виндзора утащили в темницу."},
[4242]={"Утраченная надежда","Сообщите маршалу Максвеллу плохие новости."},
[4262]={"Подчинитель Пирон","Убейте подчинителя Пирона и вернитесь к Джалинде Тирлипуньке. Кажется, Джалинда говорила, что Пирон охраняет каменоломню. Может, поискать его там?"},
[4263]={"Опалитель!","Отыщите и уничтожьте лорда Опалителя в глубинах Черной горы!"},
[4264]={"Измятая записка","Не исключено, что ваша находка заинтересует маршала Виндзора. Может быть, все не так плохо, и надежда еще жива."},
[4282]={"Проблеск надежды","Верните маршалу Виндзору утерянную информацию. Маршал уверен, что информацией завладели повелитель големов Аргелмах и генерал Кузня Гнева."},
[4286]={"Хороший товар","Отправьтесь в глубины Черной горы и принесите 20 поясных сумок дворфов Черного Железа. По выполнении задания вернуться к Орелиусу. Предположительно поясные сумки можно отобрать у дворфов Черного Железа в глубинах Черной горы."},
[4322]={"Побег!","Помогите маршалу Виндзору забрать вещи и освободить его друзей, после чего вернитесь к маршалу Максвеллу и получите дальнейшие инструкции."},
[4341]={"Каран Могучий Молот","Пойдите в Глубины Черной горы и найдите Карана Могучего Молота. Король упомянул, что Каран сидит там в плену – может, стоит поискать темницу."},
[4342]={"Рассказ Карана","Выслушайте рассказ Карана Могучего Молота."},
[4361]={"Недобрые вести","Вернитесь в Стальгорн и сообщите нехорошие новости королю Магни Бронзобороду."},
[4362]={"Судьба королевства","Вернитесь в Глубины Черной горы и освободите принцессу Мойру Бронзобород от злобного императора Даграна Тауриссана."},
[4701]={"Устранение опасности","Отправьтесь на пик Черной горы и уничтожьте источник опасности. Хелендис кричит вам вслед одно имя: Халикон. Именно его упоминали орки в связи с воргами."},
[4724]={"Праматерь стаи","Убейте Халикон, праматерь стаи воргов Кровавого Топора."},
[4726]={"Сущность детеныша дракона","Принесите 8 сущностей детенышей драконов и Драко-инкарцинатор 900 Тинки Кипеллер в Пламенеющий Стяг в Пылающих степях."},
[4729]={"Редкие звери Киблера","Отправьтесь на пик Черной горы и отыщите там щенков воргов легиона Кровавого Топора. Посадите маленьких тварей в клетку и отнесите Киблеру."},
[4734]={"Заморозка яйца","Испытайте прототип яйцехладоскопа на одном из яиц в Гнездовье."},
[4735]={"Сбор яиц","Принесите 8 драконьих яиц и устройство-коллекционер Тинки Кипеллер в Пламенеющий Стяг в Пылающих степях."},
[4742]={"Печать Вознесения","Найдите самоцвет Тлеющего Терновника, самоцвет Черной Вершины и самоцвет Кровавого Топора. Верните их Ваелану вместе с простой печатью Вознесения. Камни могут быть у трех генералов: у воеводы Вуна из клана Тлеющего Терновника, у вождя Омокка из клана Черной Вершины и у повелителя Змейталака из клана Кровавого Топора."},
[4764]={"Пряжка Роковой оснастки","Принесите пряжку Роковой оснастки Майре Светлое Крыло в Пылающие степи."},
[4768]={"Табличка Темнокамня","Принесите табличку Темного Камня тенемагу Вивиан Лаграв в Каргат."},
[4771]={"Рассветный гамбит","Отнесите \"Рассветный гамбит\" в Демонстрационную комнату в Некроситете. Уничтожьте Вектуса и возвращайтесь к Бетине Биггльцинк."},
[4787]={"Древнее яйцо","Принесите древнее яйцо Йе'кинье в Танарис."},
[4788]={"Последние таблички","Принесите пятую и шестую таблички Мошару геологу Железному Башмаку в Танарисе."},
[4808]={"Фелнок Сталлист","Отнесите письмо Тинки Фелноку Сталлисту."},
[4809]={"Рога стылодыхов","Принесите 8 безупречных рогов стылодыха Фелноку Сталлисту."},
[4810]={"Возвращение к Тинки","Отнесите ящик Фелнока Тинки Кипеллер в Пылающие степи."},
[4862]={"Товар на любителя","Отправьтесь на пик Черной горы и принесите Киблеру 15 яиц скального паука. Судя по всему, яйца надо искать недалеко от пауков."},
[4866]={"Материнское молоко","Найдите в самом сердце пика Черной горы мать Дымную Паутину. Сражайтесь с ней, пока она не введет вам свой яд. Скорее всего ее также придется убить. Когда яд будет в вас, вернитесь к Джону-Оборванцу, чтобы он смог добыть яд."},
[4867]={"Аррок Смертный Вопль","Прочитайте записку Вароша. Принесите Варошу его амулет."},
[4903]={"Приказ полководца","Убейте вождя Омокка, воеводу Вуна и повелителя Змейталака. Найденные при них важные бумаги Черной горы доставьте полководцу Клинозубу в Каргат."},
[4907]={"Тинки Кипеллер","Поговорите с Тинки Кипеллер."},
[4941]={"Мудрость Эйтригга","Поговорите с Эйтриггом в Оргриммаре. После этого обратитесь к вождю Траллу. В последний раз Эйтригг был в в зале приемов Тралла."},
[4974]={"За Орду!","Пойдите в Пик Черной горы и убейте вождя Ренда Чернорука. Принесите его голову в Оргриммар."},
[4981]={"Агент Блестяшка","Отправьтесь к пику Черной горы и выясните, что сталось с Блестяшкой."},
[4982]={"Вещи Блестяшки","Найдите вещи Блестяшки и верните их владелице. Блестяшка сказала, что она спрятала свое оборудование где-то на нижнем ярусе подземелья."},
[4983]={"По данным разведки","Передайте донесение Блестяшки гроссмейстеру Лекслорту в Каргат."},
[5001]={"Вещи Блестяшки","Найдите вещи Блестяшки и верните их владелице. Удачи!"},
[5002]={"Донесение Максвелла","Передайте маршалу Максвеллу информацию Блестяшки."},
[5047]={"Пип Смышлен, к вашим услугам!","Переговорите с Малифоем Черномолотом в Круговзоре."},
[5065]={"Утраченные таблички Мошару","Принесите третью и четвертую таблички Мошару геологу Железному Башмаку в Танарис."},
[5081]={"Миссия Максвелла","Отправляйтесь на пик Черной горы и устраните воеводу Вуна, вождя Омокка и повелителя Змейталака. По выполнении задания вернитесь к маршалу Максвеллу."},
[5089]={"Приказ генерала Драккисата","Отнесите приказ генерала Драккисата маршалу Максвеллу в Пылающие степи."},
[5102]={"Кончина генерала Драккисата","Отправьтесь на пик Черной горы и устраните генерала Драккисата. По выполнении задания вернитесь к маршалу Максвеллу."},
[5122]={"Медальон Веры"},
[5125]={"Слова Аурия"},
[5127]={"Демонова кузня","Отправляйтесь на пик Черной горы и найдите Горалука Треснувшую Наковальню. Убейте его, а потом воткните в труп окровавленную пику. Таким образом пика вытянет его душу и окрасится ей. Кроме того, вам нужно найти заготовку рунической кирасы. Отнесите пику и кирасу Лораксу в Зимних Ключах."},
[5160]={"Матрона-защитница","Дойдите до Зимних Ключей и найдите Халех. Отдайте ей пластину чешуи Ауби."},
[5212]={"Плоть не лжет","Принесите 20 препаратов чумной плоти из Стратхольма Бетине Биггльцинк. Предположительно, любая тварь из Стратхольма сойдет за препарат."},
[5213]={"Вирус чумы","Отправляйтесь в Стратхольм и исследуйте зиккураты. Доставьте сведения о Плети Бетине Биггльцинк."},
[5214]={"Великий Эзра Гримм","Найдите табачную лавку Эзры Гримма в Стратхольме, отыщите в ней коробку отличного табака Эзры Гримма и принесите ее Дымку ЛаРу."},
[5243]={"Святая вода","Отправляйтесь на север, в Стратхольм. Обыщите брошенные ящики с припасами и соберите 5 мер святой воды Стратхольма. Возвращайтесь к Леониду Бартоломею Чтимому, как только воды будет достаточно."},
[5244]={"Руины Кел'Терила","Поговорите с Джероном Гранильщиком в деревне Звездопада."},
[5245]={"Беспокойные духи Кел'Терила","Используйте кирку Джерона, чтобы добыть фрагменты реликвии высокорожденных, Принесите их Авроре Зову Небес в Восточные Чумные земли."},
[5246]={"Фрагменты прошлого","Найдите Священные письмена высокорожденных в Храме Зин-Малор, в Азшаре и принесите их Авроре Зову Небес к Башне Северного перевалa, в Восточных Чумных землях."},
[5247]={"Фрагменты прошлого","Принесите зачарованный слиток тория, 5 кристаллов Восстановления и фиал пугающей воды Авроре Зову Небес к башне Северного Перевала, в Восточных Чумных землях."},
[5251]={"Архивариус","Отправляйтесь в Стратхольм и отыщите архивариуса Галфорда из Алого ордена. Убейте его и сожгите архив Алых."},
[5262]={"Ошеломляющая истина","Отнесите голову Бальназара герцогу Николасу Зверенхоффу в Восточные Чумные земли."},
[5263]={"Быстрее, выше, сильнее","Отправляйтесь в Стратхольм и убейте барона Ривендера. Принесите его голову герцогу Николасу Зверенхоффу."},
[5281]={"Мятущиеся души","Найдите Эгана. В последний раз его видели недалеко от Стратхольма."},
[5282]={"Мятущиеся души","Стреляйте в призраков и неупокоенных на улицах Стратхольма из излучателя Эгана. Когда душа вырвется из призрачной оболочки, выстрелите в нее еще раз, и она обретет свободу. Освободите 15 неупокоенных душ и возвращайтесь к Эгану."},
[5341]={"Сокровище Баровых","Отправляйтесь в Некроситет и добудьте сокровище семьи Баровых. Оно состоит из четырех документов: на Каэр Дарроу, на Брилл, на Мельницу Таррен и на Южнобережье. После выполнения задания вернитесь к Алексию Барову."},
[5343]={"Сокровище Баровых","Отправляйтесь в Некроситет и добудьте сокровище семьи Баровых. Оно состоит из четырех документов: на Каэр Дарроу, на Брилл, на Мельницу Таррен и на Южнобережье. После выполнения задания вернитесь к Велдону Барову."},
[5382]={"Доктор Теолен Крастинов – Мясник","Найдите в Некроситете доктора Теолена Крастинова. Убейте его, затем сожгите останки Евы и Люсьена Саркофф. Выполнив задание, возвращайтесь к Еве Саркофф."},
[5384]={"Киртонос Глашатай","Вернитесь в Некроситет с кровью невинных. Найдите балкон и вылейте кровь в жаровню. На зов явится Киртонос. Сражайтесь как герой, не сдавайтесь! Уничтожьте Киртоноса и возвращайтесь к Еве Саркофф."},
[5461]={"Рас Ледяной Шепот – человек","Отправляйтесь в высокогорья Арати, в руины Стромгарда. Поищите в Стромгарде книгу Воспоминаний. Если удастся ее отыскать, отнесите ее мировому судье Мардуку."},
[5462]={"Рас Ледяной Шепот – гибель","Отправляйтесь в часовню Светлых надежд в Восточных Чумных землях и найдите Леонида Бартоломея Чтимого. Покажите ему книгу Воспоминаний и расскажите обо всем, о чем удалось узнать."},
[5463]={"Дар Менетила","Отправляйтесь в Стратхольм и отыщите Дар Менетила. Положите книгу Воспоминаний на оскверненную землю."},
[5464]={"Дар Менетила","Отнесите Книгу Души Леониду Бартоломею в Восточные Чумные земли."},
[5465]={"Книга Души","Возвращайтесь к мировому судье Мардуку в Каэр Дарроу. Покажите ему Книгу Души."},
[5466]={"Рас Снегошепот – лич","Отыщите в Некроситете Раса Снегошепота. Найдя его, воспользуйтесь Книгой Души против его посмертного облика. Если удастся превратить Раса в смертного, убейте его и заберите человеческую голову Раса Снегошепота. Отнесите голову мировому судье Мардуку."},
[5515]={"Мешок ужасов Крастинова","Найдите в Некроситете Джандис Баров и уничтожьте ее. Заберите мешок ужасов Крастинова. Отнесите мешок Еве Саркофф."},
[5522]={"Леонид Барталомей","Принесите охлажденные яйца Леониду Бартоломею в Восточные Чумные земли."},
[5526]={"Осколки сквернита","Отыщите Сквернит в Забытом Городе и подберите его осколок. Есть шанс, что вам удастся его добыть, только убив Алззина Вертоградаря. Крепко заприте осколок в реликварии Чистоты, затем верните его Рабину Сатурне в Ночную Гавань в Лунной поляне."},
[5527]={"Реликварий Чистоты","Отправляйтесь в Силитус и найдите реликварий Чистоты в руинах деревни Южного Ветра. Если вам удастся его найти, возвращайтесь к Рабину Сатурне в Ночную Гавань в Лунной поляне."},
[5529]={"Зачумленные детеныши дракона","Убейте 20 зачумленных детенышей дракона, затем возвращайтесь к Бетине Биггльцинк в Часовню Последней Надежды."},
[5531]={"Бетина Биггльцинк","Принесите охлажденные яйца Бетине Биггльцинк."},
[5533]={"Некроситет","Поговорите с алхимиком Арбингтоном с вершины Холодной Скалы, что в Западных Чумных землях."},
[5722]={"В поисках потерянного ранца","Обыщите Огненную пропасть в поисках тела Маура Зловещего Тотема и найдите все необычные предметы."},
[5723]={"Испытание силы врага","Найдите в Оргриммаре Огненную пропасть, убейте 8 троггов и 8 шаманов Огненной пропасти и возвращайтесь к Рахауро в Громовой Утес."},
[5724]={"Возвращение потерянной сумки","Отнесите сумку Маура Зловещего Тотема Рахауро в Громовой Утес."},
[5725]={"Силы разрушения...","Принесите книги \"Заклинания Тьмы\" и \"Заклятия Пустоты\" Вариматрасу в Подгород."},
[5726]={"Тайные враги","Принесите лейтенантский знак отличия Траллу в Оргриммар."},
[5727]={"Тайные враги","Отнесите лейтенантский знак отличия Нииру Огненному Клинку. Убедите его в своей преданности Пылающему Клинку. Вернитесь к Траллу в Оргриммар."},
[5728]={"Тайные враги","Убейте Баззалана и Жергоша Призывателя Духов и вернитесь в Оргриммар к Траллу."},
[5761]={"Убить тварь","Спуститесь в Огненную пропасть, убейте Тарагамана Ненасытного и принесите его сердце Нииру Огненному Клинку в Оргриммаре."},
[5848]={"Символ семейной любви","Отправляйтесь в Статхольм в северную часть Чумных земель. Найдите в Бастионе Алого ордена картину \"Символ семейной любви\", спрятанную за другой, изображающей две луны нашего мира. Отнесите картину Тириону Фордрингу."},
[6022]={"Преднамеренное убийство","Отправляйтесь на восток в Перекресток Корина и убейте несколько населяющих его созданий Плети. Соберите 7 кусков живой гнили менее, чем за 10 минут. С помощью ступки и пестика превратите живую гниль в сгущенную гниль."},
[6042]={"Мелочи нежизни","Истребите 20 пагубных нетопырей и 10 чудовищных чумных нетопырей. После возвращайтесь к Натаносу Гнилостеню."},
[6133]={"Охота на cледопытов","Отправляйтесь в северные пределы Восточных Чумных земель и заполучите реестр Кель'Таласа. Документ находится где-то в Сторожке Кель'Литиен. Также убейте 8 следопытов, 8 разведчиц дорог и 8 лесников."},
[6135]={"Проклятый Тенекрыл","Выследите Тенекрыла и убейте его. Принесите полоску меха Тенекрыла Натаносу Гнилостеню. Говорят, Тенекрыл рыщет в землях к северу от имения Марриса."},
[6136]={"Огромный червь","Найдите и уничтожьте Мерзкослиза в северных пустошах Восточных Чумных земель. Возвращайтесь к Натаносу Гнилостеню по выполнению задания."},
[6163]={"Рамштейн","Отправляйтесь в Стратхольм и убейте Рамштайна Ненасытного. Принесите его голову Натаносу в качестве сувенира."},
[6402]={"Встреча в Штормграде","Отправьтесь в Штормград и подойдите к городским воротам. Поговорите с оруженосцем Роу, чтобы он сообщил маршалу Виндзору о вашем прибытии."},
[6403]={"Великий Маскарад","Сопроводите Реджинальда Виндзора через весь Штормград. Защитите его!"},
[6501]={"Око дракона","Найдите существа, способные вернуть силу фрагменту амулета Ока дракона. Все, что об этих существах известно – это то, что они есть."},
[6502]={"Амулет Пламени дракона","Добудьте кровь могучего черного дракона генерала Драккисата, которого можно найти сидящим на троне в залах Вознесения в Пике Черной горы."},
[6521]={"Нечестивый союз","Принести голову посла Малкина Вариматрасу в Подгород."},
[6522]={"Нечестивый союз","Отнесите маленький свиток Вариматрасу в Подгород."},
[6561]={"Жестокость Черных Глубин","Принесите голову Повелителя сумрака Келриса Башане Руническому Тотему в Громовой Утес."},
[6562]={"Угроза из Глубин","Поговорите с Дже'неу Санкри в Ясеневом лесу."},
[6563]={"Сущность Аку'май","Принесите 20 сапфиров Аку'май Дже'неу Санкри в Ясеневый лес."},
[6564]={"Верность Древним богам","Принесите отсыревшую записку Дже'неу Санкри в Ясеневый лес."},
[6565]={"Верность Древним богам","Убейте Лоргуса Джетта в Непроглядной Пучине и вернитесь к Дже'неу Санкри в Ясеневый лес."},
[6566]={"Что принес ветер","Выслушайте Тралла."},
[6567]={"Защитник Орды","Найдите Рексара. Вождь сказал, что он бродит в Пустошах, по дороге, что ведет из Когтичтых гор в Фералас."},
[6568]={"Завет Рексара","Доставьте письмо Рексара Миранде Колдунье в Западные Чумные земли."},
[6569]={"Иллюзии Ока","Отправляйтесь на пик Черной горы и добудьте 20 глаз черных драконидов. По выполнении задания вернитесь к Миранде Колдунье."},
[6570]={"Огнебор","Отправляйтесь в Драконьи топи в Пылевых топях и найдите Логово Огнебора. Оказавшись внутри, наденьте амулет Обмана драконов и поговорите с Огнебором."},
[6582]={"Черепа: Провидец","Найдите в Зимних Ключах избранного бойца синих дракона по имени Провидец и убейте его. С его черепом вернитесь к Огнебору."},
[6583]={"Черепа: Сомнус","Убейте вожака зеленых драконов Сомнуса и вернитесь с его черепом к Огнебору."},
[6584]={"Черепа: Хроналис","Убейте Хроналиса, охраняющего Пещеры Времени в Пустыне Танарис и вернитесь с его черепом к Огнебору."},
[6585]={"Черепа: Акстроз","Отправьтесь в Грим Батол и убейте Акстроза, избранного бойца красных драконов. Принесите его череп Огнебору."},
[6601]={"Вознесение","Казалось бы, загадка разгадана. Вы знаете, что амулет Обмана Драконов, который сделала для вас Миранда Колдунья, не будет работать на пике Черной горы. Найдите Рокаро и расскажите о ваших затруднениях. Покажите ему амулет Угасающего Пламени Дракона. Будем надеяться, он знает что делать."},
[6602]={"Кровь могучего черного дракона","Отправляйтесь к пику Черной горы и убейте генерала Драккисата. Соберите его кровь и вернитесь к Рокаро."},
[6626]={"Воинство зла","Убейте 8 боевых стражей и 8 терноплетов из племени Иглошкурых, а также 8 сектанток из племени Мертвой Головы и возвращайтесь к Мириам Лунной Певице на Курганы Иглошкурых."},
[6627]={"Испытание знаний","Дайте верный ответ на вопрос Брауга Тусклого Духа и поговорите с ним еще раз. Брауга можно в любое время найти в Когтистых горах."},
[6628]={"Испытание знаний","Дайте верный ответ на вопрос Парквела Финталласа и поговорите с ним еще раз. Парквелла можно в любое время найти в Подгороде."},
