[6804]={"Отравленная вода","Исцелите отравленных элементалей в Восточных Чумных землях с помощью аспекта Нептулона. Принесите 12 браслетов колыхающихся волноплесков и аспект Нептулона герцогу Гидраксису в Азшару."},
[6805]={"Буря в пустыне","Убейте 15 пылевихрей и 15 пустынных грохотунов, а затем возвращайтесь к герцогу Гидраксису в Азшару."},
[6821]={"Око Углеглаза","Принесите глаз Созерцателя Углей герцогу Гидраксису в Азшару."},
[6822]={"Огненные Недра","Убейте 1 Повелителя огня, 1 лавового гиганта, 1 древнюю гончую бездны и 1 лавового волноплеска и возвращайтесь к герцогу Гидраксису в Азшару."},
[6823]={"Агент Гидраксиса","Добейтесь уважительного отношеия к себе со стороны Гидраксианских Повелителей Вод, затем отправляйтесь к герцогу Гидраксису в Азшару."},
[6824]={"Руки врага","Принесите руки Люцифрона, Сульфурона, Гееннаса и Шаззраха герцогу Гидраксису в Азшару."},
[6921]={"Среди руин","Принесите глубинный сердечник Дже'неу Санкри в форт Зорам'гар в Ясеневый лес."},
[6922]={"Барон Акванис","Принесите странную водяную сферу Дже'неу Санкри в форт Зорам'гар в Ясеневом лесу."},
[6981]={"Светящийся осколок","Отправляйтесь в Кабестан и найдите там кого-нибудь, кто сможет вам рассказать об этом светящемся осколке. Затем отнесите осколок туда, куда вас направят."},
[7028]={"Хрустальные орнаменты","Соберите 25 терадрических хрустальных орнаментов для Ивы из Пустошей."},
[7029]={"Порча Злоязыкого","Наполните церуленовый фиал с покрытием в оранжевом пруду Мародона. Полейте гнусь-лозу из полного церуленового фиала, выгнав ядовитую лозу. Исцелите 8 растений, убивая ядовитые лозы, и вернитесь к Варку Боевому Шраму в Деревню Ночных Охотников."},
[7041]={"Порча Злоязыкого","Наполните церуленовый фиал с покрытием в оранжевом пруду Мародона. Полейте гнусь-лозу из полного церуленового фиала, выгнав ядовитую лозу. Исцелите 8 растений, убивая ядовитые лозы, и вернитесь к Талендрии из Высоты Найджела."},
[7044]={"Легенды Мародона","Добудьте две части скипетра Келебраса – жезл Келебраса и бриллиант Келебраса. Найдите способ поговорить с Келебрасом."},
[7046]={"Скипетр Келебраса","Помогите Селебрасу Искупленному воссоздать скипетр Селебраса. По завершении ритуала снова обратитесь к нему."},
[7064]={"Яблочко от яблоньки...","Убейте принцессу Терадрас и вернитесь к Селендре неподалеку от Деревни Ночных Охотников в Пустошах."},
[7065]={"Яблочко от яблоньки...","Убейте принцессу Терадрас и вернитесь к хранителю Марандису на Высоту Найджела в Пустоши."},
[7066]={"Семя Жизни","Найдите в Лунной поляне Ремулоса и отдайте ему Семя Жизни."},
[7067]={"Инструкции кентавра-парии","Прочтите инструкции кентавра-парии, добудьте из Мародона амулет Соединения и верните его кентавру-парии из южной части Пустошей."},
[7068]={"Фрагменты осколка сумрака","Соберите в Мародоне 10 фрагментов осколков сумрака и отнесите их Утель'наю в Оргриммар."},
[7070]={"Фрагменты осколка сумрака","Соберите в Мародоне 10 фрагментов осколков сумрака и отнесите их верховному магу Тервошу в Терамор на побережье Пылевых топей."},
[7201]={"Последняя Стихия","Отправляйтесь в Глубины Черной горы и добудьте 10 мер сущности Стихий. Стоит начать поиски с големов и их создателей. Вивиан Лаграв также бормотала что-то про элементалей."},
[7441]={"Пузиллин и старейший Аж'Тордин","Отправляйтесь в Забытый Город и отыщите беса Пузиллина. Любыми доступными средствами убедите Пузиллина отдать вам книгу заклинаний Аж'Тордина. Если добудете книгу, вернитесь к Аж'Тордину в павильон Лорисс в Фераласе."},
[7461]={"Древнее безумие","Перебейте стражей, которые охраняют 5 столпов, снабжающих энергией Тюрьму Бессмер'тера. После того как столпы угаснут, силовое поле, удерживающее Бессмер'тера, рассеется. Войдите в Тюрьму Бессмер'тера и уничтожьте злого демона, который находится внутри. И, наконец, сразитесь с принцем Тортелдрином в Читальне. Если задание будет выполнено успешно, вернитесь во двор, к прародительнице Шен'дралар."},
[7462]={"Сокровище Шен'дралар","Вернитесь в Читальню и найдите сокровище Шен'дралар. Получите свою награду!"},
[7463]={"Магический напиток","Ступайте в Квартал Криводревов Забытого Города и убейте элементаля воды Гидротварь. Вернитесь в Читальню к сказителю Лидросу и принесите ему сущность Гидротвари."},
[7481]={"Эльфийские легенды","Отыщите в Забытом Городе Тельмия Сновидца. Вернитесь в лагерь Мохаче к ведуну Королуску и сообщите ему все, что вам удалось узнать."},
[7482]={"Эльфийские легенды","Отыщите в Забытом Городе Тельмия Сновидца. Вернитесь в крепость Оперенной Луны к исследовательнице Рунический Шип и сообщите ей все, что вам удалось узнать."},
[7486]={"Награда для героя","Заберите свою награду из сундука Гидраксиса."},
[7488]={"Сеть Лефтендрис","Принесите сеть Лефтендрис Латроникусу Лунному Копью в Крепость Оперенной Луны в Фераласе."},
[7489]={"Сеть Лефтендрис","Принесите сеть Лефтендрис Тало Терновому Копыту в Лагере Мохаче в Фераласе."},
[7490]={"Победа Орды","Отнесите голову Ониксии Траллу в Оргриммар."},
[7491]={"На виду у всех","Найдите властителя Рунтака в Аллее Силы."},
[7493]={"Все еще только начинается!"},
