[6823]={"히드락시스의 하수인","히드락시스 물의 군주들로부터 우호적인 평판을 얻은 후 아즈샤라에 있는 군주 히드락시스와 대화해야 합니다."},
[6824]={"적의 손","아즈샤라에 있는 군주 히드락시스에게 루시프론, 설퍼론, 게헨나스, 샤즈라의 손을 가져가야 합니다."},
[6921]={"폐허 사이로","잿빛 골짜기의 조람가르 전초기지에 있는 제네우 생크리에게 심연의 핵을 가져가야 합니다."},
[6922]={"군주 아쿠아니스","잿빛 골짜기의 조람가르 전초기지에 있는 제네우 생크리에게 이상한 물구슬을 가져가야 합니다."},
[6981]={"빛나는 조각","톱니항으로 가서 빛나는 조각에 대해 자세히 얘기해 줄 수 있는 이를 찾으십시오. 그에게 지시를 받아, 빛나는 조각을 전달해야 합니다."},
[7028]={"뒤틀린 악마","트라드릭 수정 조각상 25개를 모아서 잊혀진 땅에 있는 윌로우에게 가져가야 합니다."},
[7029]={"바일텅의 타락","마라우돈에 있는 주황색 수정 웅덩이에서 빈 감청석 약병을 채워야 합니다. 오염된 녹시온의 후예가 나타나게 하려면 바일줄기 덩굴나무 위에 감청색 약병에 담긴 액체를 부어야 합니다. 녹시온의 후예를 죽이는 방법으로 8개의 식물을 치료한 다음 그늘수렵 마을에 있는 바르크 배틀스카에게 돌아가야 합니다."},
[7041]={"바일텅의 타락","마라우돈에 있는 주황색 수정 웅덩이에서 빈 감청석 약병을 채워야 합니다. 오염된 녹시온의 후예가 나타나게 하려면 바일줄기 덩굴나무 위에 감청색 약병에 담긴 액체를 부어야 합니다. 녹시온의 후예를 죽이는 방법으로 8개의 식물을 치료한 다음 나이젤의 야영지에 있는 탈렌드리아에게 돌아가야 합니다."},
[7044]={"마라우돈의 전설","셀레브라스의 홀 조각인 셀레브리안 마법봉과 셀레브리안 다이아몬드를 찾아야 합니다. 셀레브라스와 대화를 나눌 방법을 찾아야 합니다."},
[7046]={"셀레브라스의 홀","회복된 셀레브라스가 셀레브라스의 홀을 만드는 동안 그를 도와야 합니다. 의식을 마친 후 그와 대화하십시오."},
[7064]={"대지와 씨앗의 오염","공주 테라드라스를 해치우고 잊혀진 땅의 그늘수렵 마을 근처에 있는 셀렌드라에게 돌아가야 합니다."},
[7065]={"대지와 씨앗의 오염","공주 테라드라스를 해치우고 잊혀진 땅의 나이젤의 야영지에 있는 수호자 마란디스를 찾아가야 합니다."},
[7066]={"생명의 씨앗","달의 숲에 있는 수호자 레물로스를 찾아 생명의 씨앗을 전해 주어야 합니다."},
[7067]={"추방자의 지시서","추방자의 지시서를 읽은 다음 마라우돈에서 결속의 아뮬렛을 획득해서 잊혀진 땅 남부에 있는 켄타우로스 추방자에게 가져가야 합니다."},
[7068]={"음영석 조각","마라우돈에서 음영석 조각 10개를 모아서 오그리마에 있는 우텔나이에게 가져가야 합니다."},
[7070]={"음영석 조각","마라우돈에서 음영석 조각 10개를 모아서 먼지진흙 습지대의 해안에 위치한 테라모어에 있는 대마법사 테르보쉬에게 가져가야 합니다."},
[7201]={"마지막 원소","검은바위 나락으로 가서 원소의 정수 10개를 회수해야 합니다. 먼저 골렘이나 골렘 제조자부터 찾아보십시오. 비비안 라그레이브가 정령에 대해 중얼거리듯 얘기한 것도 기억이 납니다."},
[7441]={"푸실린과 노쇠한 아즈토르딘","혈투의 전장으로 가서 푸실린이라는 임프를 찾으십시오. 어떤 수단을 써서라도 아즈토리딘의 마법서를 돌려받아야 합니다. 마법서를 회수하면 페랄라스의 라리스 정자에 있는 아즈토리딘에게 돌아가야 합니다."},
[7461]={"내면의 광기","이몰타르의 감옥에 힘을 공급하는 다섯 개의 수정탑을 둘러싼 수호자들을 처치해야 합니다. 수정탑의 마력이 약해지면 이몰타르를 둘러싼 마법진도 분산될 것입니다. 이몰타르의 감옥에 들어가 그 심장부에 서 있는 사악한 이몰타르를 처치하고, 마지막으로 도서관에 있는 토르텔드린 왕자와 맞서 싸우십시오. 이 임무를 완수하면 안마당에 있는 셴드랄라 고대인에게 돌아가야 합니다."},
[7462]={"셴드랄라의 보물","도서관으로 되돌아가 셴드랄라의 보물을 찾아야 합니다. 임무 완수에 대한 보상을 받으십시오!"},
[7463]={"신비의 원기 회복 주문","혈투의 전장에 있는 굽이나무 지구로 가서 물의 정령인 히드로스폰을 처치하십시오. 히드로스폰의 정수를 가지고 도서관에 있는 현자 리드로스에게 돌아가야 합니다."},
[7481]={"엘프의 전설","혈투의 전장을 뒤져 텔미우스 드림시커를 찾으십시오. 찾을 수 있는 정보는 모두 찾아 모자케 야영지에 있는 현자 코로루스크에게 돌아가야 합니다."},
[7482]={"엘프의 전설","혈투의 전장을 뒤져 텔미우스 드림시커를 찾으십시오. 찾을 수 있는 정보는 모두 찾아 페더문 요새에 있는 학자 룬쏜에게 돌아가야 합니다."},
