[1159]={"知识试炼","找到幽暗城的帕科瓦·芬塔拉斯。"},
[1160]={"知识试炼","找到《亡灵的起源》，把它交给幽暗城的帕科瓦·芬塔拉斯。"},
[1198]={"寻找塞尔瑞德","到黑色深渊去找到银月守卫塞尔瑞德。"},
[1199]={"暮光之锤的末日","收集10个暮光坠饰，把它们交给达纳苏斯的银月守卫玛纳杜斯。"},
[1200]={"黑暗深渊中的恶魔","把梦游者克尔里斯的头颅交给达纳苏斯的哨兵塞尔高姆。"},
[1221]={"蓝叶薯","找到一个开孔的箱子。 找到一根地鼠指挥棒。 找到并阅读《地鼠指挥手册》。 在剃刀沼泽里用开孔的箱子召唤一只地鼠，然后用指挥棒驱使它去搜寻蓝叶薯。 把地鼠指挥棒、开孔的箱子和6块蓝叶薯交给棘齿城的麦伯克·米希瑞克斯。"},
[1275]={"研究堕落","奥伯丁的戈沙拉·夜语需要8块堕落者的脑干。"},
[1360]={"失而复得","到奥达曼的北部大厅去找到克罗姆·粗臂的箱子，从里面拿出他的宝贵财产，然后回到铁炉堡把东西交给他。"},
[1394]={"通过试炼","和千针石林的多恩·平原行者谈一谈。"},
[1424]={"泪水之池","斯通纳德的费泽鲁尔要求你收集10件阿塔莱神器。"},
[1429]={"阿塔莱流放者","将一捆阿塔莱神器交给辛特兰的阿塔莱流放者。"},
[1444]={"向费泽鲁尔复命","向斯通纳德的费泽鲁尔回报。"},
[1445]={"阿塔哈卡神庙","收集20个哈卡神像，把它们带给斯通纳德的费泽鲁尔。"},
[1446]={"预言者迦玛兰","辛特兰的阿塔莱流放者要你给他带回迦玛兰的头。"},
[1448]={"调查神庙","暴风城的布罗哈恩·铁桶要求你去找到阿塔哈卡神庙。"},
[1449]={"去辛特兰的旅程","找到辛特兰的弗斯塔德·蛮锤。"},
[1450]={"狮鹫管理员","与辛特兰的鹰巢山狮鹫饲养场里的狮鹫管理员沙拉克·鹰斧谈一谈。"},
[1451]={"拉普索迪·铁铲","去辛特兰找到拉普索迪·铁铲。"},
[1452]={"拉普索迪的卡利姆多鸡尾酒","辛特兰的拉普索迪·铁铲要求你带给他3块大鹏的砂囊、3块格罗多克猩猩的肝脏和3块铁鬃熊的肝脏。"},
[1469]={"拉普索迪的故事","将阿塔莱石板碎片交给暴风城的布罗哈恩·铁桶。"},
[1475]={"进入阿塔哈卡神庙","为暴风城的布罗哈恩·铁桶收集10块阿塔莱石板。"},
[1486]={"变异皮革","哀嚎洞穴的纳尔帕克想要20张变异皮革。"},
[1487]={"清除变异者","哀嚎洞穴的厄布鲁要求你杀掉7只变异破坏者、7只剧毒飞蛇、7只变异蹒跚者和7只变异尖牙风蛇。"},
[1489]={"哈缪尔·符文图腾","和哈缪尔·符文图腾谈一谈。"},
[1490]={"纳拉·蛮鬃","和纳拉·蛮鬃谈一谈。"},
[1491]={"智慧饮料","收集6份哀嚎香精，把它们交给棘齿城的麦伯克·米希瑞克斯。"},
[1651]={"勇气之书","在迪菲亚兄弟会进攻时保护达芙妮·斯迪威尔的安全。 如果你想成功的话，你和达芙妮都不能死在他们的剑下。"},
[1652]={"勇气之书","与暴风城的达索瑞恩·拉尔谈一谈。"},
[1653]={"正义试炼","去和铁炉堡的乔丹·斯迪威尔谈一谈。"},
[1654]={"正义试炼","按照乔丹的武器材料单上的说明去寻找一些白石橡木、精炼矿石、乔丹的铁锤和一块科尔宝石，然后回到铁炉堡去见乔丹·斯迪威尔。"},
[1740]={"索兰鲁克宝珠","找到3块索兰鲁克宝珠的碎片和1块索兰鲁克宝珠的大碎片，把它们交给贫瘠之地的杜安·卡汉。"},
[1806]={"正义试炼","等待乔丹·斯迪威尔为你铸造武器。"},
[1956]={"奥达曼的能量源","找到一个黑曜石能量源，将其交给尘泥沼泽的塔贝萨。"},
[2040]={"地底突袭","从死亡矿井中带回小型高能发动机，将其带给暴风城矮人区中的沉默的舒尼。"},
[2198]={"破碎的项链","找到破碎的项链的来源，从而了解其潜在的价值。"},
[2199]={"昂贵的知识","给铁炉堡的塔瓦斯德·基瑟尔带去五块银锭。"},
[2200]={"回到奥达曼","去奥达曼寻找塔瓦斯的魔法项链，被杀的圣骑士是最后一个拿着它的人。"},
[2201]={"寻找宝石","在奥达曼寻找红宝石、蓝宝石和黄宝石的下落。找到它们之后，通过塔瓦斯德给你的占卜之瓶和他进行联系。"},
[2202]={"奥达曼的蘑菇","收集12颗紫色蘑菇，把它们交给卡加斯的加卡尔。"},
[2204]={"修复项链","从奥达曼最强大的石人身上获得能量源，然后将其交给铁炉堡的塔瓦斯德。"},
[2240]={"密室","阅读巴尔洛戈的日记，探索密室，然后向铁炉堡的勘察员塔伯斯·雷矛汇报。"},
[2258]={"荒芜之地的试剂","前往荒芜之地取回加卡尔需要的试剂，然后回到卡加斯把试剂交给他。"},
[2278]={"白金圆盘","和石头守护者交谈，从他那里了解更多古代的知识。一旦你了解到了所有的内容之后就激活诺甘农圆盘。"},
[2280]={"白金圆盘","把迷你版的诺甘农圆盘带到雷霆崖的贤者那里。"},
[2283]={"搜寻项链","在奥达曼挖掘场中寻找一条珍贵的项链，然后将其交给奥格瑞玛的德兰·杜佛斯。项链有可能已经损坏。"},
[2284]={"搜寻项链，再来一次","在奥达曼里找寻宝石的线索。"},
[2318]={"翻译日记","在荒芜之地的卡加斯哨所里寻找一个可以帮你翻译圣骑士日记的人。"},
[2338]={"翻译日记","将项链借给加卡尔。作为交换，他将帮你翻译日记。"},
[2339]={"寻找宝贝","从奥达曼找回项链上的所有三块宝石和能量源，然后把它们交给卡加斯的加卡尔。 红宝石被藏在暗影矮人层层设防的地区。 黄宝石藏在石腭怪活动地区的一个瓮中。 蓝宝石在格瑞姆洛克手中，他是石腭怪的领袖。 能量源可能在奥达曼的某个最强生物的手中。"},
[2342]={"寻找宝物","从奥达曼南部大厅的箱子中找到加勒特的家族宝藏，然后把它交给幽暗城的帕特里克·加瑞特。"},
[2398]={"失踪的矮人","在奥达曼找到巴尔洛戈。"},
[2418]={"能量石","给荒芜之地的里格弗兹带去8块德提亚姆能量石和8块安纳洛姆能量石。"},
[2500]={"荒芜之地的材料","从荒芜之地拿到加克所需的材料，然后回到塞尔萨玛去见他。"},
[2768]={"探水棒","把探水棒交给加基森的首席工程师沙克斯·比格维兹。"},
[2770]={"加兹瑞拉","把加兹瑞拉的鳞片交给闪光平原的维兹尔·铜栓。"},
[2841]={"设备之战","从诺莫瑞根拿到钻探设备蓝图和麦克尼尔的保险箱密码，把它们交给奥格瑞玛的诺格。"},
[2842]={"主工程师斯库提","和藏宝海湾的斯库提谈一谈。"},
[2843]={"出发！诺莫瑞根！","等斯库提调整好地精传送器。"},
[2846]={"深渊皇冠","将深渊皇冠交给尘泥沼泽的塔贝萨。"},
[2865]={"圣甲虫的壳","给加基森的特兰雷克带去5个完整的圣甲虫壳。"},
[2904]={"一团混乱","将克努比护送到出口，然后向藏宝海湾的斯库提汇报。"},
[2922]={"拯救尖端机器人！","将尖端机器人的存储器核心交给铁炉堡的工匠大师欧沃斯巴克。"},
[2924]={"基础模组","收集12个基础模组，把它们交给铁炉堡的科劳莫特·钢尺。"},
[2926]={"诺恩","用空铅瓶对着辐射入侵者或者辐射抢劫者，从它们身上收集放射尘。瓶子装满之后，把它交给卡拉诺斯的奥齐·电环。"},
[2928]={"陀螺式挖掘机","收集24副机械内胆，把它们交给暴风城的舒尼。"},
[2929]={"大叛徒","到诺莫瑞根去杀掉麦克尼尔·瑟玛普拉格。完成任务之后向大工匠梅卡托克报告。"},
[2930]={"抢救数据","将彩色穿孔卡片交给铁炉堡的大机械师卡斯派普。"},
[2933]={"毒液瓶","将毒药瓶交给塔伦米尔的某个药剂师。"},
[2934]={"完好无损的毒囊","将完好无损的毒囊交给塔伦米尔的药剂师林度恩。"},
[2935]={"请教加德林大师","与森金村的加德林大师谈一谈。"},
[2936]={"蜘蛛之神","阅读塞卡石板，了解枯木巨魔的蜘蛛之神的名字，然后回到加德林大师那里。"},
[2945]={"脏兮兮的戒指","想方法把脏兮兮的戒指弄干净。"},
[2947]={"戒指归来","你要么自己留着这枚戒指，要么就按照戒指内侧刻着的名字找到它的主人。"},
[2948]={"侏儒的手艺","将闪亮的金戒指、1块银锭、1块绿玛瑙和30个银币交给铁炉堡的塔瓦斯德·基瑟尔。"},
[2949]={"戒指归来","你要么自己留着这枚戒指，要么就按照戒指内侧刻着的名字找到它的主人。"},
[2950]={"诺格的手艺","将闪亮的金戒指、1块银锭、1块绿玛瑙和30个银币交给奥格瑞玛的诺格。"},
[2951]={"超级清洁器5200型！","将脏兮兮的东西放入超级清洁器5200型，记得要用三枚银币来启动机器。"},
[2962]={"更多的辐射尘！","到诺莫瑞根去收集高强度辐射尘。要多加小心，这种辐射尘非常不稳定，很快就会分解。 奥齐要求你把沉重的铅瓶也交给他。"},
[2988]={"枯木巨魔的牢笼","检查两个枯木巨魔村落里的笼子，然后向狮鹫管理员沙拉克·鹰斧回复。"},
[2989]={"祖尔祭坛","检查祖尔祭坛的顶部，然后向狮鹫管理员沙拉克·鹰斧报告。"},
[2990]={"萨迪斯·格希德","将沙普比克的羽毛交给诅咒之地的萨迪斯·格希德。"},
[2991]={"耐克鲁姆的徽章","将耐克鲁姆的徽章交给诅咒之地的萨迪斯·格希德。"},
[3042]={"巨魔调和剂","收集20瓶巨魔调和剂，把它们交给加基森的特伦顿·轻锤。"},
[3341]={"寒冰之王","安德鲁·布隆奈尔要你杀了寒冰之王亚门纳尔并将其头骨带回来。"},
[3373]={"伊兰尼库斯精华","把伊兰尼库斯精华放在精华之泉里，精华之泉就在沉没的神庙中，伊兰尼库斯的巢穴里。"},
[3444]={"石环","到棘齿城去，从玛尔冯·瑞文斯克的车间里取回石环。"},
[3446]={"深入神庙","在悲伤沼泽沉没的神庙中找到哈卡祭坛。"},
[3447]={"雕像群的秘密","到沉没的神庙去，揭开雕像群中隐藏的秘密。"},
[3520]={"尖啸者的灵魂","在菲拉斯捕获3个尖啸者的灵魂，然后回到热砂港的叶基亚那里去。"},
[3523]={"剃刀高地的亡灵天灾","如果你同意帮助奔尼斯特拉兹，就再跟他谈谈，并将誓言石还给他。"},
[3525]={"封印神像","保护奔尼斯特拉兹来到剃刀高地的野猪人神像处。 当他在进行仪式封印神像时保护他。"},
[3527]={"摩沙鲁的预言","将第一块和第二块摩沙鲁石板交给塔纳利斯的叶基亚。"},
[3528]={"神灵哈卡","将装满的哈卡之卵交给塔纳利斯的叶基亚。"},
[3636]={"与圣光同在","大主教本尼迪塔斯要你去杀死剃刀高地的寒冰之王亚门纳尔。"},
[3701]={"索瑞森废墟","到燃烧平原的索瑞森废墟中去，从索瑞森遗物上搜集信息。当你收集到足够的信息之后，就回到皇家历史学家阿克瑟努斯那里。"},
[3702]={"索瑞森废墟","听皇家历史学家阿克瑟努斯讲述索瑞森的历史。"},
[3765]={"遥远的旅途","到奥伯丁的戈沙拉·夜语那儿去。"},
[3801]={"黑铁的遗产","如果你想要得到进入这座城市主城区的钥匙，就去和弗兰克罗恩·铸铁谈一谈。"},
[3802]={"黑铁的遗产","杀掉弗诺斯·达克维尔并拿回战锤铁胆。把铁胆之锤拿到索瑞森神殿去，将其放在弗兰克罗恩·铸铁的雕像上。"},
[3906]={"不和谐的烈焰","到黑石山脉的采石场去干掉征服者派隆，然后向桑德哈特回报。"},
[3907]={"不和谐的火焰","进入黑石深渊并找到伊森迪奥斯。杀掉它，然后把你找到的信息汇报给桑德哈特。"},
[3981]={"指挥官哥沙克","在黑石深渊里找到指挥官哥沙克。 在那幅草图上画着的是一个铁栏后面的兽人，也许你应该到某个类似监狱的地方去找找看。"},
[3982]={"出了什么事？","保护哥沙克。"},
[4001]={"出了什么事？","与卡兰·巨锤谈一谈，收集关于绑架公主铁炉堡公主茉艾拉·铜须这一事件的情报。将情报反馈给奥格瑞玛城里的萨尔。 哥沙克提到过卡兰被关在附近的某个牢房中。"},
[4002]={"东部王国","如果你准备好要接受萨尔所安排的任务，就去找他谈一谈。"},
[4003]={"拯救公主","杀掉达格兰·索瑞森大帝，然后将铁炉堡公主茉艾拉·铜须从他的邪恶诅咒中拯救出来。"},
[4022]={"烈焰精华","向塞勒斯·萨雷芬图斯展示你从卡拉然·温布雷那里得到的黑龙皮。"},
[4024]={"烈焰精华","到黑石深渊去杀掉贝尔加。 你只知道这个巨型怪物住在黑石深渊的最深处。记住你要使用特殊的黑龙皮从贝尔加的尸体上采集烈焰精华。 将你采集到的烈焰精华交给塞勒斯·萨雷芬图斯。"},
[4061]={"机器的崛起","到燃烧平原去为塞朵拉·穆瓦丹尼收集10块断裂的元素碎片。 塞朵拉曾经说过，那里的机械傀儡和元素生物是这种碎片的主要来源。"},
[4062]={"机器的崛起","将元素碎片样本交给鲁特维尔·沃拉图斯。 塞朵拉说鲁特维尔就在东边的一处营地里。"},
[4063]={"机器的崛起","找到并杀掉傀儡统帅阿格曼奇，将他的头交给鲁特维尔。你还需要从守卫着阿格曼奇的狂怒傀儡和战斗傀儡身上收集10块完整的元素核心。"},
[4081]={"格杀勿论：黑铁矮人","到黑石深渊去消灭那些邪恶的侵略者！ 军官高图斯要你去杀死15个铁怒卫士、10个铁怒狱卒和5个铁怒步兵。完成任务之后回去向他复命。"},
[4082]={"格杀勿论：高阶黑铁军官","到黑石深渊去消灭那些邪恶的侵略者！ 高图斯军阀要你杀死10个铁怒医师,、10个铁怒士兵和10个铁怒军官。完成任务之后回去向他复命。"},
[4083]={"鬼魂之杯"},
[4121]={"押送囚徒","押送你的囚犯格拉克·洛克鲁布。穿过燃烧平原和黑石山脉，一直走到灼热峡谷。 雷克斯洛特曾经告诉过你，他会让他的人等在黑石山脉的另外一边准备接收格拉克。 另外，你还要把瑟银镣铐一并还给雷克斯洛特。"},
[4122]={"格拉克·洛克鲁布","到燃烧平原去找到格拉克·洛克鲁布。你回忆起雷克斯洛特曾经提起过，格拉克应该是在一座大型的黑石要塞中。 当你找到格拉克·洛克鲁布之后，用瑟银镣铐把他铐起来，然后将其带回灼热峡谷。雷克斯洛特会让他的部下等在那里接应你。"},
[4123]={"山脉之心","把山脉之心交给燃烧平原的麦克斯沃特·尤博格林。"},
[4126]={"霍尔雷·黑须","把遗失的雷酒秘方带给卡拉诺斯的拉格纳·雷酒。"},
[4132]={"行动：杀死安格弗将军","到黑石深渊去杀掉安格弗将军！当任务完成之后向军官高图斯复命。"},
[4134]={"遗失的雷酒秘方","把遗失的雷酒秘方交给卡加斯的薇薇安·拉格雷。"},
[4136]={"雷布里·斯库比格特","把雷布里的头颅交给燃烧平原的尤卡·斯库比格特。"},
[4141]={"穆尔金和拉瑞安","从安戈洛尔环形山的血瓣花猛击者和血瓣花掠夺者身上收集15个血瓣花，然后向穆尔金回复。"},
[4142]={"造访格雷甘","把血瓣花交给菲拉斯的格雷甘·山酒。"},
[4143]={"邪恶之雾","收集5份阿塔莱之雾的样本，然后向安戈洛环形山的穆尔金复命。"},
[4145]={"拉瑞安和穆尔金","为马绍尔营地里的拉瑞安杀掉5个血瓣花鞭笞者、5个血瓣花捕兽者、5个血瓣花掠夺者和5个血瓣花猛击者。"},
[4146]={"除草器的燃料","收集5份阿塔莱之雾的样本，然后将它们送到马绍尔营地的拉瑞安那里。"},
[4147]={"玛尔冯的车间","到棘齿城去，在玛尔冯·瑞文斯克的车间里找到他。"},
[4182]={"黑龙的威胁","杀掉15条黑色小龙、10条黑色龙人和1条黑色幼龙。当你完成任务之后就向赫林迪斯·河角回报。"},
[4183]={"真正的主人","把赫林迪斯·河角的信交给湖畔镇的所罗门镇长。"},
[4184]={"真正的主人","到暴风城去把所罗门的求援信交给伯瓦尔·弗塔根公爵。 伯瓦尔在暴风要塞里。"},
[4185]={"真正的主人","与女伯爵卡特拉娜·普瑞斯托谈话，然后再与伯瓦尔·弗塔根公爵谈话。"},
[4186]={"真正的主人","把伯瓦尔的命令交给湖畔镇的所罗门镇长。"},
[4201]={"爱情药水","将4份格罗姆之血、10块巨型银矿和装满水的娜玛拉之瓶交给黑石深渊的娜玛拉小姐。"},
[4223]={"真正的主人","和燃烧平原的麦克斯韦尔元帅谈一谈。"},
[4224]={"真正的主人","和狼狈不堪的约翰谈谈来了解温德索尔元帅的命运，然后回到麦克斯韦尔元帅那里。 你想起麦克斯韦尔元帅说过他在一个北面的洞穴那里。"},
[4241]={"温德索尔元帅","到西北部的黑石山脉去，在黑石深渊中找到温德索尔元帅的下落。 狼狈不堪的约翰曾告诉你说温德索尔被关进了一个监狱。"},
[4242]={"被遗弃的希望","把这个坏消息传达给麦克斯韦尔元帅。"},
[4262]={"征服者派隆","杀掉征服者派隆，然后向加琳达复命。 加琳达告诉过你，派隆守在采矿场中，也许你应该去那里找找。"},
[4263]={"伊森迪奥斯！","在黑石深渊里找到伊森迪奥斯，然后把他干掉！"},
[4264]={"弄皱的便笺","温德索尔元帅也许会对你手中的东西感兴趣。毕竟，希望还没有被完全扼杀。"},
[4282]={"一丝希望","找回温德索尔元帅遗失的情报。 温德索尔元帅确信那些情报在安格弗将军和傀儡统帅阿格曼奇的手里。"},
[4286]={"好东西","到黑石深渊去找到20个黑铁挎包。当你完成任务之后，回到奥拉留斯那里复命。你认为黑石深渊里的黑铁矮人应该会有这些黑铁挎包。"},
[4322]={"冲破牢笼！","帮助温德索尔元帅拿回他的装备并救出他的朋友。当你成功之后就回去向麦克斯韦尔元帅复命。"},
[4341]={"卡兰·巨锤","去黑石深渊找到卡兰·巨锤。 国王提到卡兰在那里负责看守囚犯——也许你应该在监狱附近寻找他。"},
[4342]={"卡兰的故事","听卡兰·巨锤说他的故事。"},
[4361]={"糟糕的消息","回到铁炉堡，把这个坏消息带给国王麦格尼·铜须。"},
[4362]={"王国的命运","回到黑石深渊，从达格兰·索瑞森大帝的魔掌中救出铁炉堡公主茉艾拉·铜须。"},
[4701]={"座狼之源","到黑石塔去摧毁那里的座狼源头。当你离开的时候，赫林迪斯喊出了一个名字：哈雷肯。这个词就是兽人语中“座狼”的意思。"},
[4724]={"座狼的首领","杀死血斧座狼的领袖，哈雷肯。"},
[4726]={"雏龙精华","将龙灵采集器900型和8份雏龙精华交给燃烧平原烈焰峰的丁奇·斯迪波尔。"},
[4729]={"基布雷尔的特殊宠物","到黑石塔去找到血斧座狼幼崽。使用笼子来捕捉这些凶猛的小野兽，然后把笼中的座狼幼崽交给基布雷尔。"},
[4734]={"冷冻龙蛋","在孵化间对着某颗龙蛋使用龙蛋冷冻器初号机。"},
[4735]={"收集龙蛋","将电动采集模块和8颗收集到的龙蛋交给燃烧平原烈焰峰的丁奇·斯迪波尔。"},
[4742]={"晋升印章","找到三块命令宝石：燃棘宝钻、尖石宝钻和血斧宝钻。把它们和原始晋升印章一起交给维埃兰。 可能携带者三块宝石的将军是：燃棘氏族的指挥官沃恩、尖石氏族的欧莫克大王，以及血斧氏族的维姆萨拉克。"},
[4764]={"末日扣环","将末日扣环交给燃烧平原的玛亚拉·布莱特文。"},
[4768]={"黑暗石板","将黑暗石板交给卡加斯的暗法师薇薇安·拉格雷。"},
[4771]={"黎明先锋","将黎明先锋放在通灵学院的观察室里。打败维克图斯，然后回到贝蒂娜·比格辛克那里去。"},
[4787]={"远古之卵","将远古之卵交给塔纳利斯的叶基亚。"},
[4788]={"最后的石板","将第五块和第六块摩沙鲁石板交给塔纳利斯的勘查员詹斯·铁靴。"},
[4808]={"菲诺克","把丁奇的信交给菲诺克。"},
[4809]={"冰风奇美拉角","将8支完整的冰风奇美拉角交给菲诺克。"},
[4810]={"返回丁奇身边","把菲诺克的包裹交给燃烧平原的丁奇·斯迪波尔。"},
[4862]={"蜘蛛卵","到黑石塔去为基布雷尔收集15枚尖塔蜘蛛卵。 听说那些蜘蛛周围有许多这样的卵。"},
[4866]={"蛛后的乳汁","你可以在黑石塔的中心地带找到烟网蛛后。与她战斗，让她在你体内注入毒汁。如果你有能力的话，就杀死她吧。当你中毒之后，回到狼狈不堪的约翰那儿，他会从你的身体里抽取这些“蛛后的乳汁”。"},
[4867]={"乌洛克","阅读瓦罗什的卷轴。将瓦罗什的蟑螂交给他。"},
[4903]={"高图斯的命令","杀死欧莫克大王、指挥官沃恩和维姆萨拉克。找到重要的黑石文件，然后向卡加斯的军官高图斯汇报。"},
[4907]={"丁奇·斯迪波尔","与丁奇·斯迪波尔谈一谈。"},
[4941]={"伊崔格的智慧","和奥格瑞玛的伊崔格谈一谈。讨论完毕后，咨询萨尔的意见。 你回忆起曾在萨尔的大厅中见过伊崔格。"},
[4974]={"为部落而战！","去黑石塔杀死大酋长雷德·黑手，带着他的头颅返回奥格瑞玛。"},
[4981]={"狡猾的比修","到黑石塔去查明比修的下落。"},
[4982]={"比修的装置","找到比修的装置并把它们还给她。你记得她说过她把装置藏在城市的最底层。"},
[4983]={"比修的侦察报告","把比修的侦查报告交给卡加斯的雷克斯洛特。"},
[5001]={"比修的装置","找到比修的装置并把它们还给她。祝你好运！"},
[5002]={"给麦克斯韦尔的消息","到燃烧平原去，把比修的情报交给麦克斯韦尔元帅。"},
[5047]={"皮普·急智，为您效劳！","与永望镇的玛雷弗斯·暗锤谈一谈。"},
[5065]={"失落的摩沙鲁石板","把第三块和第四块摩沙鲁石板交给塔纳利斯的勘查员詹斯·铁靴。"},
[5081]={"麦克斯韦尔的任务","到黑石塔去消灭指挥官沃恩、欧莫克大王和维姆萨拉克。完成任务之后回到麦克斯韦尔元帅处复命。"},
[5089]={"达基萨斯将军的命令","把达基萨斯将军的命令交给燃烧平原的麦克斯韦尔元帅。"},
[5102]={"达基萨斯将军之死","到黑石塔去杀掉达基萨斯将军，完成任务之后就回到麦克斯韦尔元帅那里复命。"},
[5122]={"信仰奖章"},
[5125]={"奥里克斯的清算"},
[5127]={"恶魔熔炉","到黑石塔去找到古拉鲁克。杀死他，然后用血污长矛刺入他的尸体。当他的灵魂被吸干后，这支矛就会成为穿魂长矛。 你还必须找到未铸造的符文覆饰胸甲。 将穿魂长矛和未铸造的符文覆饰胸甲都交给冬泉谷的罗拉克斯。"},
[5160]={"监护者","到冬泉谷去找到哈尔琳，把奥比的鳞片交给她。"},
[5212]={"血肉不会撒谎","从斯坦索姆找回20个瘟疫肉块，并把它们交给贝蒂娜·比格辛克。你觉得斯坦索姆中的生灵都不大可能长着肉……"},
[5213]={"活跃的探子","到斯坦索姆去探索那里的通灵塔。找到新的天灾军团档案，把它交给贝蒂娜·比格辛克。"},
[5214]={"了不起的艾兹拉·格里姆","找到艾兹拉·格里姆在斯坦索姆的烟草店，并从中找回一盒格里姆的优质香烟，把它交给烟鬼拉鲁恩。"},
[5243]={"神圣之屋","到北方的斯坦索姆去，寻找散落在城市中的补给箱，并收集5瓶斯坦索姆圣水。当你找到足够的圣水之后就回去向莱尼德·巴萨罗梅复命。"},
[5244]={"凯斯利尔废墟","与坠星村的加隆·石矛谈一谈。"},
[5245]={"凯斯利尔的怨灵","使用加隆的镐来寻找四块上层精灵遗物的碎片，把它们交给东瘟疫之地的奥萝拉。"},
[5246]={"历史的残片","在艾萨拉的辛玛洛神殿里找到神圣的上层精灵笔迹，并将它带给位于东瘟疫之地的北地哨塔附近的奥萝拉。"},
[5247]={"历史的残片","给东瘟疫之地的奥萝拉带去一块魔化瑟银锭、5块恢复水晶，以及一小瓶恐怖之水。"},
[5251]={"档案管理员","在斯坦索姆城中找到血色十字军的档案管理员加尔福特，杀掉他，然后烧毁血色十字军档案。"},
[5262]={"可怕的真相","将巴纳扎尔的头颅交给东瘟疫之地的尼古拉斯·瑟伦霍夫公爵。"},
[5263]={"超越","到斯坦索姆去杀掉瑞文戴尔男爵，把他的头颅交给尼古拉斯·瑟伦霍夫公爵。"},
[5281]={"永不安息的灵魂","找到埃根。你只知道他在斯坦索姆附近。"},
[5282]={"永不安息的灵魂","对斯坦索姆城中的鬼魂使用埃根的冲击器。当那些永不安息的灵魂挣脱他们的外壳时，再次使用埃根的冲击器——他们就可以获得自由了！ 解放15个永不安息的灵魂，然后回到埃根那里去。"},
[5341]={"巴罗夫家族的宝藏","到通灵学院中去取得巴罗夫家族的宝藏。这份宝藏包括四份地契：凯尔达隆地契、布瑞尔地契、塔伦米尔地契，还有南海镇地契。完成任务之后就回到阿莱克斯·巴罗夫那儿去。"},
[5343]={"巴罗夫家族的宝藏","到通灵学院中去取得巴罗夫家族的宝藏。这份宝藏包括四份地契：凯尔达隆地契、布瑞尔地契、塔伦米尔地契，还有南海镇地契。完成任务之后就回到维尔顿·巴罗夫那儿去。"},
[5382]={"瑟尔林·卡斯迪诺夫教授","在通灵学院中找到瑟尔林·卡斯迪诺夫教授。杀死他，并烧毁艾瓦·萨克霍夫和卢森·萨克霍夫的遗体。任务完成后就回到艾瓦·萨克霍夫那儿。"},
[5384]={"传令官基尔图诺斯","带着无辜者之血回到通灵学院，将它放在门廊的火盆下面，基尔图诺斯会前来吞噬你的灵魂。 勇敢地战斗吧，不要退缩！杀死基尔图诺斯，然后回到艾瓦·萨克霍夫那儿。"},
[5461]={"莱斯·霜语","到阿拉希高地的激流堡遗迹里面寻找巫妖生前的遗物。如果你能找到这样的东西，就把它交给马杜克镇长。"},
[5462]={"亡灵莱斯·霜语","到东瘟疫之地的圣光之愿礼拜堂去找到莱尼德·巴萨罗梅，给他看看巫妖生前的遗物，并告诉他你收集到的情报。"},
[5463]={"米奈希尔的礼物","到斯坦索姆城里去找到米奈希尔的礼物，把巫妖生前的遗物放在那块邪恶的土地上。"},
[5464]={"米奈希尔的礼物","把禁锢灵魂的遗物交给东瘟疫之地的莱尼德·巴萨罗梅。"},
[5465]={"禁锢灵魂的遗物","回到凯尔达隆的马杜克镇长那里，把禁锢灵魂的遗物交给他。"},
[5466]={"巫妖莱斯·霜语","在通灵学院里找到莱斯·霜语。当你找到他之后，使用禁锢灵魂的遗物破除其亡灵的外壳。如果你成功地破除了他的不死之身，就杀掉他并拿到莱斯·霜语的头颅。把那个头颅交给马杜克镇长。"},
[5515]={"卡斯迪诺夫的恐惧之袋","在通灵学院找到詹迪斯·巴罗夫并打败她。从她的尸体上找到卡斯迪诺夫的恐惧之袋，然后将其交给艾瓦·萨克霍夫。"},
[5522]={"莱尼德·巴萨罗梅","把冰冻的龙蛋交给东瘟疫之地的莱尼德·巴萨罗梅。"},
[5526]={"魔藤碎片","在厄运之槌中找到魔藤，然后从它上面采集一块碎片。只有干掉了奥兹恩之后，你才能进行采集工作。使用净化之匣安全地封印碎片，然后将其交给月光林地永夜港的拉比恩·萨图纳。"},
[5527]={"净化之匣","到希利苏斯的南风村去寻找净化之匣。然后将其交给月光林地永夜港的拉比恩·萨图纳。"},
[5529]={"瘟疫之龙","杀掉20只瘟疫龙崽，然后向圣光之愿礼拜堂的贝蒂娜·比格辛克复命。"},
[5531]={"贝蒂娜·比格辛克","将冰冻的龙蛋交给贝蒂娜·比格辛克。"},
[5533]={"通灵学院","和西瘟疫之地冰风岗的化学家阿尔比顿谈一谈。"},
[5722]={"寻找背包","在怒焰裂谷搜寻玛尔·恐怖图腾的尸体以及他留下的东西。"},
[5723]={"试探敌人","在奥格瑞玛找到怒焰裂谷，杀掉8个怒焰穴居人和8个怒焰萨满祭司，然后向雷霆崖的拉哈罗复命。"},
[5724]={"归还背包","将恐怖图腾背包交给雷霆崖的拉哈罗。"},
[5725]={"毁灭之力","将《暗影法术研究》和《扭曲虚空的魔法》这两本书交给幽暗城的瓦里玛萨斯。"},
[5726]={"隐藏的敌人","将军官的徽章交给奥格瑞玛的萨尔。"},
[5727]={"隐藏的敌人","将军官的徽章交给尼尔鲁·火刃并与他谈一谈，看看他是否相信你是火刃氏族中的一员，然后回到奥格瑞玛的萨尔那里。"},
[5728]={"隐藏的敌人","杀死巴扎兰和祈求者耶戈什，然后回到奥格瑞玛的萨尔那里。"},
[5761]={"饥饿者塔拉加曼","进入怒焰裂谷，杀死饥饿者塔拉加曼，然后把他的心脏交给奥格瑞玛的尼尔鲁·火刃。"},
[5848]={"爱与家庭","到瘟疫之地北部的斯坦索姆去。你可以在血色十字军堡垒中找到“爱与家庭”这幅画，它被隐藏在另一幅描绘两个月亮的画之后。 把这幅画还给提里奥·弗丁。"},
[6022]={"杀戮的理由","到东边的考林路口去屠杀镇里的亡灵天灾。在10分钟内收集7块生命腐质，使用研钵和捣杵将其研磨成凝固腐质。"},
[6042]={"讨厌的蝙蝠","杀掉20只毒性瘟疫蝙蝠和10只巨型瘟疫蝙蝠，然后回到纳萨诺斯·凋零者那里。"},
[6133]={"游侠之王的命令","到东瘟疫之地的北方边界去找回奎尔萨拉斯名册，这件物品在奎尔林斯小屋的某处。 另外你还必须杀掉8个游侠、8个巡路者和8个护林者。"},
[6135]={"暗翼蝠","找到暗翼蝠并杀掉它。从尸体上取下一块暗翼蝠的皮，并把它交给纳萨诺斯·凋零者。 据说暗翼蝠游荡在玛瑞斯农场北面的荒原上。"},
[6136]={"肥大的食腐虫","找到东瘟疫之地北方荒原中的淤血虫并消灭它。任务完成之后，向纳萨诺斯·凋零者复命。"},
[6163]={"吞咽者拉姆斯登","到斯坦索姆去，杀掉吞咽者拉姆斯登。把他的头颅交给纳萨诺斯。"},
[6402]={"集合在暴风城","前往暴风城的城门。与侍卫洛文交谈，他会通知温德索尔元帅你已经到达了。"},
[6403]={"潜藏者","跟随雷吉纳德·温德索尔元帅在暴风城中前进。保护他，别让他受到伤害！"},
[6501]={"巨龙之眼","你必须寻遍世界以找到一种能恢复龙眼碎片的能量的生物。你对这种生物的唯一了解就是：他们确实存在。"},
[6502]={"龙火护符","你必须从达基萨斯将军身上取回黑龙勇士之血，你可以在黑石塔的晋升大厅后面的房间里找到他。"},
[6521]={"邪恶的盟友","把玛克林大使的头颅交给幽暗城的瓦里玛萨斯。"},
[6522]={"邪恶的盟友","把小卷轴交给幽暗城的瓦里玛萨斯。"},
[6561]={"黑暗深渊中的邪恶","把梦游者克尔里斯的头颅交给雷霆崖的巴珊娜·符文图腾。"},
[6562]={"帮助耶努萨克雷","与灰谷的耶努萨克雷谈一谈。"},
[6563]={"阿库麦尔水晶","收集20颗阿库麦尔蓝宝石，把它们交给灰谷的耶努萨克雷。"},
[6564]={"上古之神的仆从","把潮湿的便笺交给灰谷的耶努萨克雷。"},
[6565]={"上古之神的仆从","杀掉黑暗深渊里的洛古斯·杰特，然后向灰谷的耶努萨克雷复命。"},
[6566]={"风吹来的消息","听萨尔讲话。"},
[6567]={"部落的勇士","按照酋长的指示找到雷克萨。他在石爪山和菲拉斯之间的凄凉之地游荡。"},
[6568]={"雷克萨的证明","把雷克萨的证明交给西瘟疫之地的巫女麦兰达。"},
[6569]={"黑龙幻象","到黑石塔去收集20颗黑色龙人的眼球，完成任务之后回到巫女麦兰达那里。"},
[6570]={"埃博斯塔夫","到尘泥沼泽中的巨龙沼泽去，找到埃博斯塔夫的洞穴。进入洞穴之后戴上龙形护符，然后跟埃博斯塔夫交谈。"},
[6582]={"龙骨试炼，斯克利尔","找到蓝龙斯克利尔并杀掉他。从他的身上取下他的颅骨，然后将其交给埃博斯塔夫。 你可以在冬泉谷找到斯克利尔。"},
[6583]={"龙骨试炼，索姆努斯","杀掉绿龙索姆努斯，把他的颅骨交给埃博斯塔夫。"},
[6584]={"龙骨试炼，克鲁纳里斯","诺兹多姆的孩子克鲁纳里斯在塔纳利斯沙漠守卫着时光之穴。杀了他，把他的颅骨交给埃博斯塔夫。"},
[6585]={"龙骨试炼，埃克托兹","到格瑞姆巴托去杀掉红龙埃克托兹，把他的颅骨交给埃博斯塔夫。"},
[6601]={"晋升……","看来这场假面舞会就要结束了。你知道麦兰达为你制作的龙形护符在黑石塔里面不会发挥作用，也许你应该去找雷克萨，将你的困境告诉他。把黯淡的龙火护符给他看看，也许他知道下一步该怎么做。"},
[6602]={"黑龙勇士之血","到黑石塔去杀掉达基萨斯将军，把它的血交给雷克萨。"},
[6626]={"邪恶之地","杀掉8个剃刀沼泽护卫者、8个剃刀沼泽织棘者和8个亡首教徒，然后向剃刀高地入口处的麦雷姆·月歌复命。"},
[6627]={"知识试炼","成功回答布劳格·幽魂的问题，然后和他再次对话。他会一直在石爪山等你回答问题。"},
[6628]={"知识试炼","成功回答帕科瓦·芬塔拉斯的问题，然后再次和他对话。他会一直在幽暗城等你回答问题。"},
[6642]={"兄弟会的好感 - 黑铁矿石"},
[6643]={"兄弟会的好感 - 炽热之核"},
[6644]={"兄弟会的好感 - 熔岩之核"},
[6645]={"兄弟会的好感 - 熔火犬皮"},
[6646]={"兄弟会的好感 - 山脉之血"},
[6804]={"被囚禁的水元素","对东瘟疫之地的被感染的水元素使用海神之水。把12副不谐护腕和海神之水交给艾萨拉的海达克西斯公爵。"},
[6805]={"雷暴和磐石","杀死15个灰尘风暴和15个沙漠奔行者，然后回到艾萨拉的海达克西斯公爵那儿。"},
[6821]={"艾博希尔之眼","将艾博希尔之眼交给艾萨拉的海达克西斯公爵。"},
[6822]={"熔火之心","杀死一个火焰之王、一个熔岩巨人、一个上古熔火恶犬和一个熔岩奔腾者，然后回到艾萨拉的海达克西斯公爵那里。"},
[6823]={"海达克西斯的使者","在海达希亚水元素中达到被尊敬的声望，然后与艾萨拉的海达克西斯公爵谈一谈。"},
[6824]={"敌人之手","将鲁西弗隆之手、萨弗隆之手、基赫纳斯之手和沙斯拉尔之手交给艾萨拉的海达克西斯公爵。"},
[6921]={"废墟之间","把深渊之核交给灰谷佐拉姆加前哨站里的耶努萨克雷。"},
[6922]={"阿奎尼斯男爵","把奇怪的水球交给灰谷佐拉姆加前哨站的耶努萨克雷。"},
[6981]={"发光的碎片","寻找更多有关这块噩梦碎片的信息。"},
[7028]={"扭曲的邪恶","为凄凉之地的维洛收集25个瑟莱德丝水晶雕像。"},
[7029]={"维利塔恩的污染","在玛拉顿里用天蓝水瓶在橙色水晶池中装满水。 在维利斯塔姆藤蔓上使用装满水的天蓝水瓶，使堕落的诺克赛恩幼体出现。 治疗8株植物并杀死那些诺克赛恩幼体，然后向葬影村的瓦克·战痕复命。"},
[7041]={"维利塔恩的污染","在玛拉顿里用天蓝水瓶在橙色水晶池中装满水。 在维利斯塔姆藤蔓上使用装满水的天蓝水瓶，使堕落的诺克赛恩幼体出现。 治疗8株植物并杀死那些诺克赛恩幼体，然后向尼耶尔前哨站的塔琳德莉亚复命。"},
[7044]={"玛拉顿的传说","找回塞雷布拉斯节杖的两个部分：塞雷布拉斯魔棒和塞雷布拉斯钻石。 然后设法和塞雷布拉斯对话。"},
[7046]={"塞雷布拉斯节杖","帮助赎罪的塞雷布拉斯制作塞雷布拉斯节杖。 当仪式完成之后再和他谈谈。"},
[7064]={"大地的污染","杀死瑟莱德丝公主，然后回到凄凉之地葬影村附近的瑟琳德拉那里复命。"},
[7065]={"大地的污染","杀死瑟莱德丝公主，然后回到凄凉之地尼耶尔前哨站的守护者玛兰迪斯那里复命。"},
[7066]={"生命之种","到月光林地去找到雷姆洛斯，将生命之种交给他。"},
[7067]={"贱民的指引","阅读贱民的指引，然后从玛拉顿得到联合坠饰，将其交给凄凉之地南部的半人马贱民。"},
[7068]={"暗影残片","从玛拉顿收集10块暗影残片，然后把它们交给奥格瑞玛的尤塞尔奈。"},
[7070]={"暗影残片","从玛拉顿收集10块暗影残片，然后把它们交给尘泥沼泽塞拉摩岛上的大法师特沃什。"},
[7201]={"最后的元素","到黑石深渊去取得10份元素精华。你应该在那些作战傀儡和傀儡制造者身上找找，另外，薇薇安·拉格雷也提到了一些有关元素生物的话题……"},
[7441]={"普希林和埃斯托尔迪","到厄运之槌去找到小鬼普希林。你可以使用任何手段从小鬼那里得到埃斯托尔迪的咒术之书。 找到咒术之书后，回到拉瑞斯小亭的埃斯托尔迪那里。"},
[7461]={"伊莫塔尔的疯狂","你必须干掉5座水晶塔周围的守卫，那5座水晶塔维持着关押伊莫塔尔的监狱。一旦水晶塔的能量被削弱，伊莫塔尔周围的能量力场就会消散。 进入伊莫塔尔的监狱，干掉站在中间的那个恶魔。最后，在图书馆挑战托塞德林王子。 当任务完成之后，到庭院中去找辛德拉古灵。"},
[7462]={"辛德拉的宝藏","返回图书馆去找到辛德拉的宝藏。拿取你的奖励吧！"},
[7463]={"久违的法师","到厄运之槌的扭木广场去杀掉水元素海多斯博恩。把海多斯博恩精华交给图书馆的博学者莱德罗斯。"},
[7481]={"精灵的传说","到厄运之槌去寻找泰尔米乌斯·探梦者。向莫沙彻营地的先知科鲁拉克报告你所找到的信息。"},
[7482]={"精灵的传说","到厄运之槌去寻找泰尔米乌斯·探梦者。向羽月要塞的学者卢索恩·纹角报告你所找到的信息。"},
[7486]={"英雄的奖赏","从海达克西斯的箱子拿取你的奖励。"},
[7488]={"蕾瑟塔蒂丝的网","把蕾瑟塔蒂丝的网交给菲拉斯羽月要塞的拉托尼库斯·月矛。"},
[7489]={"蕾瑟塔蒂丝的网","把蕾瑟塔蒂丝的网交给非拉斯莫沙彻营地的塔罗·刺蹄。"},
[7490]={"部落的胜利","将奥妮克希亚的头颅交给奥格瑞玛的萨尔。"},
[7491]={"万众敬仰","在力量谷找到伦萨克。"},
[7493]={"一切才刚刚开始"},
[7495]={"联盟的胜利","将奥妮克希亚的头颅交给暴风城的伯瓦尔·弗塔根公爵。"},
[7496]={"英雄庆典","在英雄谷找到玛丁雷少校。"},
[7497]={"一切才刚刚开始"},
[7498]={"迦罗娜：潜行与诡计研究","将这本典籍交给它的主人。"},
[7499]={"防御宝典","将这本典籍交给它的主人。"},
[7500]={"奥法师的食谱","将这本典籍交给它的主人。"},
[7501]={"圣光之力","将这本典籍交给它的主人。"},
[7502]={"束缚之影","将这本典籍交给它的主人。"},
[7503]={"最伟大的猎手","将这本典籍交给它的主人。"},
[7504]={"光明不会告诉你的事情","将这本典籍交给它的主人。"},
[7505]={"你与冰霜震击","将这本典籍交给它的主人。"},
[7506]={"翡翠梦境……","将这本典籍交给它的主人。"},
[7507]={"诺斯特罗的屠龙技术纲要","将《诺斯特罗的屠龙技术纲要》还回图书馆。"},
[7508]={"铸造奎尔塞拉","把黯淡的精灵剑交给博学者莱德罗斯。"},
[7509]={"铸造奎尔塞拉","你必须设法让奥妮克希亚对这把未淬火的的上古之刃喷射火焰。完成之后，捡起加热过的上古之刃。你要注意的是，加热过的上古之刃不会一直保持被加热的状态，时间非常紧迫。 在把它给我拿回来之前的最后一步是杀掉那条龙，并将加热过的上古之刃插入她的尸体中。 完成这些之后，奎尔塞拉就是你的了。"},
[7563]={"血之狂暴","把30瓶狂暴野兽的血交给燃烧平原的莫苏尔·召血者。"},
[7564]={"戈瑟奇·邪眼","把血箱交给燃烧平原的戈瑟奇·邪眼。"},
[7604]={"瑟银兄弟会契约","如果你愿意接受萨弗隆的设计图，请将瑟银兄弟会契约交给罗克图斯·暗契。"},
[7621]={"警示 (optional explanation)"},
[7622]={"光与影的平衡","在总计有15个农夫被杀死之前拯救50个农夫。完成任务之后与艾瑞斯·哈文法谈谈。 你可以通过浏览死亡布告来了解自己拯救了多少农夫。"},
[7623]={"魔王贝恩霍勒","从燃烧平原的戈瑟奇那里购买暗影药水。 使用这种药剂进入加德纳尔，然后与魔王贝恩霍勒谈一谈。"},
[7624]={"背叛者乌拉泰克","找到并杀死乌拉泰克，然后把叛徒之心交给加德纳尔的魔王贝恩霍勒。"},
[7625]={"克索诺斯星尘","从乌尔丹那里购买克索诺斯星尘，把它交给燃烧平原的戈瑟奇·邪眼。"},
[7629]={"瓶中的小鬼","把瓶中的小鬼带到通灵学院的炼金实验室中。在小鬼制造出羊皮纸之后，把瓶子还给戈瑟奇·邪眼。"},
[7631]={"克索诺斯恐惧战马","阅读莫苏尔的指南，并召唤出一匹克索诺斯恐惧战马，击败它，然后控制它的灵魂。"},
[7632]={"远古石叶","找到远古石叶的主人。祝你好运，<name>。这个世界是很大的。"},
[7634]={"龙筋箭袋","费伍德森林的古树哈斯塔特要求你带回一块成年蓝龙的肌腱。"},
[7635]={"合适的弓弦","费伍德森林的古树斯托玛要求你带给他一块成年黑龙的肌腱。"},
[7636]={"古树的手杖","你必须找到并干掉下列4个恶魔： 迷人的西蒙妮。 疯狂的克林弗兰。 S屠杀者索伦诺尔。 摧毁者阿托留斯。 杀掉这些恶魔，然后回到费伍德森林的古树瓦特鲁斯那里去。 根据你背包中的石化树皮来找到它们所在位置的线索。 你必须独自完成这个任务。"},
[7637]={"牺牲精神","到铁炉堡去找高阶牧师洛汉，从他那里拿到驱魔香炉。你需要捐赠150金币来获得它。"},
[7639]={"圣骑士的审判","把驱魔香炉交给暴风城教堂区的格雷森·沙东布瑞克公爵。"},
[7640]={"恐惧谷的灵魂","使用驱魔香炉召唤恐惧谷中的灵魂。当你杀掉25个恐惧谷的灵魂之后，回到暴风城教堂区的格雷森·沙东布瑞克公爵那里复命。"},
[7641]={"格瑞曼德·艾尔默","与暴风城矮人区的格瑞曼德·艾尔默谈一谈。"},
[7642]={"收集材料","把40块符文布、6块奥金锭、10棵阿尔萨斯之泪、5瓶斯坦索姆圣水和150枚金币交给暴风城矮人区的格瑞曼德·艾尔默。"},
[7643]={"上古圣马之魂","你需要特殊的饲料来喂养灵魂马。南海镇的梅丽德丝·卡尔森可以为你提供这样的粮草。 到菲拉斯的厄运之槌去，杀掉特迪斯·扭木，释放上古圣马之魂。用特殊的粮草喂养它，这样可以安抚它的灵魂。最后，把奥金马铠交给它就可以完成祝福。"},
[7644]={"被祝福的奥金马铠","将被祝福的奥金马铠交给暴风城教堂区的格雷森·沙东布瑞克公爵。"},
[7646]={"预言水晶球","把一块艾泽拉斯钻石和一块原始黑钻石交给暴风城教堂区的格雷森·沙东布瑞克公爵。"},
[7647]={"审判和救赎","在通灵学院尸骨储藏所地下室的中心使用预言水晶球。将你要审判的灵魂引领出来。将这些灵魂击败然后死亡骑士达克雷尔就将被召唤出来。将其击败然后获得堕落战马的灵魂。 把赎罪的战马之魂和被祝福的奥金马铠一起附在达克雷尔的堕落战马身上。"},
[7648]={"艾尔默的手艺","把奥金马铠交给暴风城教堂区的格雷森·沙东布瑞克公爵。"},
[7667]={"收集材料","如果你愿意帮助奥格瑞玛智慧谷的萨格尼，就将一块艾泽拉斯钻石和一块原始黑钻石交给他。"},
[7703]={"戈多克食人魔的事务","找到戈多克力量护手，并将它交给厄运之槌的克罗卡斯。 根据克罗卡斯所说的，“传说”自称是王子的精灵托塞德林从一名戈多克食人魔手中偷走了那件神器。"},
[7761]={"黑手的命令","真是个愚蠢的兽人。看来你需要找到那枚烙印并获得达基萨斯徽记才可以使用命令宝珠。 你从信中获知，达基萨斯将军守卫着烙印。也许你应该就此进行更深入的调查。"},
[7781]={"黑石之王","将奈法利安的头颅交给暴风城的伯瓦尔·弗塔根公爵。"},
[7782]={"黑石之王","回到暴风城的英雄谷，与艾法希比元帅谈一谈。"},
[7783]={"黑石之王","将奈法利安的头颅交给奥格瑞玛的萨尔。"},
[7784]={"黑石之王","和奥格瑞玛的萨鲁法尔大王谈谈。他在力量谷等你。"},
[7785]={"复生之瓶","查看复生之瓶，然后回到德米提恩那里去。"},
[7786]={"逐风者桑德兰","如果你想要把逐风者桑德兰从监牢里释放出来，你就必须找到左右两块逐风者禁锢之颅，10块源质锭，以及火焰之王的精华，把它们交给德米提恩。"},
[7787]={"觉醒吧，雷霆之怒！","把风吻之刃交给德米提恩。"},
[7848]={"熔火之心的传送门","进入黑石深渊，在通往熔火之心的传送门附近找到一块熔火碎片，然后回到黑石山脉的洛索斯·天痕那里。"},
