[8256]={"亡灵的腐液","为艾萨拉的奥汀克带回一份亡灵腐液。奥汀克住在埃达拉斯废墟东北部悬崖的顶端。"},
[8257]={"摩弗拉斯之血","前往沉没的阿塔哈卡神庙，杀死绿龙摩弗拉斯，将他的血液交给费伍德森林中的格雷塔·苔蹄。沉没的神庙的入口就在悲伤沼泽中。"},
[8258]={"达克雷尔的威胁","在斯坦索姆地下室的尸骨储藏所的中心使用预言水晶球。然后你必须与被召唤出来的幽灵作战。击败这些幽灵之后，死亡骑士达克雷尔才会出现，你的任务就是击败他。 把死亡骑士达克雷尔的头颅交给奥格瑞玛智慧谷的萨格尼。"},
[8286]={"明天的希望","前往塔纳利斯的时光之穴寻找诺兹多姆的子嗣，阿纳克洛斯。"},
[8288]={"唯一的领袖","到黑石山中的奈法利安巢穴去，杀死勒什雷尔，并带回它的头颅。 将勒什雷尔的头颅交给希利苏斯塞纳里奥要塞的流沙守望者巴里斯托尔斯。"},
[8301]={"正义之路","为流沙守望者巴里斯托尔斯收集200块异种蝎壳碎片。"},
[8302]={"正义之手","为流沙守望者巴里斯托尔斯收集200块异种蝎壳碎片。"},
[8303]={"阿纳克洛斯","到塔纳利斯的时光之穴去寻找阿纳克洛斯。"},
[8305]={"久远的记忆","找到希利苏斯的水晶之泪，并凝视它。"},
[8412]={"灵魂图腾","将灵魂图腾所需的材料交给捕风者巴斯拉。"},
[8413]={"巫毒羽毛","将巫毒羽毛交给捕风者巴斯拉。"},
[8414]={"驱散邪恶","收集20个爪牙的天灾石，并将它们交给西瘟疫之地的高阶牧师赛尔丹尼斯。"},
[8416]={"惰性天灾石","将惰性天灾石交给冰风岗的指挥官阿什拉姆·瓦罗菲斯特。"},
[8417]={"困扰的灵魂","到诅咒之地的入口去，与部落英雄的灵魂谈一谈。"},
[8418]={"铸造力量之石","前往沉没的神庙，从巨魔守护者们身上取得巫毒羽毛，然后把它们交给阿什拉姆·瓦罗菲斯特。"},
[8419]={"小鬼的要求","将一块恶魔布交给费伍德森林的伊普斯。"},
[8420]={"灼热的疼痛","将一块恶魔布交给费伍德森林的伊普斯。"},
[8421]={"奇怪的材料","将10块腐烂的木头和4个血毒精华交给费伍德森林的伊普斯。"},
[8422]={"巨魔的羽毛","到沉没的神庙去，从巨魔们身上获得6支巫毒羽毛。"},
[8423]={"战士的血脉","杀死7头地狱野猪，然后回到部落英雄的灵魂那儿。"},
[8424]={"魔誓者之战","杀死诅咒之地的魔誓者，然后回到部落英雄的灵魂那儿。"},
[8425]={"巫毒羽毛","将你从沉没的神庙的巨魔身上得到的巫毒羽毛交给部落英雄的灵魂。"},
[8519]={"往日的回忆","了解所以可以的过去的事情，然后和塔纳利斯时光之穴的阿纳克洛斯谈谈。"},
