[1221]={"藍葉薯","找到壹個開孔的箱子。 找到壹根地鼠指揮棒。 找到並閱讀《地鼠指揮手冊》。 在剃刀沼澤裏用開孔的箱子召喚壹只地鼠，然後用指揮棒驅使它去搜尋藍葉薯。 把地鼠指揮棒、開孔的箱子和10塊藍葉薯交給棘齒城的麥伯克·米希瑞克斯。"},
[1275]={"研究墮落","奧伯丁的戈沙拉·夜語需要8塊墮落者的腦幹。"},
[1360]={"失而復得","到奧達曼的北部大廳去找到克羅姆·粗臂的箱子，從裏面拿出他的寶貴財產，然後回到鐵爐堡把東西交給他。"},
[1394]={"通過試煉","和千針石林的多恩·平原行者談壹談。"},
[1424]={"淚水之池","斯通納德的費澤魯爾要求妳收集10件阿塔萊神器。"},
[1429]={"阿塔萊流放者","將壹捆阿塔萊神器交給辛特蘭的阿塔萊流放者。"},
[1444]={"向費澤魯爾復命","向斯通納德的費澤魯爾回報。"},
[1445]={"阿塔哈卡神廟","收集20個哈卡神像，把它們帶給斯通納德的費澤魯爾。"},
[1446]={"預言者迦瑪蘭","辛特蘭的阿塔萊流放者要妳給他帶回迦瑪蘭的頭。"},
[1448]={"調查神廟","暴風城的布羅哈恩·鐵桶要求妳去找到阿塔哈卡神廟。"},
[1449]={"去辛特蘭的旅程","找到辛特蘭的弗斯塔德·蠻錘。"},
[1450]={"獅鷲管理員","與辛特蘭的鷹巢山獅鷲飼養場裏的獅鷲管理員沙拉克·鷹斧談壹談。"},
[1451]={"拉普索迪·鐵鏟","去辛特蘭找到拉普索迪·鐵鏟。"},
[1452]={"拉普索迪的卡利姆多雞尾酒","辛特蘭的拉普索迪·鐵鏟要求妳帶給他3塊大鵬的砂囊、3塊格羅多克猩猩的肝臟和3塊鐵鬃熊的肝臟。"},
[1469]={"拉普索迪的故事","將阿塔萊石板碎片交給暴風城的布羅哈恩·鐵桶。"},
[1475]={"進入阿塔哈卡神廟","為暴風城的布羅哈恩·鐵桶收集10塊阿塔萊石板。"},
[1486]={"變異皮革","哀嚎洞穴的納爾帕克想要20張變異皮革。"},
[1487]={"清除變異者","哀嚎洞穴的厄布魯要求妳殺掉7只變異破壞者、7只劇毒飛蛇、7只變異蹣跚者和7只變異尖牙風蛇。"},
[1489]={"哈繆爾·符文圖騰","和哈繆爾·符文圖騰談壹談。"},
[1490]={"納拉·蠻鬃","和納拉·蠻鬃談壹談。"},
[1491]={"智慧飲料","收集6份哀嚎香精，把它們交給棘齒城的麥伯克·米希瑞克斯。"},
[1651]={"勇氣之書","在迪菲亞兄弟會進攻時保護達芙妮·斯迪威爾的安全。 如果妳想成功的話，妳和達芙妮都不能死在他們的劍下。"},
[1652]={"勇氣之書","與暴風城的達索瑞恩·拉爾談壹談。"},
[1653]={"正義試煉","去和鐵爐堡的喬丹·斯迪威爾談壹談。"},
[1654]={"正義試煉","按照喬丹的武器材料單上的說明去尋找壹些白石橡木、精煉礦石、喬丹的鐵錘和壹塊科爾寶石，然後回到鐵爐堡去見喬丹·斯迪威爾。"},
[1740]={"索蘭魯克寶珠","找到3塊索蘭魯克寶珠的碎片和1塊索蘭魯克寶珠的大碎片，把它們交給貧瘠之地的杜安·卡漢。"},
[1806]={"正義試煉","等待喬丹·斯迪威爾為妳鑄造武器。"},
[1956]={"奧達曼的能量源","找到壹個黑曜石能量源，將其交給塵泥沼澤的塔貝薩。"},
[2040]={"地底突襲","從死亡礦井中帶回小型高能發動機，將其帶給暴風城矮人區中的沈默的舒尼。"},
[2198]={"破碎的項鏈","找到破碎的項鏈的來源，從而了解其潛在的價值。"},
[2199]={"昂貴的知識","給鐵爐堡的塔瓦斯德·基瑟爾帶去五塊銀錠。"},
[2200]={"回到奧達曼","去奧達曼尋找塔瓦斯的魔法項鏈，被殺的聖騎士是最後壹個拿著它的人。"},
[2201]={"尋找寶石","在奧達曼尋找紅寶石、藍寶石和黃寶石的下落。找到它們之後，通過塔瓦斯德給妳的占蔔之瓶和他進行聯系。"},
[2202]={"奧達曼的蘑菇","收集12顆紫色蘑菇，把它們交給卡加斯的加卡爾。"},
[2204]={"修復項鏈","從奧達曼最強大的石人身上獲得能量源，然後將其交給鐵爐堡的塔瓦斯德。"},
[2240]={"密室","閱讀巴爾洛戈的日記，探索密室，然後向鐵爐堡的勘察員塔伯斯·雷矛匯報。"},
[2258]={"荒蕪之地的試劑","前往荒蕪之地取回加卡爾需要的試劑，然後回到卡加斯把試劑交給他。"},
[2278]={"白金圓盤","和石頭守護者交談，從他那裏了解更多古代的知識。壹旦妳了解到了所有的內容之後就激活諾甘農圓盤。"},
[2280]={"白金圓盤","把迷妳版的諾甘農圓盤帶到雷霆崖的賢者那裏。"},
[2283]={"搜尋項鏈","在奧達曼挖掘場中尋找壹條珍貴的項鏈，然後將其交給奧格瑞瑪的德蘭·杜佛斯。項鏈有可能已經損壞。"},
[2284]={"搜尋項鏈，再來壹次","在奧達曼裏找尋寶石的線索。"},
[2318]={"翻譯日記","在荒蕪之地的卡加斯哨所裏尋找壹個可以幫妳翻譯聖騎士日記的人。"},
[2338]={"翻譯日記","將項鏈借給加卡爾。作為交換，他將幫妳翻譯日記。"},
[2339]={"尋找寶貝","從奧達曼找回項鏈上的所有三塊寶石和能量源，然後把它們交給卡加斯的加卡爾。 紅寶石被藏在暗影矮人層層設防的地區。 黃寶石藏在石腭怪活動地區的壹個甕中。 藍寶石在格瑞姆洛克手中，他是石腭怪的領袖。 能量源可能在奧達曼的某個最強生物的手中。"},
[2342]={"尋找寶物","從奧達曼南部大廳的箱子中找到加勒特的家族寶藏，然後把它交給幽暗城的帕特裏克·加瑞特。"},
[2398]={"失蹤的矮人","在奧達曼找到巴爾洛戈。"},
[2418]={"能量石","給荒蕪之地的裏格弗茲帶去8塊德提亞姆能量石和8塊安納洛姆能量石。"},
[2500]={"荒蕪之地的材料","從荒蕪之地拿到加克所需的材料，然後回到塞爾薩瑪去見他。"},
[2768]={"探水棒","把探水棒交給加基森的首席工程師沙克斯·比格維茲。"},
[2770]={"加茲瑞拉","把加茲瑞拉的鱗片交給閃光平原的維茲爾·銅栓。"},
[2841]={"設備之戰","從諾莫瑞根拿到鉆探設備藍圖和麥克尼爾的保險箱密碼，把它們交給奧格瑞瑪的諾格。"},
[2842]={"主工程師斯庫提","和藏寶海灣的斯庫提談壹談。"},
[2843]={"出發！諾莫瑞根！","等斯庫提調整好地精傳送器。"},
[2846]={"深淵皇冠","將深淵皇冠交給塵泥沼澤的塔貝薩。"},
[2865]={"聖甲蟲的殼","給加基森的特蘭雷克帶去5個完整的聖甲蟲殼。"},
[2904]={"壹團混亂","將克努比護送到出口，然後向藏寶海灣的斯庫提匯報。"},
[2922]={"拯救尖端機器人！","將尖端機器人的存儲器核心交給鐵爐堡的工匠大師歐沃斯巴克。"},
[2924]={"基礎模組","收集12個基礎模組，把它們交給鐵爐堡的科勞莫特·鋼尺。"},
[2926]={"諾恩","用空鉛瓶對著輻射入侵者或者輻射搶劫者，從它們身上收集放射塵。瓶子裝滿之後，把它交給卡拉諾斯的奧齊·電環。"},
[2928]={"陀螺式挖掘機","收集24副機械內膽，把它們交給暴風城的舒尼。"},
[2929]={"大叛徒","到諾莫瑞根去殺掉麥克尼爾·瑟瑪普拉格。完成任務之後向大工匠梅卡托克報告。"},
[2930]={"搶救數據","將彩色穿孔卡片交給鐵爐堡的大機械師卡斯派普。"},
[2933]={"毒液瓶","將毒藥瓶交給塔倫米爾的某個藥劑師。"},
[2934]={"完好無損的毒囊","將完好無損的毒囊交給塔倫米爾的藥劑師林度恩。"},
[2935]={"請教加德林大師","與森金村的加德林大師談壹談。"},
[2936]={"蜘蛛之神","閱讀塞卡石板，了解枯木巨魔的蜘蛛之神的名字，然後回到加德林大師那裏。"},
[2945]={"臟兮兮的戒指","想方法把臟兮兮的戒指弄幹凈。"},
[2947]={"戒指歸來","妳要麽自己留著這枚戒指，要麽就按照戒指內側刻著的名字找到它的主人。"},
[2948]={"侏儒的手藝","將閃亮的金戒指、1塊銀錠、1塊綠瑪瑙和30個銀幣交給鐵爐堡的塔瓦斯德·基瑟爾。"},
[2949]={"戒指歸來","妳要麽自己留著這枚戒指，要麽就按照戒指內側刻著的名字找到它的主人。"},
[2950]={"諾格的手藝","將閃亮的金戒指、1塊銀錠、1塊綠瑪瑙和30個銀幣交給奧格瑞瑪的諾格。"},
[2951]={"超級清潔器5200型！","將臟兮兮的東西放入超級清潔器5200型，記得要用三枚銀幣來啟動機器。"},
[2962]={"更多的輻射塵！","到諾莫瑞根去收集高強度輻射塵。要多加小心，這種輻射塵非常不穩定，很快就會分解。 奧齊要求妳把沈重的鉛瓶也交給他。"},
[2988]={"枯木巨魔的牢籠","檢查兩個枯木巨魔村落裏的籠子，然後向獅鷲管理員沙拉克·鷹斧回復。"},
[2989]={"祖爾祭壇","檢查祖爾祭壇的頂部，然後向獅鷲管理員沙拉克·鷹斧報告。"},
[2990]={"薩迪斯·格希德","將沙普比克的羽毛交給詛咒之地的薩迪斯·格希德。"},
[2991]={"耐克魯姆的徽章","將耐克魯姆的徽章交給詛咒之地的薩迪斯·格希德。"},
[3042]={"巨魔調和劑","收集20瓶巨魔調和劑，把它們交給加基森的特倫頓·輕錘。"},
[3341]={"寒冰之王","安德魯·布隆奈爾要妳殺了寒冰之王亞門納爾並將其頭骨帶回來。"},
[3373]={"伊蘭尼庫斯精華","把伊蘭尼庫斯精華放在精華之泉裏，精華之泉就在沈沒的神廟中，伊蘭尼庫斯的巢穴裏。"},
[3444]={"石環","到棘齒城去，從瑪爾馮·瑞文斯克的車間裏取回石環。"},
[3446]={"深入神廟","在悲傷沼澤沈沒的神廟中找到哈卡祭壇。"},
[3447]={"雕像群的秘密","到沈沒的神廟去，揭開雕像群中隱藏的秘密。"},
[3520]={"尖嘯者的靈魂","在菲拉斯捕獲3個尖嘯者的靈魂，然後回到熱砂港的葉基亞那裏去。"},
[3523]={"剃刀高地的亡靈天災","如果妳同意幫助奔尼斯特拉茲，就再跟他談談，並將誓言石還給他。"},
[3525]={"封印神像","保護奔尼斯特拉茲來到剃刀高地的野豬人神像處。 當他在進行儀式封印神像時保護他。"},
[3527]={"摩沙魯的預言","將第壹塊和第二塊摩沙魯石板交給塔納利斯的葉基亞。"},
[3528]={"神靈哈卡","將裝滿的哈卡之卵交給塔納利斯的葉基亞。"},
[3636]={"與聖光同在","大主教本尼迪塔斯要妳去殺死剃刀高地的寒冰之王亞門納爾。"},
[3701]={"索瑞森廢墟","到燃燒平原的索瑞森廢墟中去，從索瑞森遺物上搜集信息。當妳收集到足夠的信息之後，就回到皇家歷史學家阿克瑟努斯那裏。"},
[3702]={"索瑞森廢墟","聽皇家歷史學家阿克瑟努斯講述索瑞森的歷史。"},
[3765]={"遙遠的旅途","到奧伯丁的戈沙拉·夜語那兒去。"},
[3801]={"黑鐵的遺產","如果妳想要得到進入這座城市主城區的鑰匙，就去和弗蘭克羅恩·鑄鐵談壹談。"},
[3802]={"黑鐵的遺產","殺掉弗諾斯·達克維爾並拿回戰錘鐵膽。把鐵膽之錘拿到索瑞森神殿去，將其放在弗蘭克羅恩·鑄鐵的雕像上。"},
[3906]={"不和諧的烈焰","到黑石山脈的采石場去幹掉征服者派隆，然後向桑德哈特回報。"},
[3907]={"不和諧的火焰","進入黑石深淵並找到伊森迪奧斯。殺掉它，然後把妳找到的信息匯報給桑德哈特。"},
[3981]={"指揮官哥沙克","在黑石深淵裏找到指揮官哥沙克。 在那幅草圖上畫著的是壹個鐵欄後面的獸人，也許妳應該到某個類似監獄的地方去找找看。"},
[3982]={"出了什麽事？","保護哥沙克。"},
[4001]={"出了什麽事？","與卡蘭·巨錘談壹談，收集關於綁架公主鐵爐堡公主茉艾拉·銅須這壹事件的情報。將情報反饋給奧格瑞瑪城裏的薩爾。 哥沙克提到過卡蘭被關在附近的某個牢房中。"},
[4002]={"東部王國","如果妳準備好要接受薩爾所安排的任務，就去找他談壹談。"},
[4003]={"拯救公主","殺掉達格蘭·索瑞森大帝，然後將鐵爐堡公主茉艾拉·銅須從他的邪惡詛咒中拯救出來。"},
[4022]={"烈焰精華","向塞勒斯·薩雷芬圖斯展示妳從卡拉然·溫布雷那裏得到的黑龍皮。"},
[4024]={"烈焰精華","到黑石深淵去殺掉貝爾加。 妳只知道這個巨型怪物住在黑石深淵的最深處。記住妳要使用特殊的黑龍皮從貝爾加的屍體上采集烈焰精華。 將妳采集到的烈焰精華交給塞勒斯·薩雷芬圖斯。"},
[4061]={"機器的崛起","到燃燒平原去為塞朵拉·穆瓦丹尼收集10塊斷裂的元素碎片。 塞朵拉曾經說過，那裏的機械傀儡和元素生物是這種碎片的主要來源。"},
[4062]={"機器的崛起","將元素碎片樣本交給魯特維爾·沃拉圖斯。 塞朵拉說魯特維爾就在東邊的壹處營地裏。"},
[4063]={"機器的崛起","找到並殺掉傀儡統帥阿格曼奇，將他的頭交給魯特維爾。妳還需要從守衛著阿格曼奇的狂怒傀儡和戰鬥傀儡身上收集10塊完整的元素核心。"},
[4081]={"格殺勿論：黑鐵矮人","到黑石深淵去消滅那些邪惡的侵略者！ 軍官高圖斯要妳去殺死15個鐵怒衛士、10個鐵怒獄卒和5個鐵怒步兵。完成任務之後回去向他復命。"},
[4082]={"格殺勿論：高階黑鐵軍官","到黑石深淵去消滅那些邪惡的侵略者！ 高圖斯軍閥要妳殺死10個鐵怒醫師,、10個鐵怒士兵和10個鐵怒軍官。完成任務之後回去向他復命。"},
[4083]={"鬼魂之杯"},
[4121]={"押送囚徒","押送妳的囚犯格拉克·洛克魯布。穿過燃燒平原和黑石山脈，壹直走到灼熱峽谷。 雷克斯洛特曾經告訴過妳，他會讓他的人等在黑石山脈的另外壹邊準備接收格拉克。 另外，妳還要把瑟銀鐐銬壹並還給雷克斯洛特。"},
[4122]={"格拉克·洛克魯布","到燃燒平原去找到格拉克·洛克魯布。妳回憶起雷克斯洛特曾經提起過，格拉克應該是在壹座大型的黑石要塞中。 當妳找到格拉克·洛克魯布之後，用瑟銀鐐銬把他銬起來，然後將其帶回灼熱峽谷。雷克斯洛特會讓他的部下等在那裏接應妳。"},
[4123]={"山脈之心","把山脈之心交給燃燒平原的麥克斯沃特·尤博格林。"},
[4126]={"霍爾雷·黑須","把遺失的雷酒秘方帶給卡拉諾斯的拉格納·雷酒。"},
[4132]={"行動：殺死安格弗將軍","到黑石深淵去殺掉安格弗將軍！當任務完成之後向軍官高圖斯復命。"},
[4134]={"遺失的雷酒秘方","把遺失的雷酒秘方交給卡加斯的薇薇安·拉格雷。"},
[4136]={"雷布裏·斯庫比格特","把雷布裏的頭顱交給燃燒平原的尤卡·斯庫比格特。"},
[4141]={"穆爾金和拉瑞安","從安戈洛爾環形山的血瓣花猛擊者和血瓣花掠奪者身上收集15個血瓣花，然後向穆爾金回復。"},
[4142]={"造訪格雷甘","把血瓣花交給菲拉斯的格雷甘·山酒。"},
[4143]={"邪惡之霧","收集5份阿塔萊之霧的樣本，然後向安戈洛環形山的穆爾金復命。"},
[4145]={"拉瑞安和穆爾金","為馬紹爾營地裏的拉瑞安殺掉5個血瓣花鞭笞者、5個血瓣花捕獸者、5個血瓣花掠奪者和5個血瓣花猛擊者。"},
[4146]={"除草器的燃料","收集5份阿塔萊之霧的樣本，然後將它們送到馬紹爾營地的拉瑞安那裏。"},
[4147]={"瑪爾馮的車間","到棘齒城去，在瑪爾馮·瑞文斯克的車間裏找到他。"},
[4182]={"黑龍的威脅","殺掉15條黑色小龍、10條黑色龍人和1條黑色幼龍。當妳完成任務之後就向赫林迪斯·河角回報。"},
[4183]={"真正的主人","把赫林迪斯·河角的信交給湖畔鎮的所羅門鎮長。"},
[4184]={"真正的主人","到暴風城去把所羅門的求援信交給伯瓦爾·弗塔根公爵。 伯瓦爾在暴風要塞裏。"},
[4185]={"真正的主人","與女伯爵卡特拉娜·普瑞斯托談話，然後再與伯瓦爾·弗塔根公爵談話。"},
[4186]={"真正的主人","把伯瓦爾的命令交給湖畔鎮的所羅門鎮長。"},
[4201]={"愛情藥水","將4份格羅姆之血、10塊巨型銀礦和裝滿水的娜瑪拉之瓶交給黑石深淵的娜瑪拉小姐。"},
[4223]={"真正的主人","和燃燒平原的麥克斯韋爾元帥談壹談。"},
[4224]={"真正的主人","和狼狽不堪的約翰談談來了解溫德索爾元帥的命運，然後回到麥克斯韋爾元帥那裏。 妳想起麥克斯韋爾元帥說過他在壹個北面的洞穴那裏。"},
[4241]={"溫德索爾元帥","到西北部的黑石山脈去，在黑石深淵中找到溫德索爾元帥的下落。 狼狽不堪的約翰曾告訴妳說溫德索爾被關進了壹個監獄。"},
[4242]={"被遺棄的希望","把這個壞消息傳達給麥克斯韋爾元帥。"},
[4262]={"征服者派隆","殺掉征服者派隆，然後向加琳達復命。 加琳達告訴過妳，派隆守在采礦場中，也許妳應該去那裏找找。"},
[4263]={"伊森迪奧斯！","在黑石深淵裏找到伊森迪奧斯，然後把他幹掉！"},
[4264]={"弄皺的便箋","溫德索爾元帥也許會對妳手中的東西感興趣。畢竟，希望還沒有被完全扼殺。"},
[4282]={"壹絲希望","找回溫德索爾元帥遺失的情報。 溫德索爾元帥確信那些情報在安格弗將軍和傀儡統帥阿格曼奇的手裏。"},
[4286]={"好東西","到黑石深淵去找到20個黑鐵挎包。當妳完成任務之後，回到奧拉留斯那裏復命。妳認為黑石深淵裏的黑鐵矮人應該會有這些黑鐵挎包。"},
[4322]={"沖破牢籠！","幫助溫德索爾元帥拿回他的裝備並救出他的朋友。當妳成功之後就回去向麥克斯韋爾元帥復命。"},
[4341]={"卡蘭·巨錘","去黑石深淵找到卡蘭·巨錘。 國王提到卡蘭在那裏負責看守囚犯——也許妳應該在監獄附近尋找他。"},
[4342]={"卡蘭的故事","聽卡蘭·巨錘說他的故事。"},
[4361]={"糟糕的消息","回到鐵爐堡，把這個壞消息帶給國王麥格尼·銅須。"},
[4362]={"王國的命運","回到黑石深淵，從達格蘭·索瑞森大帝的魔掌中救出鐵爐堡公主茉艾拉·銅須。"},
[4701]={"座狼之源","到黑石塔去摧毀那裏的座狼源頭。當妳離開的時候，赫林迪斯喊出了壹個名字：哈雷肯。這個詞就是獸人語中“座狼”的意思。"},
[4724]={"座狼的首領","殺死血斧座狼的領袖，哈雷肯。"},
[4726]={"雛龍精華","將龍靈采集器900型和8份雛龍精華交給燃燒平原烈焰峰的丁奇·斯迪波爾。"},
[4729]={"基布雷爾的特殊寵物","到黑石塔去找到血斧座狼幼崽。使用籠子來捕捉這些兇猛的小野獸，然後把籠中的座狼幼崽交給基布雷爾。"},
[4734]={"冷凍龍蛋","在孵化間對著某顆龍蛋使用龍蛋冷凍器初號機。"},
[4735]={"收集龍蛋","將電動采集模塊和8顆收集到的龍蛋交給燃燒平原烈焰峰的丁奇·斯迪波爾。"},
[4742]={"晉升印章","找到三塊命令寶石：燃棘寶鉆、尖石寶鉆和血斧寶鉆。把它們和原始晉升印章壹起交給維埃蘭。 可能攜帶者三塊寶石的將軍是：燃棘氏族的指揮官沃恩、尖石氏族的歐莫克大王，以及血斧氏族的維姆薩拉克。"},
[4764]={"末日扣環","將末日扣環交給燃燒平原的瑪亞拉·布萊特文。"},
[4768]={"黑暗石板","將黑暗石板交給卡加斯的暗法師薇薇安·拉格雷。"},
[4771]={"黎明先鋒","將黎明先鋒放在通靈學院的觀察室裏。打敗維克圖斯，然後回到貝蒂娜·比格辛克那裏去。"},
[4787]={"遠古之卵","將遠古之卵交給塔納利斯的葉基亞。"},
[4788]={"最後的石板","將第五塊和第六塊摩沙魯石板交給塔納利斯的勘查員詹斯·鐵靴。"},
[4808]={"菲諾克","把丁奇的信交給菲諾克。"},
[4809]={"冰風奇美拉角","將8支完整的冰風奇美拉角交給菲諾克。"},
[4810]={"返回丁奇身邊","把菲諾克的包裹交給燃燒平原的丁奇·斯迪波爾。"},
[4862]={"蜘蛛卵","到黑石塔去為基布雷爾收集15枚尖塔蜘蛛卵。 聽說那些蜘蛛周圍有許多這樣的卵。"},
[4866]={"蛛後的乳汁","妳可以在黑石塔的中心地帶找到煙網蛛後。與她戰鬥，讓她在妳體內註入毒汁。如果妳有能力的話，就殺死她吧。當妳中毒之後，回到狼狽不堪的約翰那兒，他會從妳的身體裏抽取這些“蛛後的乳汁”。"},
[4867]={"烏洛克","閱讀瓦羅什的卷軸。將瓦羅什的蟑螂交給他。"},
[4903]={"高圖斯的命令","殺死歐莫克大王、指揮官沃恩和維姆薩拉克。找到重要的黑石文件，然後向卡加斯的軍官高圖斯匯報。"},
[4907]={"丁奇·斯迪波爾","與丁奇·斯迪波爾談壹談。"},
[4941]={"伊崔格的智慧","和奧格瑞瑪的伊崔格談壹談。討論完畢後，咨詢薩爾的意見。 妳回憶起曾在薩爾的大廳中見過伊崔格。"},
[4974]={"為部落而戰！","去黑石塔殺死大酋長雷德·黑手，帶著他的頭顱返回奧格瑞瑪。"},
[4981]={"狡猾的比修","到黑石塔去查明比修的下落。"},
[4982]={"比修的裝置","找到比修的裝置並把它們還給她。妳記得她說過她把裝置藏在城市的最底層。"},
[4983]={"比修的偵察報告","把比修的偵查報告交給卡加斯的雷克斯洛特。"},
[5001]={"比修的裝置","找到比修的裝置並把它們還給她。祝妳好運！"},
[5002]={"給麥克斯韋爾的消息","到燃燒平原去，把比修的情報交給麥克斯韋爾元帥。"},
[5047]={"皮普·捷思，為您效勞！","與永望鎮的瑪雷弗斯·暗錘談壹談。"},
[5065]={"失落的摩沙魯石板","把第三塊和第四塊摩沙魯石板交給塔納利斯的勘查員詹斯·鐵靴。"},
[5081]={"麥克斯韋爾的任務","到黑石塔去消滅指揮官沃恩、歐莫克大王和維姆薩拉克。完成任務之後回到麥克斯韋爾元帥處復命。"},
[5089]={"達基薩斯將軍的命令","把達基薩斯將軍的命令交給燃燒平原的麥克斯韋爾元帥。"},
[5102]={"達基薩斯將軍之死","到黑石塔去殺掉達基薩斯將軍，完成任務之後就回到麥克斯韋爾元帥那裏復命。"},
[5122]={"信仰獎章"},
[5125]={"奧裏克斯的清算"},
[5127]={"惡魔熔爐","到黑石塔去找到古拉魯克。殺死他，然後用血汙長矛刺入他的屍體。當他的靈魂被吸幹後，這支矛就會成為穿魂長矛。 妳還必須找到未鑄造的符文覆飾胸甲。 將穿魂長矛和未鑄造的符文覆飾胸甲都交給冬泉谷的羅拉克斯。"},
[5160]={"監護者","到冬泉谷去找到哈爾琳，把奧比的鱗片交給她。"},
[5212]={"血肉不會撒謊","從斯坦索姆找回20個瘟疫肉塊，並把它們交給貝蒂娜·比格辛克。妳覺得斯坦索姆中的生靈都不大可能長著肉……"},
[5213]={"活躍的探子","到斯坦索姆去探索那裏的通靈塔。找到新的天災軍團檔案，把它交給貝蒂娜·比格辛克。"},
[5214]={"弗拉斯·希亞比","找到弗拉斯·希亞比在斯坦索姆的煙草店，並從中找回壹盒希亞比的煙草，把它交給煙鬼拉魯恩。"},
[5243]={"神聖之屋","到北方的斯坦索姆去，尋找散落在城市中的補給箱，並收集5瓶斯坦索姆聖水。當妳找到足夠的聖水之後就回去向萊尼德·巴薩羅梅復命。"},
[5244]={"凱斯利爾廢墟","與墜星村的加隆·石矛談壹談。"},
[5245]={"凱斯利爾的怨靈","使用加隆的鎬來尋找四塊上層精靈遺物的碎片，把它們交給東瘟疫之地的奧蘿拉。"},
[5246]={"歷史的殘片","在艾薩拉的辛瑪洛神殿裏找到神聖的上層精靈筆跡，並將它帶給位於東瘟疫之地的北地哨塔附近的奧蘿拉。"},
[5247]={"歷史的殘片","給東瘟疫之地的奧蘿拉帶去壹塊魔化瑟銀錠、5塊恢復水晶，以及壹小瓶恐怖之水。"},
[5251]={"檔案管理員","在斯坦索姆城中找到血色十字軍的檔案管理員加爾福特，殺掉他，然後燒毀血色十字軍檔案。"},
[5262]={"可怕的真相","將巴納紮爾的頭顱交給東瘟疫之地的尼古拉斯·瑟倫霍夫公爵。"},
[5263]={"超越","到斯坦索姆去殺掉瑞文戴爾男爵，把他的頭顱交給尼古拉斯·瑟倫霍夫公爵。"},
[5281]={"永不安息的靈魂","找到埃根。妳只知道他在斯坦索姆附近。"},
[5282]={"永不安息的靈魂","對斯坦索姆城中的鬼魂使用埃根的沖擊器。當那些永不安息的靈魂掙脫他們的外殼時，再次使用埃根的沖擊器——他們就可以獲得自由了！ 解放15個永不安息的靈魂，然後回到埃根那裏去。"},
[5341]={"巴羅夫家族的寶藏","到通靈學院中去取得巴羅夫家族的寶藏。這份寶藏包括四份地契：凱爾達隆地契、布瑞爾地契、塔倫米爾地契，還有南海鎮地契。完成任務之後就回到阿萊克斯·巴羅夫那兒去。"},
[5343]={"巴羅夫家族的寶藏","到通靈學院中去取得巴羅夫家族的寶藏。這份寶藏包括四份地契：凱爾達隆地契、布瑞爾地契、塔倫米爾地契，還有南海鎮地契。完成任務之後就回到維爾頓·巴羅夫那兒去。"},
[5382]={"瑟爾林·卡斯迪諾夫教授","在通靈學院中找到瑟爾林·卡斯迪諾夫教授。殺死他，並燒毀艾瓦·薩克霍夫和盧森·薩克霍夫的遺體。任務完成後就回到艾瓦·薩克霍夫那兒。"},
[5384]={"傳令官基爾圖諾斯","帶著無辜者之血回到通靈學院，將它放在門廊的火盆下面，基爾圖諾斯會前來吞噬妳的靈魂。 勇敢地戰鬥吧，不要退縮！殺死基爾圖諾斯，然後回到艾瓦·薩克霍夫那兒。"},
[5461]={"萊斯·霜語","到阿拉希高地的激流堡遺跡裏面尋找巫妖生前的遺物。如果妳能找到這樣的東西，就把它交給馬杜克鎮長。"},
[5462]={"亡靈萊斯·霜語","到東瘟疫之地的聖光之願禮拜堂去找到萊尼德·巴薩羅梅，給他看看巫妖生前的遺物，並告訴他妳收集到的情報。"},
[5463]={"米奈希爾的禮物","到斯坦索姆城裏去找到米奈希爾的禮物，把巫妖生前的遺物放在那塊邪惡的土地上。"},
[5464]={"米奈希爾的禮物","把禁錮靈魂的遺物交給東瘟疫之地的萊尼德·巴薩羅梅。"},
[5465]={"禁錮靈魂的遺物","回到凱爾達隆的馬杜克鎮長那裏，把禁錮靈魂的遺物交給他。"},
[5466]={"巫妖萊斯·霜語","在通靈學院裏找到萊斯·霜語。當妳找到他之後，使用禁錮靈魂的遺物破除其亡靈的外殼。如果妳成功地破除了他的不死之身，就殺掉他並拿到萊斯·霜語的頭顱。把那個頭顱交給馬杜克鎮長。"},
[5515]={"卡斯迪諾夫的恐懼之袋","在通靈學院找到詹迪斯·巴羅夫並打敗她。從她的屍體上找到卡斯迪諾夫的恐懼之袋，然後將其交給艾瓦·薩克霍夫。"},
[5522]={"萊尼德·巴薩羅梅","把冰凍的龍蛋交給東瘟疫之地的萊尼德·巴薩羅梅。"},
[5526]={"魔藤碎片","在厄運之槌中找到魔藤，然後從它上面采集壹塊碎片。只有幹掉了奧茲恩之後，妳才能進行采集工作。使用凈化之匣安全地封印碎片，然後將其交給月光林地永夜港的拉比恩·薩圖納。"},
[5527]={"凈化之匣","到希利蘇斯的南風村去尋找凈化之匣。然後將其交給月光林地永夜港的拉比恩·薩圖納。"},
[5529]={"瘟疫之龍","殺掉20只瘟疫龍崽，然後向聖光之願禮拜堂的貝蒂娜·比格辛克復命。"},
[5531]={"貝蒂娜·比格辛克","將冰凍的龍蛋交給貝蒂娜·比格辛克。"},
[5533]={"通靈學院","和西瘟疫之地冰風崗的化學家阿爾比頓談壹談。"},
[5722]={"尋找背包","在怒焰裂谷搜尋瑪爾·恐怖圖騰的屍體以及他留下的東西。"},
[5723]={"試探敵人","在奧格瑞瑪找到怒焰裂谷，殺掉8個怒焰穴居人和8個怒焰薩滿祭司，然後向雷霆崖的拉哈羅復命。"},
[5724]={"歸還背包","將恐怖圖騰背包交給雷霆崖的拉哈羅。"},
[5725]={"毀滅之力","將《暗影法術研究》和《扭曲虛空的魔法》這兩本書交給幽暗城的瓦裏瑪薩斯。"},
[5726]={"隱藏的敵人","將軍官的徽章交給奧格瑞瑪的薩爾。"},
[5727]={"隱藏的敵人","將軍官的徽章交給尼爾魯·火刃並與他談壹談，看看他是否相信妳是火刃氏族中的壹員，然後回到奧格瑞瑪的薩爾那裏。"},
[5728]={"隱藏的敵人","殺死巴紮蘭和祈求者耶戈什，然後回到奧格瑞瑪的薩爾那裏。"},
[5761]={"饑餓者塔拉加曼","進入怒焰裂谷，殺死饑餓者塔拉加曼，然後把他的心臟交給奧格瑞瑪的尼爾魯·火刃。"},
[5848]={"愛與家庭","到瘟疫之地北部的斯坦索姆去。妳可以在血色十字軍堡壘中找到“愛與家庭”這幅畫，它被隱藏在另壹幅描繪兩個月亮的畫之後。 把這幅畫還給提裏奧·弗丁。"},
[6022]={"殺戮的理由","到東邊的考林路口去屠殺鎮裏的亡靈天災。在10分鐘內收集7塊生命腐質，使用研缽和搗杵將其研磨成凝固腐質。"},
[6042]={"討厭的蝙蝠","殺掉20只毒性瘟疫蝙蝠和10只巨型瘟疫蝙蝠，然後回到納薩諾斯·雕零者那裏。"},
[6133]={"遊俠之王的命令","到東瘟疫之地的北方邊界去找回奎爾薩拉斯名冊，這件物品在奎爾林斯小屋的某處。 另外妳還必須殺掉8個遊俠、8個巡路者和8個護林者。"},
[6135]={"暗翼蝠","找到暗翼蝠並殺掉它。從屍體上取下壹塊暗翼蝠的皮，並把它交給納薩諾斯·雕零者。 據說暗翼蝠遊蕩在瑪瑞斯農場北面的荒原上。"},
[6136]={"肥大的食腐蟲","找到東瘟疫之地北方荒原中的淤血蟲並消滅它。任務完成之後，向納薩諾斯·雕零者復命。"},
[6163]={"吞咽者拉姆斯登","到斯坦索姆去，殺掉吞咽者拉姆斯登。把他的頭顱交給納薩諾斯。"},
[6402]={"集合在暴風城","前往暴風城的城門。與侍衛洛文交談，他會通知溫德索爾元帥妳已經到達了。"},
[6403]={"潛藏者","跟隨雷吉納德·溫德索爾元帥在暴風城中前進。保護他，別讓他受到傷害！"},
[6501]={"巨龍之眼","妳必須尋遍世界以找到壹種能恢復龍眼碎片的能量的生物。妳對這種生物的唯壹了解就是：他們確實存在。"},
[6502]={"龍火護符","妳必須從達基薩斯將軍身上取回黑龍勇士之血，妳可以在黑石塔的晉升大廳後面的房間裏找到他。"},
[6521]={"邪惡的盟友","把瑪克林大使的頭顱交給幽暗城的瓦裏瑪薩斯。"},
[6522]={"邪惡的盟友","把小卷軸交給幽暗城的瓦裏瑪薩斯。"},
[6561]={"黑暗深淵中的邪惡","把夢遊者克爾裏斯的頭顱交給雷霆崖的巴珊娜·符文圖騰。"},
[6562]={"幫助耶努薩克雷","與灰谷的耶努薩克雷談壹談。"},
[6563]={"阿庫麥爾水晶","收集20顆阿庫麥爾藍寶石，把它們交給灰谷的耶努薩克雷。"},
[6564]={"上古之神的仆從","把潮濕的便箋交給灰谷的耶努薩克雷。"},
[6565]={"上古之神的仆從","殺掉黑暗深淵裏的洛古斯·傑特，然後向灰谷的耶努薩克雷復命。"},
[6566]={"風吹來的消息","聽薩爾講話。"},
[6567]={"部落的勇士","按照酋長的指示找到雷克薩。他在石爪山和菲拉斯之間的淒涼之地遊蕩。"},
[6568]={"雷克薩的證明","把雷克薩的證明交給西瘟疫之地的巫女麥蘭達。"},
[6569]={"黑龍幻象","到黑石塔去收集20顆黑色龍人的眼球，完成任務之後回到巫女麥蘭達那裏。"},
[6570]={"埃博斯塔夫","到塵泥沼澤中的巨龍沼澤去，找到埃博斯塔夫的洞穴。進入洞穴之後戴上龍形護符，然後跟埃博斯塔夫交談。"},
[6582]={"龍骨試煉，斯克利爾","找到藍龍斯克利爾並殺掉他。從他的身上取下他的顱骨，然後將其交給埃博斯塔夫。 妳可以在冬泉谷找到斯克利爾。"},
[6583]={"龍骨試煉，索姆努斯","殺掉綠龍索姆努斯，把他的顱骨交給埃博斯塔夫。"},
[6584]={"龍骨試煉，克魯納裏斯","諾茲多姆的孩子克魯納裏斯在塔納利斯沙漠守衛著時光之穴。殺了他，把他的顱骨交給埃博斯塔夫。"},
[6585]={"龍骨試煉，埃克托茲","到格瑞姆巴托去殺掉紅龍埃克托茲，把他的顱骨交給埃博斯塔夫。"},
[6601]={"晉升……","看來這場假面舞會就要結束了。妳知道麥蘭達為妳制作的龍形護符在黑石塔裏面不會發揮作用，也許妳應該去找雷克薩，將妳的困境告訴他。把黯淡的龍火護符給他看看，也許他知道下壹步該怎麽做。"},
[6602]={"黑龍勇士之血","到黑石塔去殺掉達基薩斯將軍，把它的血交給雷克薩。"},
[6626]={"邪惡之地","殺掉8個剃刀沼澤護衛者、8個剃刀沼澤織棘者和8個亡首教徒，然後向剃刀高地入口處的麥雷姆·月歌復命。"},
[6627]={"知識試煉","成功回答布勞格·幽魂的問題，然後和他再次對話。他會壹直在石爪山等妳回答問題。"},
[6628]={"知識試煉","成功回答帕科瓦·芬塔拉斯的問題，然後再次和他對話。他會壹直在幽暗城等妳回答問題。"},
