[6643]={"兄弟會的好感 - 熾熱之核"},
[6644]={"兄弟會的好感 - 熔巖之核"},
[6645]={"兄弟會的好感 - 熔火犬皮"},
[6646]={"兄弟會的好感 - 山脈之血"},
[6804]={"被囚禁的水元素","對東瘟疫之地的被感染的水元素使用海神之水。把12副不諧護腕和海神之水交給艾薩拉的海達克西斯公爵。"},
[6805]={"雷暴和磐石","殺死15個灰塵風暴和15個沙漠奔行者，然後回到艾薩拉的海達克西斯公爵那兒。"},
[6821]={"艾博希爾之眼","將艾博希爾之眼交給艾薩拉的海達克西斯公爵。"},
[6822]={"熔火之心","殺死壹個火焰之王、壹個熔巖巨人、壹個上古熔火惡犬和壹個熔巖奔騰者，然後回到艾薩拉的海達克西斯公爵那裏。"},
[6823]={"海達克西斯的使者","在海達希亞水元素中達到被尊敬的聲望，然後與艾薩拉的海達克西斯公爵談壹談。"},
[6824]={"敵人之手","將魯西弗隆之手、薩弗隆之手、基赫納斯之手和沙斯拉爾之手交給艾薩拉的海達克西斯公爵。"},
[6921]={"廢墟之間","把深淵之核交給灰谷佐拉姆加前哨站裏的耶努薩克雷。"},
[6922]={"阿奎尼斯男爵","把奇怪的水球交給灰谷佐拉姆加前哨站的耶努薩克雷。"},
[6981]={"發光的碎片","尋找更多有關這塊噩夢碎片的信息。"},
[7028]={"扭曲的邪惡","為淒涼之地的維洛收集25個瑟萊德絲水晶雕像。"},
[7029]={"維利塔恩的汙染","在瑪拉頓裏用天藍水瓶在橙色水晶池中裝滿水。 在維利斯塔姆藤蔓上使用裝滿水的天藍水瓶，使墮落的諾克賽恩幼體出現。 治療8株植物並殺死那些諾克賽恩幼體，然後向葬影村的瓦克·戰痕復命。"},
[7041]={"維利塔恩的汙染","在瑪拉頓裏用天藍水瓶在橙色水晶池中裝滿水。 在維利斯塔姆藤蔓上使用裝滿水的天藍水瓶，使墮落的諾克賽恩幼體出現。 治療8株植物並殺死那些諾克賽恩幼體，然後向尼耶爾前哨站的塔琳德莉亞復命。"},
[7044]={"瑪拉頓的傳說","找回塞雷布拉斯節杖的兩個部分：塞雷布拉斯魔棒和塞雷布拉斯鉆石。 然後設法和塞雷布拉斯對話。"},
[7046]={"塞雷布拉斯節杖","幫助贖罪的塞雷布拉斯制作塞雷布拉斯節杖。 當儀式完成之後再和他談談。"},
[7064]={"大地的汙染","殺死瑟萊德絲公主，然後回到淒涼之地葬影村附近的瑟琳德拉那裏復命。"},
[7065]={"大地的汙染","殺死瑟萊德絲公主，然後回到淒涼之地尼耶爾前哨站的守護者瑪蘭迪斯那裏復命。"},
[7066]={"生命之種","到月光林地去找到雷姆洛斯，將生命之種交給他。"},
[7067]={"賤民的指引","閱讀賤民的指引，然後從瑪拉頓得到聯合墜飾，將其交給淒涼之地南部的半人馬賤民。"},
[7068]={"暗影殘片","從瑪拉頓收集10塊暗影殘片，然後把它們交給奧格瑞瑪的尤塞爾奈。"},
[7070]={"暗影殘片","從瑪拉頓收集10塊暗影殘片，然後把它們交給塵泥沼澤塞拉摩島上的大法師特沃什。"},
[7201]={"最後的元素","到黑石深淵去取得10份元素精華。妳應該在那些作戰傀儡和傀儡制造者身上找找，另外，薇薇安·拉格雷也提到了壹些有關元素生物的話題……"},
[7441]={"普希林和埃斯托爾迪","到厄運之槌去找到小鬼普希林。妳可以使用任何手段從小鬼那裏得到埃斯托爾迪的咒術之書。 找到咒術之書後，回到拉瑞斯小亭的埃斯托爾迪那裏。"},
[7461]={"伊莫塔爾的瘋狂","妳必須幹掉5座水晶塔周圍的守衛，那5座水晶塔維持著關押伊莫塔爾的監獄。壹旦水晶塔的能量被削弱，伊莫塔爾周圍的能量力場就會消散。 進入伊莫塔爾的監獄，幹掉站在中間的那個惡魔。最後，在圖書館挑戰托塞德林王子。 當任務完成之後，到庭院中去找辛德拉古靈。"},
[7462]={"辛德拉的寶藏","返回圖書館去找到辛德拉的寶藏。拿取妳的獎勵吧！"},
[7463]={"久違的法師","到厄運之槌的扭木廣場去殺掉水元素海多斯博恩。把海多斯博恩精華交給圖書館的博學者萊德羅斯。"},
[7481]={"精靈的傳說","到厄運之槌去尋找卡裏爾·溫薩魯斯。向莫沙徹營地的先知科魯拉克報告妳所找到的信息。"},
[7482]={"精靈的傳說","到厄運之槌去尋找卡裏爾·溫薩魯斯。向羽月要塞的學者盧索恩·紋角報告妳所找到的信息。"},
[7486]={"英雄的獎賞","從海達克西斯的箱子拿取妳的獎勵。"},
[7488]={"蕾瑟塔蒂絲的網","把蕾瑟塔蒂絲的網交給菲拉斯羽月要塞的拉托尼庫斯·月矛。"},
[7489]={"蕾瑟塔蒂絲的網","把蕾瑟塔蒂絲的網交給非拉斯莫沙徹營地的塔羅·刺蹄。"},
[7490]={"部落的勝利","將奧妮克希亞的頭顱交給奧格瑞瑪的薩爾。"},
